  FT["PH-H18653"] = {"id":"PH-H18653","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1970/eo_222_1970.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Council of Leaders","orig":"Creating the Council of Leaders"},"level":"law","status":"active","docNumber":"Executive Order No. 222","issuingBody":"President of the Philippines","promulgatedDate":"1970-03-21","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00222_1970_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00222_1970_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18653-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 222, March 21, 1970 ]\nCREATING THE COUNCIL OF LEADERS\nWHEREAS, it is imperative that the President of the Philippines be advised on all matters requiring policy\npronouncements on national issues and problems and on actions he has to take on the same;\nWHEREAS, there are presently two such advisory bodies – the Council of State and the Council of Leaders –\nwhose functions and members are more or less identical and overlapping and duplicating each other; and\nWHEREAS, to achieve better coordination of activities and more fruitful results, it is advisable that there be\nonly one policy-making and consultative body to the President;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby organize the Council of Leaders to be composed of the following:\n1. The Vice President,\n2. The President of the Senate,\n3. The Speaker of the House of Representatives,\n4. The President, Governors and City Mayors League of the Philippines,\n5. The Former Presidents of the Republic of the Philippines,\n6. The Presidents of the Political Parties which had candidates on a nation-wide scale in the last elections,\n7. The Chairman of the Committees of both Houses of Congress whose functions are relevant to the subject\nmatter to be discussed in the Council, and\n8. The members of the Cabinet the functions of whose departments are relevant to the subject matter to be\ndiscussed in the Council.\nThe Council shall perform the functions presently being discharged by the Council of State which is hereby\nThe Cabinet Secretariat shall serve as permanent Secretariat of the Council and is hereby charged with the\nresponsibility of preparing all implementing actions on, and the following-up of, all matters taken up by the\nCouncil, and keeping the President regularly informed of all action taken thereon.\nDone in the City of Manila, this 21st day of March, in the year of Our Lord, nineteen hundred and seventy.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) ALEJANDRO MELCHOR\nActing Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18654"] = {"id":"PH-H18654","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PROVIDING FOR A NEW PERIOD FOR THE APPLICATION OF EXECUTIVE ORDER NO. 107 DATED DECEMBER 24,","orig":"MALACAÑANG PROVIDING FOR A NEW PERIOD FOR THE APPLICATION OF EXECUTIVE ORDER NO. 107 DATED DECEMBER 24,"},"level":"law","status":"active","docNumber":"Executive Order No. 222","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00222_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00222_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18654-A1","no":1,"noLabel":{},"text":{"en":"immediately.\nThig Executive Order shall take effect\nDone in the City of Manila, this 15th day\nIn the year of Our Lords\n• nine&cen hundred and eisht\n*ecutive Secretary"}}],"pack":"ph-p158"};
