  FT["PH-H18767"] = {"id":"PH-H18767","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Placing the Kilusang Kabuhayan At Kaunlaran (KKK) Capital and Its Earnings Under the Control and Supervision of the Office of the President and for Other Purposes","orig":"Placing the Kilusang Kabuhayan At Kaunlaran (KKK) Capital and Its Earnings Under the Control and Supervision of the Office of the President and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 238","issuingBody":"President of the Philippines","promulgatedDate":"1987-07-22","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00238_1987_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00238_1987_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18767-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Kilusang Kabuhayan at Kaunlaran (KKK) Capital Fund/National Livelihood Support Fund shall\nbe exclusively utilized for the promotion generation and development of livelihood opportunities under the\ncontrol and supervision of the Office of the President."}},{"id":"PH-H18767-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Central Bank of the Philippines, the KKK-designated banks and other persons or entities dealing\nwith the KKK Capital Fund/National Livelihood Support Fund are hereby directed to deliver to the Office of\nthe President all or part of said funds, including their earnings, in their possession or control."}},{"id":"PH-H18767-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Consistent with the purpose of the KKK Capital Fund/National Livelihood Support Fund, the Office of\nthe President shall consolidate said funds or transfer or distribute the same to different accounts or cause the\ndeposit thereof in one or more depositories."}},{"id":"PH-H18767-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The Office of the President shall establish new fund delivery systems in addition to or in lieu of\nexisting ones, and all releases of funds shall be in accordance and consistent with such delivery systems and\nthe policies, rules and regulations now existing or that may hereafter be issued by the Office of the President\nto implement the purpose of the Executive Order."}},{"id":"PH-H18767-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"All orders, issuances, rules and regulations or parts thereof inconsistent with this Executive Order are\nhereby repealed or modified accordingly."}},{"id":"PH-H18767-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Any portion or provision of this Executive Order that may be declared unconstitutional shall not have\nthe effect of nullifying other portions or provisions hereof as long as such remaining portion or provision can\nstill subsist and be given effect in their entirety."}},{"id":"PH-H18767-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"This Executive Order shall take effect immediately.\n\nDONE in the City of Manila, this 22nd day of July, in the year of Our Lord, nineteen hundred and\neighty-seven."}}],"pack":"ph-p158"};
  FT["PH-H18768"] = {"id":"PH-H18768","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE PAGBILAO PORT ZONE UNDER THE ADMINISTRATIVE JURISDICTION PHILIPPINE PORTS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE PAGBILAO PORT ZONE UNDER THE ADMINISTRATIVE JURISDICTION PHILIPPINE PORTS"},"level":"law","status":"active","docNumber":"Executive Order No. 238","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00238_1995.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00238_1995.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18768-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"AIl other orders, proclamations,\nissuances, or portions thereof, which are inconsistent with\nthis Executive Order, are hereby repealed or modified\naccordingly."}},{"id":"PH-H18768-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"This Executive\nOrder shall take effect\nimmediately.\nDone in the City of Manila, this 24th day of April, in\nthe year of Our Lord, nineteen hundred and ninety five.\nBy the President:\nGUINGONA, JR.\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18769"] = {"id":"PH-H18769","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"EXECUTIVE ORDER NO.~1j THE RATES OF DUTY ON CERTAIN IMPORTED AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS TO IMPLEMENT THE PREFERENTIAL INDUSTRIAL COOPERATION (AICO) SCHEME","orig":"EXECUTIVE ORDER NO.~1j THE RATES OF DUTY ON CERTAIN IMPORTED AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS TO IMPLEMENT THE PREFERENTIAL INDUSTRIAL COOPERATION (AICO) SCHEME"},"level":"law","status":"active","docNumber":"Executive Order No. 238","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00238_2000.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00238_2000.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18769-A402","no":402,"noLabel":{"en":"Section 402"},"text":{"en":"of the Tariff and Customs Code of 1978, as amended, do hereby\n1.\nThe articles\nspecifically\nlisted in Annex \"A\" hereof, as\nclassified\nunder Section\n104 of the Tariff and Customs Code of 1978, as\nshall be accorded the AICa rate of 5% as specified in Column 4thereof.\nSECTION 2. The AlGa rate provided in Annex \"A\" shall be accorded to\nentity in Malaysia (Malaysia Packaging Industry Bhd.) effective 03\nSECTION 3. In the event that any subsequent changes are made in the\nbasic (MFN) Philippine rate of duty on the articles listed in Annex \"A\" to a rate\nlower than the AICa rate prescribed\nin Column 4 thereof, such article shall\nautomatically\nbe accorded the corresponding\nreduced rate of duty.\n01 January 2003, the final CEPT rate on the subject article shall apply.\nSECTION 4. Upon the effectivity of this Executive Order, the articles\nspecifically\nlisted in the aforesaid Annex \"A\" which are entered or withdrawn\nfrom warehouses\nin the Philippines for consumption\nshall pay the applicable\nAICO preferential\ntariff rates specified\nunder Section 1 hereof,\nqualification\nunder the Rules of Origin for the CEPT, as evidenced\nCertificate\nof Origin -Form \"0\",\nThis Executive Order shall take effect immediately.\nDone in the City of Manila, this ~Lord,\nTwo Thousand.\nin the year of Our\nBy the President:\nExecutive Secretary\n(!~~?\n\"\"--11111111111111111111111111111111111\n\"\"\".\",'17242"}}],"pack":"ph-p158"};
  FT["PH-H18770"] = {"id":"PH-H18770","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES AND FUNCTIONS AND MEMBERSHIP OF THE NATIONAL STEERING COMMITTEE OF THE FAMILY WEEK","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES AND FUNCTIONS AND MEMBERSHIP OF THE NATIONAL STEERING COMMITTEE OF THE FAMILY WEEK"},"level":"law","status":"active","docNumber":"Executive Order No. 238","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00238_2003.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00238_2003.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18770-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Purposes of the National Steering Committee on the\nFilipino Family. The National Steering Committee on the Filipino Family shall\npromote the family as the foundation of the nation, its basic social institution, as\nwell as the protection of marriage as the foundation of the family. If shall\nlikewise provide opportunities for partnership with private sector particularly civic\nand religious, marriage and family organizations, educational institutions and\nmedia groups in promoting the goals and objectives of the Council."}},{"id":"PH-H18770-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Powers and Functions. The National Steering Committee on\nthe Filipino Family shall have the following powers and functions:\n2.1\nTo formulate policies, plan and promote strategies for an effective\nnational program on the family;\n2.2\nTo draw up a mechanism between and among the various national\ndepartment and local government units, and the private sector\nparticularly civic and religious, marriage and family organizations,\neducational institutions and media groups for the mobilization,\ncoordination, monitoring and evaluation of effective family life\n2.3 To conduct studies, researches and cause the publication of articles\nand books on marriage family;\n2.4\nTo encourage opportunities for training on human relations\ndevelopment among groups and individual engaged in family life\n2.5\nTo set up and administer a national family development fund for its\nprograms and projects;\n2.6\nTo plan, coordinate and evaluate the yearly celebration of the\nNational Family Week (Amends E.O. No. 241 and PP No. 60) the\nNational Family Thanksgiving Day (PP No. 847), the National\nMother's Day, the National Father's Day, the National Grandparents\nDay, the International Year of the Family, and such other\ncelebration for the family;\n2.7\nTo ensure the institutionalization of Family Week and Family\nThanksgiving Day through the participation of all concerned;\nPOMA Hologram / 22082\n\n2.8\nTo network with all concerned government agencies and non-\ngovernment organizations in the effective discharge of its\n2.9\nTo perform such powers and functions as necessary to carry out\nthe provisions of this Executive Order."}},{"id":"PH-H18770-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Composition. The National Steering Committee on the Filipino\nFamily shall be chaired by the Secretary of Social Welfare and Development of\nhis/her designated Undersecretary and a Vice-Chairperson who shall be elected\nfrom among the non-governmental organizations, civic and religious, marriage\nand family organizations, educational institutions and media groups represented\nand shall be composed of the following government agencies and private sector\n3.1 Government Agencies\n3.1.1 Department of Social Welfare and Development (DSWD)\n3.1.2 Department of Education (DepEd)\n3.1.3 Department of Health (DOH)\n3.1.4 Department of the Interior and Local Government (DILG)\n3.1.5 Commission on Higher Education (CHED)\n3.1.6 National Youth Commission (NYC)\n3.1.7 National Commission on the Role of Filipino Women\n3.1.8 National Commission on Indigenous Peoples (NCIP)\n3.1.9 Council for the Welfare of Children (CWC)\n3.1.10 Presidential Management Staff (PMS)\n3.1.11 Office of the Presidential Adviser for Special Concerns\n3.1.12 Office of the Muslim Affairs (OMA)\n3.1.13 Philippine Information Agency (PIA)\n3.1.14 Senate Committee on Youth Women and Family\n3.1.15 House Committee on Population and Family Relations\n3.2 Non-Government Entities\n3.2.1 CBCP Episcopal Commission on the Family and Life (ECFL)\n3.2.2 The Church of Jesus Christ of Latter-day Saints\n3.2.3 Iglesia ni Cristo\n3.2.4 National Council of Churches in the Philippines (NCCP)\n3.2.5 Kaisahang Buhay Foundation (KBF)\n3.2.6 Marriage Enhancement and Teams Services Foundation\n(METS Foundation)\nPOMd Hologram # 22083\n\n3.2.7 NORFIL Foundation\n3.2.8 National Council of Social Development Foundation, Inc.\n3.2.9 Family Life Institute Family Network\n3.2.10 Pro-Life Philippines Foundation\nThe National Steering Committee on the Filipino Family as the need arises\nmay invite government agencies and non-government organizations not\nmentioned above as additional members of the National Committee on the\nFilipino Family."}},{"id":"PH-H18770-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Funding. The necessary amount to be incurred in connection\nwith the implementation of this Order shall be primarily funded under the budget\nof the Department of Social Welfare and Development (DSWD) and secondarily\nshared by the government departments and agencies concerned, charged\nagainst their respective regular budgets. And, therefore, funds for the operation\nof the activities and programs, shall be included in the General Appropriations\nAct. Further, the National Steering Committee on the Filipino Family may engage\nin resource generation/mobilization activities as may be allowed by law to ensure\nthe success and continued operation of the National Steering Committee on the\nFilipino Family and its programs and projects.\nIN WITNESS WHEREOF, I have hereunto set my hand and caused the\nseal of the Republic of the Philippines to be affixed.\nDONE in the City of Manila, this 22ndday of September, in the year of Our\nLord, Two Thousand and Three.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE009614\nA A Hologram • 22084"}}],"pack":"ph-p158"};
  FT["PH-H18771"] = {"id":"PH-H18771","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1949/eo_239_1949.html","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Appropriating Additional Funds for the Operation of the Government of the Republic of the Philippines During the Period From July 1, 1949 to June 30, 1950, and for Other Purposes","orig":"Appropriating Additional Funds for the Operation of the Government of the Republic of the Philippines During the Period From July 1, 1949 to June 30, 1950, and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 239","issuingBody":"President of the Philippines","promulgatedDate":"1949-07-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00239_1949_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00239_1949_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18771-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sum of Eight hundred seventy-five thousands pesos, or so much thereof as may be\nnecessary, is hereby appropriated out of any funds in the Philippine Treasury not otherwise appropriated for\nthe following purposes:\n1. For continuing the health work and activities undertaken by the United States Public Health Service in the\nPhilippines\n2. For continuing the quarantine work to be taken over from the United States Public Health Service in\naccordance with the policy to relinquish gradually to the Philippine Government all activities now being\nundertaken and financed by the said Service under the Philippine Rehabilitation Act of 1946\n200,000.00\n3. For the operation and maintenance of international air communications, navigation services and radio aids\npaid for by the United States Government to be completely taken over by the Government of the Republic of\nthe Philippines on July 1, 1949\n225,000.00\n4. For the operation and maintenance of the Weather Bureau stations paid for by the United States\nGovernment to be completely taken over by the Government of the Republic of the Philippines on July 1,1949\n150,000.00"}},{"id":"PH-H18771-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The motor vehicles which are to be transferred by the agencies concerned of the United States to\nthe Republic of the Philippines and which are used by the Bureau of Health and the Bureau of Quarantine\nService for health, sanitation and quarantine work for the prevention and control of epedimics, shall continue\nto be operated and maintained for the same purposes by said Bureaus."}},{"id":"PH-H18771-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The special and general provisions of Republic Act No. 320 are hereby made applicable to the\nappropriations provided in this Executive Order."}},{"id":"PH-H18771-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Order shall take effect as of July 1, 1949.\nDone in the City of Manila, this 8th day of July, in the year of Our Lord, nineteen hundred and forty-nine, and\nof the Independence of the Philippines, the fourth.\n(SGD.) ELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\n(SGD.) TEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18772"] = {"id":"PH-H18772","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1970/eo_239_1970.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating An Executive Committee to Act as Advisory Council to the Fao Seminar on Measures to Accelerate Benefits From Water Use At the Farm Level to Be Held in Quezon City in October 1970","orig":"Creating An Executive Committee to Act as Advisory Council to the Fao Seminar on Measures to Accelerate Benefits From Water Use At the Farm Level to Be Held in Quezon City in October 1970"},"level":"law","status":"active","docNumber":"Executive Order No. 239","issuingBody":"President of the Philippines","promulgatedDate":"1970-06-22","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00239_1970_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00239_1970_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18772-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 239, June 22, 1970 ]\nCREATING AN EXECUTIVE COMMITTEE TO ACT AS ADVISORY COUNCIL TO THE FAO\nSEMINAR ON MEASURES TO ACCELERATE BENEFITS FROM WATER USE AT THE FARM\nLEVEL TO BE HELD IN QUEZON CITY IN OCTOBER 1970\nBy virtue of the powers vested in me by law, I, FERDINAND E. MARCOS, President of the Philippines, do\nhereby create an Executive Committee to act as Advisory Council to the FAO Seminar on Measures to\nAccelerate Benefits from Water Use at the Farm Level to be held in Quezon City in October 1970 composed\nof the following:\nThe Administration, National Irrigation Administration\nThe Executive Director, National food and Agriculture Council\nThe Director,Bureau of Plant Industry\nThe Commisioner,Agricultural Productivity Commission\nThe Director,Bureau of Solis\nThe Administration,Irrigation Service Unit\nThe Head,Water Resources Department, Bureau of Public Works\nThe Dean,U.P. College of Agriculture\nThe President,Central Luzon State University\nThe Committee may call upon any department, bureau, office, agency or instrumentality of the government,\nincluding government-owned or controlled corporations, for such assistance as it may need and create such\nsub-committees as may be necessary to ensure the success of the seminar.\nDone in the City of Manila, this 22nd day of June, in the year of Our Lord, nineteen hundred and seventy.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) PONCIANO G. A. MATHAY\nActing Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18773"] = {"id":"PH-H18773","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Reorganizing the Department of Foreign Affairs and for Other","orig":"Reorganizing the Department of Foreign Affairs and for Other"},"level":"law","status":"active","docNumber":"Executive Order No. 239","issuingBody":"President of the Philippines","promulgatedDate":"1987-07-24","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00239_1987_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00239_1987_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18773-A33","no":33,"noLabel":{"en":"Sec 33"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately upon its approval.\nAPPROVED in the City of Manila, Philippines, this 24th day of July, in the Year of Our Lord, nineteen\nhundred and eighty-seven."}}],"pack":"ph-p158"};
