  FT["PH-H18776"] = {"id":"PH-H18776","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"RATIONALIZING QUADRANGLE AREA AND DEFINING ITS POWERS, FUNCTIONS AND RESPONSIBILITIES","orig":"RATIONALIZING QUADRANGLE AREA AND DEFINING ITS POWERS, FUNCTIONS AND RESPONSIBILITIES"},"level":"law","status":"active","docNumber":"Executive Order No. 239","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00239_2003.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00239_2003.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18776-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Functions and Responsibilities\nof the Office of North\nLuzon Growth Quadrangle\nOffice of North Luzon Growth\nQuadrangle\nArea (ONL-GQA) shall have the following\nand'responsi\nMonitor the proper coordination of the development goals, policies\nand programs formulated\nfor the North Luzon Growth Quadrangle\nArea with the overall national goals, policies and. programs;\nPromote investments\nin the North Luzon Growth Quadrangle Area\nMobilize the participation\nof the local and national\ngovernment\nagencies, as well as non-government\norganizations\nand private\nsector groups;\ntrade and inves~ment\nin pursuance\nborder relations\nand conduct\nwith associations\nof Ilocanos\nMaintain linkages with central government offices and the official\ndevelopment assista~ce community;\nand conduct\nreview of the plans,\nfor the North Luzon Growth Quadrangle\nmatters concerning Ilocano and other indigenous peoples\naffairs and issues relative to the pursuit of the goals and objectives\nof the North Luzon Growth Quadrangle Area;\nand program\nof work of the\nProgram Management\nOffice-North\nLuzon Growth\nQuadrangleArea\nCall on ,any agency for any assistance and suppor1\nrelative to its plans, programs and projects."}},{"id":"PH-H18776-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Secretariat\nSupport for the Office of North LuzonGrowtfl\nQuadrangle Area.-The\nProgram Management Office of the North\nLuzon Growth Commission\n(PMO-NLGC) created under Executive OrderNo.\n28,\nact as secretariat\nto provideadminist\nand technical support.\n_:\",--'-'\",~~~~~\n~~~~1"}},{"id":"PH-H18776-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity.\nimmediately.\nCity of Manila, September\nBy the President\nALBERTO G. ROMULO\nExecutive Secretary\n~~!~!!~!~~1!\\11~~~~2"}}],"pack":"ph-p158"};
  FT["PH-H18777"] = {"id":"PH-H18777","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CONTINUING THE APPROPRIATIONS AUTHORIZED BY THE CONGRESS FOR THE OPERATION AND MAINTENANCE OF CERTAIN EXISTING ACTI- VITIES OR SERVICES OF THE GOVERNMENT OF THE REPUBLIC OF THE PHILIPPINES DUR- ING THE PERIOD FROM JULY 1, 1949 TO JUNE 30, 1950, AND FOR OTHER PURPOSES.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CONTINUING THE APPROPRIATIONS AUTHORIZED BY THE CONGRESS FOR THE OPERATION AND MAINTENANCE OF CERTAIN EXISTING ACTI- VITIES OR SERVICES OF THE GOVERNMENT OF THE REPUBLIC OF THE PHILIPPINES DUR- ING THE PERIOD FROM JULY 1, 1949 TO JUNE 30, 1950, AND FOR OTHER PURPOSES."},"level":"law","status":"active","docNumber":"Executive Order No. 240","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00240_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00240_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18777-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The special and general provisions of Republic\nAct No. 320 are hereby made applicable to the appro-\npriations provided in this Executive Order."}},{"id":"PH-H18777-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Order shall take effect as of July 1, 1949.\nDone in the City of Manila, this 8th day of July, in\nthe year of Our Lord, nineteen hundred and forty-nine,\nand of the Independence of the Philippines the fourth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18778"] = {"id":"PH-H18778","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1970/eo_240_1970.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Executive Order No. 212, Dated February 17, 1970, Entitled Creating the National Artificial Rain Stimulation Committee","orig":"Amending Executive Order No. 212, Dated February 17, 1970, Entitled Creating the National Artificial Rain Stimulation Committee"},"level":"law","status":"active","docNumber":"Executive Order No. 240","issuingBody":"President of the Philippines","promulgatedDate":"1970-06-25","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00240_1970_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00240_1970_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18778-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 240, June 25, 1970 ]\nAMENDING EXECUTIVE ORDER NO. 212, DATED FEBRUARY 17, 1970, ENTITLED “CREATING\nTHE NATIONAL ARTIFICIAL RAIN STIMULATION COMMITTEE.”\nI, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers vested in me by law, do\nhereby amend Executive Order No. 212, dated February 17, 1970, entitled “Creating the National Artificial\nRain Stimulation Committee” by adding the representatives of the following government agencies as\nmembers of the Committee namely, National Food and Agricultural Council (NFAC) and Research and\nDevelopment Center, Armed Forces of the Philippines.\nDone in the City of Manila, this 25th day of June, in the year of Our Lord, nineteen hundred and seventy.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) PONCIANO G. A. MATHAY\nActing Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18779"] = {"id":"PH-H18779","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG P M S LIBRARY PROVIDING FOR THE REORGANIZATION OF THE OFFICE OF THE VICE-PRESIDENT AND FOR OTHER PURPOSES","orig":"MALACAÑANG P M S LIBRARY PROVIDING FOR THE REORGANIZATION OF THE OFFICE OF THE VICE-PRESIDENT AND FOR OTHER PURPOSES"},"level":"law","status":"active","docNumber":"Executive Order No. 240","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00240_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00240_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18779-A1","no":1,"noLabel":{},"text":{"en":"of the Vice-President shall be appointed by the President, upon\nrecommendation of the Vice-President.\nthe chief of stare and the\nassistant chief or assistant chiefs of staff shall have the rank,\nsalary, allowance, emoluments and other privileges of a cabinet\nundersecretary and assistant secretary respectively and shall\nhold office at the pleasure of the vice-President.\n3. Separation from the Service.\nofficials and employees in the office of the vice-President who\nare not reappointed under the new structure and staffing pattern\nof the Office of the vice-President shall be deemed separated\nfrom the service and shall receive the retirement benefits to\nwhich they may be entitled under existing laws, rules and\nregulations.\nOtherwise, they shall be paid the equivalent of\none-month basic salary for every year of service or the\nequivalent nearest fraction thereof favorable to them on\nbasis of the highest salary received but in no case shall such\npayment exceed the equivalent of twelve (12) months salary.\nFunds needed to carry out the\nprovisions of this Executive\nOrder shall be taken fron funds\navailable in the Office of the Vice-President.\nRepealing Clause.\nAll laws, orders, issuances,\nrules and regulations or parts thereof inconsistent with this\nExecutive Order are hereby repealed or modified accordingly.\n6.\neffect innediately.\nEffectivity.\nThis Executive Order shall take\nDone in the city of Manila, this 24th day of\nthe year of Our Lord, nineteen hundred and eighty-seven.\nbetrayer to louiet\nBy the President:\n\"JOKER P. ARROYO\nÉxecutive secretary"}}],"pack":"ph-p158"};
