  FT["PH-H18896"] = {"id":"PH-H18896","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO.","orig":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 257","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00257_1995.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00257_1995.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18896-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"immediately.\nyear of Our Lord,\n,\nPMS LIBE?ARY\n1111111111111111111111111111111111111\nPMS LIBRARY BCODEOO8151"}}],"pack":"ph-p158"};
  FT["PH-H18897"] = {"id":"PH-H18897","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES SUSPENDING THE MECHANISM OF REMITTING BY THE PHIVIDEC INDUSTRIAL OF 50% OF ITS PROFIT TO THE PHILIPPINE INVESTMENT DEVELOPMENT CORPORATION","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES SUSPENDING THE MECHANISM OF REMITTING BY THE PHIVIDEC INDUSTRIAL OF 50% OF ITS PROFIT TO THE PHILIPPINE INVESTMENT DEVELOPMENT CORPORATION"},"level":"law","status":"active","docNumber":"Executive Order No. 257","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00257_2000.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00257_2000.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18897-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Repealing\nClause. Conformably with Presidential\nNo. 1416, as amended by Presidential Decree No. 1772, all laws, decrees,\ncharters, executive orders, administrative\norders, proclamations,\nregulations\nand other issuances or parts thereof which are in conflict\nwith the provisions\nof this Executive\nOrder are hereby repealed or\nmodified accordingly.\nSEC.immediately.\n4.\nEffectivity.\nThis Executive\nOrder shall take effect\nDONE in the City of Manila, this o1!!;r!J day of\nof Our Lord, Two Thousand.\nJ £.A~ in the year\nBy the President:\n:.:.:~~.:=~~\nRONALDO B. ZAMORA\nExecutive Secretary\n11'11/05\n'18602\n3"}}],"pack":"ph-p158"};
  FT["PH-H18898"] = {"id":"PH-H18898","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES CREATING A REGIONAL DEVELOPMENT COMMITTEE (RDC UNDER THE","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES CREATING A REGIONAL DEVELOPMENT COMMITTEE (RDC UNDER THE"},"level":"law","status":"active","docNumber":"Executive Order No. 257","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00257_2003.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00257_2003.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18898-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Functions of the NB-RDC. The NB-RDC shall:\na. formulate and monitor the implementation of policies that\nreduce regional growth disparities, promote equitable\nallocation of resources among regions;\nb. serve as clearinghouse for key regional development policy\nproposals which impact on two or more regions;\nc. formulate and monitor the implementation of the framework\nfor regional development of the Medium-Term Philippine\nDevelopment Plan;\nd. direct the formulation and review guidelines for the regional\nallocation of agency budgetary resources; and\ne. periodically review the viability of the regional configuration of\nthe country and recommend to the President the re-delineation\nof regions, as may be necessary."}},{"id":"PH-H18898-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Creation of NB-RDC Technical Board. A Technical Board\nshall be created to provide technical support to the NB-RDC."}},{"id":"PH-H18898-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Composition of the Technical Board. The Technical Board\nshall be composed of the following:\nNEDA Deputy Director-General for Regional Development\nThree (3) NEDA Regional Directors one each from Luzon,\nVisayas and Mindanao\nRepresentatives of the member agencies of the NB-RDC\nFour (4) regional development experts from the private\nsector and academe"}},{"id":"PH-H18898-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Funding. Funds needed to carry out the provisions of this\nExecutive Order for the first calendar year shall be drawn from the NEDA budget.\nPOMA Hologram * 23297\n\nFund requirements for the succeeding years shall be provided in the General\nAppropriations Act."}},{"id":"PH-H18898-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Implementing Authority of the MED Director-General. The\nNEDA Director-General shall issue such implementing rules, regulations, and\nother issuances as may be necessary to ensure the efficient and effective\nimplementation of the provisions of this Executive Order."}},{"id":"PH-H18898-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Repeal. All previous issuances inconsistent with the\nprovisions of this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H18898-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"Effectivity. This Executive Order shall take effect\nimmediately.\nDONE in the City of Manila, this 15th day of December, in the year of Our\nLord, Two Thousand and Three.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE010089\nPOMA Hologram # 23298"}}],"pack":"ph-p158"};
  FT["PH-H18899"] = {"id":"PH-H18899","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MESSAGES   OF   THE   PRESIDENT","orig":"MESSAGES   OF   THE   PRESIDENT"},"level":"law","status":"active","docNumber":"Executive Order No. 258","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00258_1940.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00258_1940.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18899-A1","no":1,"noLabel":{},"text":{"en":"OFFICIAL   GAZETTE\nQUEZON I Volume 4\nDone at the City of Mania, this twelfth day of March, in the year of Our Lord nineteen hundred\nand forty, and of the Commonwealth of the I'hilippines, the fifth.\nMJ~L L. QUEZON\nPresident of the Phihppines\nBy the President:\nTORGE 8. VARGAS\nSecretary to the Presideut\nSouree.. Presidential Museum and Library\nOffice  of the  President  of the  Philippmes.  (1940).  /Exec#£jue  Order  Nos...  248  -  399J.  Manila:\nPresidential Museum and Library."}}],"pack":"ph-p158"};
  FT["PH-H18900"] = {"id":"PH-H18900","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF SINACABAN, IN THE PROVINCE OF MISAMIS OCCIDENTAL.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF SINACABAN, IN THE PROVINCE OF MISAMIS OCCIDENTAL."},"level":"law","status":"active","docNumber":"Executive Order No. 258","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00258_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00258_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18900-A1","no":1,"noLabel":{},"text":{"en":"OFFICIAL GAZETTE\nconsist of the southern portion of the municipality of\nJimenez, Misamis Occidental, more particularly described\nand bounded as follows:\nOn the north by a line starting from point 1, the center of the\nlighthouse on the Tabo-o point S. 84° 30' W., 7,250 meters to point\n2 which is on the bank of Palilan River branch; thence following\nPalilan River branch 2,400 meters southwesterly to point 3, thence\na straight line S. 87° 00' W., 22,550 meters to point 4, where this\nintersects the Misamis Occidental Zamboanga bounlary; on the\nwest, Ly the present Misamis Occidental-Zamboanga boundary; on\nthe south by the present Jimenez-Tudela boundary; and on the\neast, by the limits of the municipal waters which the municipality\nof Sinacaban shall have pursuant to section 2321 of the Revised\nAdministrative Code, (Description based on data shown in Enlarged\nMap of Poblacion of Jimenez, Scale 1:8:000.)\nThe municipality of Sinacaban contains the barrios of\nSinacaban, which shall be the seat cf the municipal gov-\nernment, Sinonoc, Libertad, the southern portion of the\nbarrio of Macabayao, and the sitios of Tipan, Katipunan,\nEstrella, Flores, Senior, Adorable, San Isidro, Cagayanon,\nKamanse, Kulupan and Libertad Alto.\nThe municipality of Jimenez shall have its present ter-\nritory, minus the portion thereof included in the munic-\nipality of Sinacaban.\nThe municipality of Sinacaban shall begin to exist upon\nthe appointment and qualification of the mayor, vice-mayor,\nand a majority of the councilors thereof. The new munic-\nipality shall, however, assume payment of a proportionate\nshare of the loan of the municipality of Jimerez with the\nRehabilitation Finance Corporation as may be outstanding\non the date of its organization, the proportion of such\npayment to be determined by the Department of Finance.\nDone in the City of Manila, this 30th day of August, in\nthe year of Our Lord, nineteen hundred and forty-nine,\nand of the Independence of the Philippines, the fourth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary\n3177"}}],"pack":"ph-p158"};
  FT["PH-H18901"] = {"id":"PH-H18901","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1957/eo_258_1957.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Returning to the Municipality of Kolambugan, Province of Lanao, Certain Sitios of the Municipal District of Tangcal, Same Province","orig":"Returning to the Municipality of Kolambugan, Province of Lanao, Certain Sitios of the Municipal District of Tangcal, Same Province"},"level":"law","status":"active","docNumber":"Executive Order No. 258","issuingBody":"President of the Philippines","promulgatedDate":"1957-07-11","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00258_1957_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00258_1957_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18901-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 258, July 11, 1957 ]\nRETURNING TO THE MUNICIPALITY OF KOLAMBUGAN, PROVINCE OF LANAO, CERTAIN\nSITIOS OF THE MUNICIPAL DISTRICT OF TANGCAL, SAME PROVINCE\nPursuant to the provisions of section sixty-eight of the Revised Administrative Code, the sitios of Palao,\nMintering, Inome, Lindungan, and Panisilin, which are included within the barrios of Meladoc Small,\nMeladoc Big, Lamosa, Pilingkingan, and Berowar, respectively, of the municipal district of Tangcal, province\nof Lanao, are hereby segregated from the said municipal district and returned to the municipality of\nKolambugan, same province, to which they belonged prior to their becoming parts of Tangcal.\nThis Order shall take effect immediately.\nDone in the City of Manila, this 11th day of July, in the year of Our Lord, nineteen hundred and fifty-seven,\nand of the Independence of the Philippines, the twelfth.\n(Sgd.) CARLOS P. GARCIA\nPresident of the Philippines\nBy the President:\n(Sgd.) FORTUNATO DE LEON\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18902"] = {"id":"PH-H18902","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1970/eo_258_1970.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the National Action Committee on Anti-Smuggling","orig":"Creating the National Action Committee on Anti-Smuggling"},"level":"law","status":"active","docNumber":"Executive Order No. 258","issuingBody":"President of the Philippines","promulgatedDate":"1970-09-17","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00258_1970_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00258_1970_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18902-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 258, September 17, 1970 ]\nCREATING THE NATIONAL ACTION COMMITTEE ON ANTI-SMUGGLING AFFAIRS\nWHEREAS, the problem of smuggling is not the sole concern and responsibility of a single government\nWHEREAS, the existence of gaps and inadequacies in the current anti-smuggling effort of the government,\nparticularly on matters relating to intelligence, operation or apprehension, prosecution and disposition of\nsmuggling cases, has served to hamper the effectiveness of the drive; and\nWHEREAS, to wage a more dynamic and vigorous campaign against smuggling, it is necessary that there be a\nconcerted and well-coordinated action among the different agencies of the government engaged in\nanti-smuggling activities;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby create a National Action Committee on Anti-Smuggling Affairs composed of\nthe following;\nCommissioner of Customs\nChairman, Anti-Smuggling Action Center\nRepresentative of the Secretary of Justice\nRepresentative of the Commissioner, BIR\nRepresentative of the Chief of Staff, AFP\nCommandant, Philippine Coast Guard\nRepresentative of such other government entities that the Committee may call on on-the-need basis."}}],"pack":"ph-p158"};
  FT["PH-H18903"] = {"id":"PH-H18903","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG GRANTING GOVERNMENT HOSPITALS AND THE BUREAU OF FOOD AND DRUGS AUTONOMY IN THE USE OF THEIR INCOME","orig":"MALACAÑANG GRANTING GOVERNMENT HOSPITALS AND THE BUREAU OF FOOD AND DRUGS AUTONOMY IN THE USE OF THEIR INCOME"},"level":"law","status":"active","docNumber":"Executive Order No. 258","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00258_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00258_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18903-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Any income earned by any government hospital\nand by the BFD shall be deemed to have been released from appropria-\ntions authorized for such hospital or the BFD, as the case may be, and\nshall be immediately available for expenditures."}},{"id":"PH-H18903-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Fund releases from the Department of Budget and\nManagement shall be reduced by the amount of income earned by the\nhospitals and the BFD. For this purpose, these agencies shall submit\nperiodic reports of their income as well as reports indicating the details\nof expenditures thereof."}},{"id":"PH-H18903-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"In the event that any of these agencies realizes\nincome more than its authorized appropriation, such excess shall be\ndeemed automatically appropriated and released to augment existing\nauthorized appropriation.\n\n- 2 -\nThe rules and regulations necessary to implement\nthe provisions of this Executive Order shall be jointly issued by the\nDepartment of Finance and the Department of Budget and Management."}},{"id":"PH-H18903-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila on 25th of\nYear of Our Lord, Nineteen Hundred and Eighty Seven.\nBy authority of the President:\nPOKER P. ARROYO\nExecutive Secretary"}}],"pack":"ph-p158"};
