  FT["PH-H18905"] = {"id":"PH-H18905","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG PMS LI BRARY BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO. PRESCRIBING TIME STANDARDS FOR HOUSING","orig":"MALACANANG PMS LI BRARY BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO. PRESCRIBING TIME STANDARDS FOR HOUSING"},"level":"law","status":"active","docNumber":"Executive Order No. 258","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00258_2000.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00258_2000.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18905-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Separability\nClause. In the event any provision\ndeclared invalid by any competent court or tribunal,\nthe other provisions hereof\nunaffected thereby shall remain in full force and effect."}},{"id":"PH-H18905-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Effectivity.\nThis order shall take effect immediately.\nDONE in the City of Manila, this28.}J1day ofJu~ in the year of Our Lord\nTwen ty Hundred.\n/\n~-\n--:0\nJOSEPH EJERCITO\nBY THE PRESIDENT:\nPMS LIBRARY\nRONALDO B. ZAMORA\nExecutive Secretary\n~._,.-\",,~'.,\"-\n;;.\n~IIIIIIIIIIIIIIIIIIIIIIIIIIIIIIIIIII\nPJEE Hologram\n#18596"}}],"pack":"ph-p158"};
  FT["PH-H18906"] = {"id":"PH-H18906","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES RECONSTITUTING THE NATIONAL TASK FORCE DIWALWAL","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES RECONSTITUTING THE NATIONAL TASK FORCE DIWALWAL"},"level":"law","status":"active","docNumber":"Executive Order No. 258","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00258_2003.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00258_2003.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18906-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDONE in the City of Manila, this 13 th day ofDecember, in the year of Our\nLord, Two Thousand and Three.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPGMA Hologram / 23295"}}],"pack":"ph-p158"};
  FT["PH-H18907"] = {"id":"PH-H18907","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING A FIRE PREVENTION BOARD","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING A FIRE PREVENTION BOARD"},"level":"law","status":"active","docNumber":"Executive Order No. 259","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00259_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00259_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18907-A1","no":1,"noLabel":{},"text":{"en":"3178\nOFFICIAL GAZETTE\nWHEREAS, the planning and study of efficient and modern\nmethods of preventing and fighting fires are necessary to\ninsure the safety of the people and the protection of their\nproperties;\nNow, THEREFORE, I, Elpidio Quirino, President of the\nPhilippines, by virtue of the powers vested in me by law,\ndo hereby create a Fire Prevention Board composed of\nthe following:\nThe Secretary of the Interior....\n..... General Chairman\nGROUP ONE (GOVERNMENT)\nThe Undersecretary of the Interior\nGroup Chairman\nA representative of the Department of\nPublic Works and Communications to be\ndesignated by the Secretary thereof..\nA representative of the Department of Edu-\ncation to be designated by the Secretary\nA representative of the Department of Com-\nmerce and Industry to be designated by\nthe Secretary thereof\nGROUP TWO (PROFESSIONAL\nThe Chief of the Manila Fire Department Group Chairman\nA fire fighting expert from the Manila Fire\nDepartment to be designated by the Chief\nA provincial fire fighting expert to be desig-\nnated by the Group Chairman..\nA fire marshal, civilian or military, to be\ndesignated by the Group Chairman.........\nGROUP THREE (SAFFTY)\nThe Executive Director, Philippine Safety\nGroup Chairman\nThe Chairman, Advisory Safety Council to\nthe Secretary of Labor\nThe Chief of Safety Services, Philippine\nNational Red Cross\nA representative of fire fighting equipment\ndistributors to be designated by the Group\n•.....\nGROUP FOUR (FIRE INSURANCE)\nThe Chairman, Manila Fire Insurance As-\nGroup Chairman\nThe Manager, American Foreign Insurance\nAssociation\nA representative of a local fire insurance\nfirm to be designated by the Group Chair-\nThe Manager, American International Un-\nderwriters (Philippines)\nGROUP FIVE (CIVIC)\nThe President, Philippine Chamber of Com-\n... Group Chairman\nThe President, Chinese Chamber of Com-\nOFFICIAL GAZETTE\nThe President, American Chamber of Com-\nmerce of the Philippines....\nThe President, National Federation of Wo-\nmen's Clubs of the Philippines....\nThe Board which shall meet at the call of the General\nChairman shall have the following duties:\n(a) To investigate the origin and cause of fires;\n(6) To study ways and means of preventing âres;\n(c) To study suitable fire-fighting plans and facilities;\n(d) To arouse the inhabitants of the Philippines to the necessity\nof combating and preventing fires by appealing to their\nsense of individual responsibility through the newspapers,\nradio, posters, or other means of dissemination;\n(e) To cooperate with the auchorities concerned in the adoption\nof such measures as may be necessary for the effective\nsupervision and regulation of the manufacture, distribu-\ntion, storage, and possession of petroleur, gas, acetylene.\ndynamite, gunpowder, explosives, blasting supplies, or\ningredients thereof, and other highly combustible matter;\n(f) To cause the inspection of factory buildings and other\nstructures which are considered fire hazards ard recom-\nmend to the proper authorities their removal or their\nremodelling so as to provide sufficient protection against\n(g) To encourage the observance in, every municipality and\nchartered city of Fire Prevention Week proclaimed in\nProclamation No. 248, dated January 20, 1938; and\n(h) To submit from time to time to the President of the Phil-\nippines its recommendations on fire fighting and preven-\nThe General Chairman may also call the grous chair-\nmen to a meeting from time to time.\nThe groups shall meet at the call of their respective\nAll officers and employees of the different Departments,\nbureaus, offices, agencies, and instrumentalities of the\nNational Government aid those of the provinces, cities,\nmunicipalities and other political subdivisions are hereby\nenioined to cooperate with the Board in the performance\nof its functions and, with the approval of the correspond-\ning Head of Department, shall, when necessary, render\nsuch service as the Board may assign to them.\nDone in the City of Manila, this 30th day of August, in\nthe year of Our Lord, nineteen hundred and forty-nine,\nand of the Independence of the Philippines, the fourth.\nELPIDIO QUIrINO\nPresident of the Philippines\n3179\nBy the President:\nTEODORO EVANgELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18908"] = {"id":"PH-H18908","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1957/eo_259_1957.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Municipality of San Enrique in the Province of Iloilo","orig":"Creating the Municipality of San Enrique in the Province of Iloilo"},"level":"law","status":"active","docNumber":"Executive Order No. 259","issuingBody":"President of the Philippines","promulgatedDate":"1957-07-12","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00259_1957_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00259_1957_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18908-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 259, July 12, 1957 ]\nCREATING THE MUNICIPALITY OF SAN ENRIQUE IN THE PROVINCE OF ILOILO\nPursuant to the provisions of section sixty-eight of the Revised Administrative Code, the barrios of Abaca,\nAsisig, Bantayam, Cabugao Nuevo, Cabugao Viejo, Camiri, Catan-agan, Compo, Cubay, Dacal, Dumilis,\nGarita, Gines Nuevo, Imbang Pequeño, Imbisad-an, Iprog, Lip-ac, Madarag, Mapili, Paga, Palge, Quinolpan,\nRomagayray, San Antonio, San Enrique, and Tambunac, all of the Municipality of Passi, province of Iloilo,\nare hereby segregated from said municipality and constituted into an independent municipality in said\nprovince, to be known as the municipality of San Enrique with the seat of government at the barrio of San\nThe municipality of Passi shall have the same territory minus that comprised in the municipality of San\nThe municipality of San Enrique shall begin to exist upon the appointment and qualification of the mayor,\nvice-mayor, and a majority of the councilors thereof and upon the certification by the Secretary of Finance\nthat said municipality is financially capable of implementing the provisions of the Minimum Wage Law and\nproviding for all the statutory obligations and ordinary essential services of a regular municipality and that the\nmother municipality of Passi, after the segregation therefrom of the barrios comprised in the municipality of\nSan Enrique, can still maintain creditably its municipal government, meet all its statutory and contractual\nobligations and provide for the essential municipal services.\nDone in the City of Manila, this 12th day of July, in the year of Our Lord, nineteen hundred and fifty-seven,\nand of the Independence of the Philippines, the twelfth.\n(Sgd.) CARLOS P. GARCIA\nPresident of the Philippines\nBy the President:\n(Sgd.) FORTUNATO DE LEON\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H18909"] = {"id":"PH-H18909","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1970/eo_259_1970.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Executive Order No. 237 Dated June 16, 1970, Which Created the National Council for Small and Medium Industries.","orig":"Amending Executive Order No. 237 Dated June 16, 1970, Which Created the National Council for Small and Medium Industries."},"level":"law","status":"active","docNumber":"Executive Order No. 259","issuingBody":"President of the Philippines","promulgatedDate":"1970-09-18","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00259_1970_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00259_1970_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18909-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 259, September 18, 1970 ]\nAMENDING EXECUTIVE ORDER NO. 237 DATED JUNE 16, 1970, WHICH CREATED THE\nNATIONAL COUNCIL FOR SMALL AND MEDIUM INDUSTRIES\nThe fifth paragraph of Executive Order No. 237 dated June 16, 1970, is hereby amended to read as follows:\n“NOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby create a National Council for Small and Medium Industries which shall be\ncomposed of the following:\nChairman of the National Economic Council\nDirector, U.P. Institute for Small Scale and Medium Industries\nAction Officer\nSecretary of Commerce and Industry\nChairman, Board of Governors, Development Bank of the Philippines\nPresident, Philippine National Bank\nGeneral Manager, Government Service Insurance System\nAdministrator, Social Security System\nRepresentative, Filipino Chamber of Small Business and Industries\nRepresentative, Philippine Chamber of Industries\nRepresentative, Philippine Chamber of Commerce\nDone in the City of Manila, this 18th day of September, in the year of Our Lord, nineteen hundred and\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) ALEJANDRO MELCHOR\nExecutive Secretary"}}],"pack":"ph-p158"};
