  FT["PH-H18925"] = {"id":"PH-H18925","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PHILIPPINES INTER-AGENCY EMPLOYMENT PROTECTION REHABILITATION PERSONS WITH DISABILITIES","orig":"BY THE PRESIDENT OF THE PHILIPPINES INTER-AGENCY EMPLOYMENT PROTECTION REHABILITATION PERSONS WITH DISABILITIES"},"level":"law","status":"active","docNumber":"Executive Order No. 261","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00261_1995.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00261_1995.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18925-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"The Committee, through the Chairperson, shall make .::l\nperiodic report of its activities to. t:he President."}},{"id":"PH-H18925-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"The Bureau of Local Emplo~ent\nof the Department of\nLabor and Emplo~ent\nshall serve as the Committee's Secretariat and\nliaison/ coordinating arm with Congress and other government agencies."}},{"id":"PH-H18925-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"All participating\ngovernment agencies\nshall include in\ntheir respective Annual Work and Financial Plans the necessary budget\nfor the implementation\nof this Order.\nThis Executive Order shall take effect upon its signing.\nDONE in the City of Manila, this 17th\nOur Lord, Nineteen Hundred and Ninety-Five.\nPMS LIBRARY\nExecu tive Secretary\n1111111111111111111111111111111111111\nPMS LIBRARY BCODEOO6128\n---~~~\n\"\"\"'\""}}],"pack":"ph-p158"};
