  FT["PH-H19041"] = {"id":"PH-H19041","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"BY THE PRESmENT OF THE PHILIPPINES ORDER NO. 274 DATED 14 SEPTEMBER","orig":"BY THE PRESmENT OF THE PHILIPPINES ORDER NO. 274 DATED 14 SEPTEMBER"},"level":"law","status":"active","docNumber":"Executive Order No. 278","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00278_1995.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00278_1995.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19041-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Section 1 of Executive Order No. 274, series of 1995, is hereby\nto read as follows:\n\"SEC. 1. To ensure that an effective mechanism and linkage is instituted\nfor the implementation of the Bicol Region Tourism Master Plan\n(BR TMP), there is hereby created under the Office of the President a\nPresidential Commission to be called the Bicol\nTourism Special\nDevelopment Project Commission which shall be responsible for the\noverall coordination and supervision of the implementation of the\nBRTMP. It shall be composed of the following:\n-Vice-Chairman\nSecretary of Tourism\nSecretary of Public Works and Highways\nSecretary of Transportation and\nCommunications\nSecretary of Agrarian Reform\nSecretary of Agriculture\nSecretary of Interior and Local\nGovernment\nSecretary of Trade and Industry\nSecretary of Environment and Natural\nSecretary of Education, Culture and\nChairman of the Regional Development\nCouncil, Region V\nGovernors/City Mayors of Concerned\nLocal Government Units (LGUs)\nThe Department of Tourism shall provide technical secretariat services to\nthe Commission.\"\nIN REPLVING, P~CTE:"}},{"id":"PH-H19041-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 10~ay of\nLord, Nineteen Hundred and Ninety-Five.\n, in the year of OUf\n;;\nBy the President:\n\\\nExecutive Secretary\nRCGIALC/aao"}}],"pack":"ph-p158"};
  FT["PH-H19042"] = {"id":"PH-H19042","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo2000/eo_278_2000.html","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for the Winding-Up of the Mt. Pinatubo Assistance, Resettlement and Development Commission (Joseph Ejercito-Estrada)","orig":"Providing for the Winding-Up of the Mt. Pinatubo Assistance, Resettlement and Development Commission (Joseph Ejercito-Estrada)"},"level":"law","status":"active","docNumber":"Executive Order No. 278","issuingBody":"President of the Philippines","promulgatedDate":"2000-08-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00278_2000_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00278_2000_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19042-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Secretary of Budget and Management or his representative shall henceforth act as Chairman\nof the Executive Committee of the Mt. Pinatubo Commission in lieu of the Secretary of Finance, who shall\ncontinue to be a member of the Commission. The DBM shall provide the secretariat for the Commission from\nits existing personnel complement. The Secretary of Budget and Management shall immediately prepare for\nthe winding-up of the Mt. Pinatubo Commission. Except for the foregoing changes, the membership of the\nCommission shall be maintained without need of another appointment."}},{"id":"PH-H19042-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Department of Budget and Management shall supervise the winding up of the activities of\nthe Commission. After the life of the Commission expires, the term of the members thereof shall immediately\nterminate. However, the government representatives to the Commission shall continue to meet as an\ninteragency committee for a period not exceeding one (1) year for the sole purpose of assisting the\nDepartment of Budget and Management in winding-up the Commission."}},{"id":"PH-H19042-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In pursuance of the foregoing mandate, the Secretary of Budget and Management may require\nthe Commission to submit such data, records and documents to the Department of Budget and Management,\nand may seek the assistance of the different government agencies represented in the Commission."}},{"id":"PH-H19042-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Order shall take effect immediately\nDone in the City of Manila, this 14th day of August, in the year of Our Lord, two thousand.\n(Sgd.) JOSEPH EJERCITO ESTRADA\nBy the President:\nRONALDO B. ZAMORA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19043"] = {"id":"PH-H19043","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES PRESCRIBING GUIDELINES FOR PROJECT LOAN NEGOTIATIONS AND GOVERNMENT FOREIGN-ASSISTED INFRASTRUCTURE PROJECTS","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES PRESCRIBING GUIDELINES FOR PROJECT LOAN NEGOTIATIONS AND GOVERNMENT FOREIGN-ASSISTED INFRASTRUCTURE PROJECTS"},"level":"law","status":"active","docNumber":"Executive Order No. 278","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00278_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00278_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19043-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"General Policy\nOn Consultancy Services for\nGovernment Infrastructure Projects. As a general rule, the government\nshould, as much as possible, fund consultancy services for government\nPOMA Hologram « 24216\n\ninfrastructure projects with local funds and using local resources and expertise.\nConsultancy services shall be proposed for foreign assistance only where foreign\nfunding is indispensable or local funds are insufficient. For this purpose, the\nconcerned government units shall provide funds in their respective investment\nprograms for the following consultancy services:\nPre-investment components which shall include feasibility studies\nand related surveys and special studies;\nDetailed engineering design and related activities (where the\nproject is determined to be feasible); or\nProject Management/Supervision\nWhere Filipino capability is determined by appropriate authorities to be\ninsufficient, Filipino consultants may hire or associate themselves with foreign\nconsultants, provided that the Filipino shall be the lead consultant.\nWhere foreign funding is indispensable, foreign consultants for the project\nmust enter into joint venture with Filipino consultants.\nPackaging of Government Infrastructure Projects.\nThe following basic principles shall govern the work packaging of government\ninfrastructure projects, irrespective of the funding source:\n2.1. Large government infrastructure projects, when feasible, shall be\npackaged into separable work components without sacrificing the\ntechnical integrity of the structure to be built and taking into\naccount Filipino capabilities. Complex and/or multi-disciplinary\ninfrastructure projects covering works of a different nature\nrequiring varied competencies shall be packaged into separate work\ncomponents to be defined in the Implementing Rules and\nRegulations (IRR) of this Order.\n2.2. The packaging of such projects shall take into account the technical\nand financial capabilities and experience of Filipinos in the domestic\nand international market, as well as the most logical and practical\nscope of work to complete a project or any part thereof.\n2.3. In the criteria for determining eligible or pre-qualified bidders, the\nsuccessful completion of a single project whose value is at least\nfifty percent of the value of the contract to be bid shall be\nacceptable as work experience requirement.\n2\nPOM^ Hologram * 24217\n\n3\n2.4. Clustering of small and medium projects may be adopted, provided\nthat the resulting cluster or package is within the capabilities of\nFilipino contractors.\n•\n2.5. However, packaging of projects that is tantamount to or will result\nin contract splitting as defined under Section 11 of Executive Order\nNo. 109-A, for the purpose of evading or circumventing the\nrequirements of law and/or existing rules and regulations, shall not\nPre-Loan Negotiations. Prior to loan negotiations, the\nnegotiating panel shall convene a technical working group to include at least one\n(1) representative from the private sector to provide inputs and ensure\ntransparency. The DOF shall invite the representatives) upon recommendation\nby the Construction Industry Authority of the Philippines (CIAP), in case of\ninfrastructure projects, and upon recommendation by the private sector\nconcerned in case of goods and consulting services.\nProiects Preparation and Loan\nNegotiation\nParameters. In the preparation of projects or negotiation of foreign loans for\nthese projects, the government negotiating panels shall strictly observe the\nprovisions of this EO including the following parameters:\n4.1 Where special tax privileges are granted to a particular\nclass/nationality by virtue of the government's international\ncommitments, such tax privileges shall be included in the bid\noffers/financial proposals for purposes of evaluation and the basis\nof contract award.\n4.2\nTo ensure the sustained promotion of Filipino talents in all fields,\neffect technology transfer, and adoption of measures that will help\nthem become competitive, the loan agreement shall, whenever\neconomically viable, provide for joint venture associations between\nFilipino and foreign firms.\n4.3\nThe government negotiating panel shall ensure that the loan\nagreement, including exchanges of notes and other documents\nmade integral parts thereof, do not contain provisions which\ndiscriminate against Filipinos and limit their participation in the\nproject to be funded under the loan agreement.\nImplementing Rules and Regulations (IRR).\nNEDA Infrastructure Committee (INFRACOM) shall promulgate the IRR for this\nOrder within sixty (60) days from date hereof.\n3\nPOMA Hologram # 24218\n\n4\nRepealing Clause. All executive issuances, orders, rules\nand regulations, department orders, circulars of parts thereof inconsistent with\nthis Order are hereby repealed, amended and/or modified accordingly.\nSeparability Clause. If any provision of this Order is\ndeclared invalid or unconstitutional, the other provisions not affected thereby\nshall remain valid and subsisting.\nEffectivity. This Order shall take effect fifteen (15) days\nafter its publication in the Official Gazette or in a newspaper of general\ncirculation.\nDONE, in the City of Manila, this 2nd\nour Lord Two Thousand and Four.\nday of FEB in the year of\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE010055\nPOMA Hologram # 24219\n4"}}],"pack":"ph-p158"};
  FT["PH-H19044"] = {"id":"PH-H19044","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ORGANIZING CERTAIN BARRIOS OF THE MUNIC- IPALITY OF ROSARIO, PROVINCE OF BATAN- GAS, INTO AN INDEPENDENT MUNICIPALITY UNDER THE NAME OF PADRE GARCIA.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ORGANIZING CERTAIN BARRIOS OF THE MUNIC- IPALITY OF ROSARIO, PROVINCE OF BATAN- GAS, INTO AN INDEPENDENT MUNICIPALITY UNDER THE NAME OF PADRE GARCIA."},"level":"law","status":"active","docNumber":"Executive Order No. 279","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00279_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00279_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19044-A1","no":1,"noLabel":{},"text":{"en":"OFFICIAL GAZETTE\nProvince, and Rosario; on the southeast, by the Bayan\nRiver from where it crosses the present Batangas-Quezon\nboundary westward along its south tributary to a point on\nsaid tributary exactly north of the poblacion of barrio\nTiquiwan, municipality of Rosario; and on the south and\nsouthwest, by a line running westward from the said point\non the tributary just mentioned to Quiloquilo permanent\ndam in Quiloquilo Creek; thence to Pinagmuzonan culvert\nbetween Lumang bayan and Quilib, Sta. 95-828, 68; thence\n\" to Tampayak timber bridge between Sta. Cruz and San\nMiguel; thence following the course of Tampayak Creek\nnorthward to the boundary of Lipa and Rosario. (Des-\ncription based on map of Rosario, scale 1:40,000, and data\nsubmitted by district engineer in his 3rd indorsement, dated\nThe municipality of Rosario shall consist of its present\nterritory minus the portion thereof comprised \" in the\nmunicipality of Padre Garcia.\nThe organization herein made shall take effect on\nDone in the City of Manila, this 11th day of October,\nin the year of Our Lord, nineteen hundred ard forty-nine,\nand of the Independence of the Philippines, the fourth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary\n4229"}}],"pack":"ph-p158"};
  FT["PH-H19045"] = {"id":"PH-H19045","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1957/eo_279_1957.html","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for the Implementing Details for Reorganization Plans Nos. 3-A, 19-A, 46-A, and 47-A Relative to the Budget Commission","orig":"Providing for the Implementing Details for Reorganization Plans Nos. 3-A, 19-A, 46-A, and 47-A Relative to the Budget Commission"},"level":"law","status":"active","docNumber":"Executive Order No. 279","issuingBody":"President of the Philippines","promulgatedDate":"1957-11-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00279_1957_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00279_1957_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19045-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The organization, functions, and operations of the Budget Commission, hereinafter referred to as\nthe “Commission,” shall be in accordance with the provisions of Reorganization Plans Nos. 3-A, establishing\na Wage and Position Classification Office, 19-A, as it applies to the Budget Commission, 46-A on Budgeting,\nand 47-A on Accounting, hereinafter referred to collectively as the “Plans,” and these Implementing Details."}},{"id":"PH-H19045-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The organization of the Commission, as graphically depicted in the following organization\ncharts, shall consist of the Office of the Commissioner, Office of the Deputy Commissioner, Administrative\nDivision, Legislative staff, Fiscal Policy Staff, Central Accounting Service, Management Service, Budget\nOperations Service, and the Wage and Position Classification Office: However, The Commissioner of the\nBudget, hereinafter referred to as the “Commissioner,” is authorized to create such staff and operating units as\nhe determines necessary to carry out the functional responsibilities of the Commission as provided in section 5\nof Reorganization Plan No. 46-A on Budgeting.\nFUNCTIONAL STATEMENTS OF THE BUDGET COMMISSION"}},{"id":"PH-H19045-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Commission shall have such functions, powers, duties, and responsibilities as are provided\nby Executive Order No. 25, dated April 25, 1936, Commonwealth Act No. 246 (otherwise known as the\nBudget Act), Republic Act No. 992 (an Act to Provide for a Budget System for the National Government) and\nRepublic Act No. 433; such additional functions and authorities as are given to the Commission by the Plans;\nand all amendatory acts, executive orders, rules, and regulations promulgated pursuant thereto. These\nfunctions, powers, duties, and responsibilities comprise: serving as the principal staff arm of the President,\nwith respect to advice on fiscal planning and control, management aspects of government operations, and\npreparation and control of the national budget; maintaining and preparing consolidated accounting records and\nreports for the National Government; coordinating legislative proposals affecting departments and agencies of\nthe government; administering the wage and position classification system; and including the following\nfunctions, among others:\n(1) obtain, from departments and agencies such information as the Commission may from time to time\nrequire, under such regulations as the President may prescribe;\n(2) have access to, and the right to examine, any books, documents, papers, or records of any department or\n\nagency as the Commissioner may deem necessary, under such regulations as the President may prescribe;\n(3) develop programs and issue regulations and orders for the improved gathering, compiling, analysis,\npublication, and dissemination of relevant and necessary statistical information related to the functions: of the\nCommission by the departments and agencies; and advise the President when such regulations and orders are\nnot adhered to by departments and agencies;\n(4) study, draft, review, revise, coordinate, and clear legislative proposals affecting departments and agencies\nof the government; and\n(5) administer the position classification and compensation system provided in Reorganization Plans Nos. 1-A\nand 2-A on Personnel, modify and revise these plans as necessary to maintain them in a current status."}}],"pack":"ph-p158"};
  FT["PH-H19046"] = {"id":"PH-H19046","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1970/eo_279_1970.html","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Republic Act Numbered Nineteen Hundred Thirty-Seven, Otherwise Known as the Tariff and Customs Code of the Philippines, as Amended.","orig":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Republic Act Numbered Nineteen Hundred Thirty-Seven, Otherwise Known as the Tariff and Customs Code of the Philippines, as Amended."},"level":"law","status":"active","docNumber":"Executive Order No. 279","issuingBody":"President of the Philippines","promulgatedDate":"1970-12-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00279_1970_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00279_1970_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19046-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The articles specifically listed in “Annex A” of this Order as classified under Section 104 of\nRepublic Act Numbered Nineteen Hundred Thirty-Seven shall pay the rates of import duty indicated opposite"}},{"id":"PH-H19046-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"After the expiration of thirty (30) days from the issuance of this Order, all the aforestated articles\nentered into or withdrawn from warehouses in the Philippines, for consumption, shall be subject to the rates of\nimport duty herein prescribed."}},{"id":"PH-H19046-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Any unwarranted increase in the prices of local products benefited by these tariff changes may\nbe sufficient ground for the revocation of such tariff changes.\nDone in the City of Manila, this 11th day of December, in the year of Our Lord, nineteen hundred and\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) ALEJANDRO MELCHOR\nExecutive Secretary"}}],"pack":"ph-p158"};
