  FT["PH-H19048"] = {"id":"PH-H19048","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DIRECTING THE DISSOLUTION OF PHILCORP PTY LTD","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DIRECTING THE DISSOLUTION OF PHILCORP PTY LTD"},"level":"law","status":"active","docNumber":"Executive Order No. 279","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00279_1995.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00279_1995.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19048-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The dissolution and liquidation, in accordance with\nPhilippine and Australian laws, of PhilCorp Pty Ltd.\nThe Department of Agriculture and the Office of the\nGovernment Corporate Counsel shall take the necessary steps to elect\nand carry out the dissolution and liquidation process in dismantling\nPhilCorp Pty Ltd.\nThe Department of Agriculture is hereby authorized to\nutilize the remaining assets of PhilCorp Ply Ltd to purchase breeding\ncattle from the Oceania Region for upgrading of the local livestock.\nIN REPLYING, PLEASE CITE:\nPFVR Letter:\n\nAll orders, issuances, rules and regulations or parts\nthereot inconsistent with the provisions of this Executive Order are\nhereby repealed and /or modified accordingly.\nThis Executive Order shall take effect immediatcly.\nDone in the City of Manila, this 13th day of October\nthe year of Our Lord Nineteen Hundred and Ninety Five.\nBy the Presidents\nPMS LICRARY\nRUBEN D. TORRES\nExecutive Secretary\nPMS LIBRARY BCODE006144"}}],"pack":"ph-p158"};
  FT["PH-H19049"] = {"id":"PH-H19049","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo2000/eo_279_2000.html","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Providing for Travelling and Incidental Expenses of Private Individuals Relative to the Prosecution of Cases Where the Government Is a Party Litigant (Joseph Ejercito-Estrada)","orig":"Providing for Travelling and Incidental Expenses of Private Individuals Relative to the Prosecution of Cases Where the Government Is a Party Litigant (Joseph Ejercito-Estrada)"},"level":"law","status":"active","docNumber":"Executive Order No. 279","issuingBody":"President of the Philippines","promulgatedDate":"2000-08-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00279_2000_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00279_2000_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19049-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Coverage. – This Executive Order shall apply to all private individuals including retired\ngovernment personnel or those who have left the government service for other reasons but whose testimony in\ncourt is material and indispensable for the prosecution of cases where the Government is a party litigant."}},{"id":"PH-H19049-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Travelling and Incidental Expenses of Private Individuals as Witnesses for the Government. –\nNecessary travel expenses, including actual and necessary expenses for subsistence may be allowed for\nwitnesses for the Government whose testimony in the courts of justice is considered material and\nindispensable in the trial of any case, whether administrative, civil or criminal. These shall be charged against\nthe funds of the Ombudsman or of the agency concerned for former agency personnel, or of the Commission\non Audit in the case of former COA employees.\nA person required by the Ombudsman to provide information shall be paid the same fees and travel\nallowances as are extended to witnesses whose attendance has been required in the trial courts. (Sec. 32, R.A.\nNo. 6770, The Ombudsman Act of 1989).\nIn order to assure the appearance of the witness, the public prosecutor or attorney concerned shall previously\napply therefor in writing to the court concerned. It having been shown that the testimony of the witness is\nmaterial, said court shall order the issuance of summons."}},{"id":"PH-H19049-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Funding requirements. – For the current year, funds to cover the transportation and incidental\nexpenses referred to in the preceding section shall be sourced from agency savings or, upon request,\naugmented by the Department of Budget and Management. Thereafter, funding requirements shall be included\nin the regular appropriation of the agencies concerned."}},{"id":"PH-H19049-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Repealing Clause. – All circulars, orders, memoranda, rules, regulations, and issuances or\nportions thereof which are inconsistent with this Executive Order are hereby repealed or modified\n\naccordingly."}},{"id":"PH-H19049-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Effectivity. – This Executive Order shall take effect thirty (30) days following its complete\npublication in at least two (2) newspapers of general circulation in the Philippines\nDone in the City of Manila, this 14th day of August, in the year of Our Lord, two thousand.\n(SGD.) JOSEPH EJERCITO ESTRADA\nBy the President:\n(SGD.) RONALDO B. ZAMORA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19050"] = {"id":"PH-H19050","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS TIrDADY BY THE PRESIDENT OF THE PHILIPPINES INSTITUTING REFORMS IN THE FINANCING POLICIES FOR THE WATER SUPPLY AND SEWERAGE SECTOR AND WATER SERVICE PROVIDERS AND PROVIDING FOR THE RATIONALIZATION OF LWUA'S ORGANIZATIONAL STRUCTURE AND OPERATIONS IN SUPPORT THEREOF","orig":"MALACAÑANG PMS TIrDADY BY THE PRESIDENT OF THE PHILIPPINES INSTITUTING REFORMS IN THE FINANCING POLICIES FOR THE WATER SUPPLY AND SEWERAGE SECTOR AND WATER SERVICE PROVIDERS AND PROVIDING FOR THE RATIONALIZATION OF LWUA'S ORGANIZATIONAL STRUCTURE AND OPERATIONS IN SUPPORT THEREOF"},"level":"law","status":"active","docNumber":"Executive Order No. 279","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00279_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00279_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19050-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Reform Objectives/Policies - All concerned government\nagencies and instrumentalities of the water supply and sewerage sector,\nincluding but not limited to the Department of Finance (DOF), the Municipal\nFinance Corporation (MC), Department of Interior and Local Government\n(DILG), Department of Budget and Management (DBM), Department of\nEnvironment and Natural Resources (DENR), DPWH, National Economic and\nDevelopment Authority (NEDA), LWUA, and the GFIs are hereby directed to\npursue and implement the following reform objectives / policies in the water\nsupply and sewerage sector:\nImprovement of investor confidence in the water supply and\nsewerage sector;\nRationalization in the allocation of scarce financial resources in the\nwater supply and sewerage sector through classification and\ngraduation initiatives;\nFreedom of choice of water service providers in sourcing financing;\nIncrease in the participation of LGUs, GFIs, and PFIs in the\nfinancing of the water supply and sewerage sector;\n2\nPOMA Hologram • 24221\n\nStimulation of improved service and creation of financial self-\nsustainability for water service providers;\nEncouragement of initiatives aimed at self-sufficiency of water\nservice providers, including, but not limited to, amalgamation,\nprivate sector participation, cost-recovery tariffs, and resource\nGrant of incentives for the improvement and graduation of water\nservice providers;\nEducation of consumers towards treating water as a scarce\neconomic good; and\n()\nEstablishment of an independent economic regulator for the water\nsupply and sewerage sector."}},{"id":"PH-H19050-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Definition of Terms - For purposes of this Order, the term:\nWater Service Providers (WSPs) - refer to local water utilities such\nas WDS, LGU-run water utilities, rural waterworks and sanitation\nassociations, barangay waterworks and sanitation associations,\nregardless of location.\nAmalgamation - refers to the consolidation, joint operation or\nannexation of two or more WSPs resulting into a water district.\nClassification - refers to the categorization of WSPs into non-\ncreditworthy, pre-creditworthy, semi-creditworthy or creditworthy\nto determine proper allocation of financing.\nCost Recovery Tariff - is the tariff required to cover capital and\noperation and maintenance costs of WSPs at all service levels.\nCreditworthy WSPs - are financially self-sustaining WSPs and\ncapable of accessing financing from GFIs and/or PFIs.\nGovernment Financial Institutions (GFIs) - refer to the\nDevelopment Bank of the Philippines (DBP), Land Bank of the\nPhilippines (LBP and other financing institutions owned and\ncontrolled by the Government\nGraduation - refers to the progression of a WSP from semi-\ncreditworthy to creditworthy status or of a non-credit worthy to\npre-creditworthy or of a pre-creditworthy WS to semi-creditworthy\nstatus based on improvements in financial and operational\nindicators.\n3\nPOMÀ Helogram # 24222\n\n•\nLocal Government Units (LGUs) - refer to the territorial and political\nsubdivisions of the Philippines, consisting of provinces, cities,\nmunicipalities and barangays.\nNon-Creditworthy WSPs - refer to WSPs with potential to reach\npre-creditworthy status in the medium-term, based on relevant\nfinancial and operational indicators set by the Oversight Committee.\nPre-Creditworthy WSPs - refer to WSPs which are not likely to\nbecome creditworthy in the medium-term due to performance\nissues but can demonstrate the potential for creditworthiness in the\nlong-term, based on relevant financial and operational indicators\nset by the Oversight Committee.\nSemi-Creditworthy WSPs - refer to WSPs with the demonstrated\nability to achieve creditworthiness in the short-term, based on\nrelevant financial and operational indicators set by the Oversight\nCommittee, but either lack the full criteria for creditworthiness or\ndo not meet the criteria consistently.\nOVERSIGHT COMMITTEE\nOversight Committee - An inter-agency Oversight\nCommittee is hereby constituted for purposes of coordinating and overseeing the\nimplementation of the reforms in the financing, graduation and regulatory\npolicies in the water supply and sewerage sector.\nComposition - The composition of the Oversight\nCommittee shall be as follows:\n::Department of Finance (DOF)\nVice-Chair : National Economic and Development Authority (NEDA)\nMembers : Department of Budget and Management (DBM)\nDepartment of Interior and Local Government (DIG)\nOffice of the President (OP)\nLocal Water Utilities Administration (LWUA)\nDesignated representatives of DOF, NEDA, DBM, DILG and OP must preferably\nbe of Undersecretary level. LWUA must be represented by its Administrator.\nGFIs and the Municipal Development Fund Office (MDFO) may serve as resource\npersons during meetings of the Oversight Committee.\n4\nPOMA Hologram • 24223\n\nFunctions - The Oversight Committee shall, among others:\nFormulate the implementing rules and regulations (IRR) of this\nReview the rationalization plan to be submitted by LWUA pursuant\nto Section 9 of this Order and submit its recommendations on said\nplan to the President for approval;\nReview the criteria for the classification of WSPs, recommended by\nthe Water Development Group (WDG) of LWUA;\nReview the classification of WSPs prepared by LWUA-WDG, duly\ncertified by LWUA-Head that the same is in accordance with the\ncriteria presented to and reviewed by the Oversight Committee.\nThe Oversight Committee may subject the classification of the\nWSPs to audit;\nPrepare an action plan for the reforms in the financing policies in\nthe water supply and sewerage sector for the near term and the\nmedium term including incentive schemes that appropriate\nagencies may consider to offer to GFIs and PFIs to encourage such\ninstitutions to lend to WSPs;\n(9)\nPrepare and submit quarterly reports to the agency to which LWUA\nis attached; and\nReview the charter of LWUA and when necessary, propose\namendments thereto.\nThe Oversight Committee shall immediately organize itself and set its policies\nand procedures to facilitate the implementation of the said reforms in the water\nsupply and sewerage sector.\nTechnical Secretariat - The Oversight Committee shall\nestablish a Technical Secretariat under DOF to be staffed by personnel assigned\nby government agencies comprising it. It shall serve as the official repository of\nall data concerning the classification and evaluation of all WSPs.\nExpenses - Members of the Oversight Committee and its\nTechnical Secretariat shall be entitled to receive honoraria and /or\nreimbursement of expenses as may be allowed subject to availability of funds\nand prevailing rules and regulations.\n5\nPGA Hologram • 24224\n\nLOCAL WATER UTILITIES ADMINISTRATION\nTransfer to OP - The LWUA, presently attached to the\nDPWH, is hereby attached to OP until such time it is transferred to DOF as\nprovided for under Section 10 hereof. In addition, the LWUA Board of Trustees\n(BOT) shall include representatives from the agency to which it is attached.\nRationalization of LWUA's organizational structure\nand operations - LWUA, subject to applicable laws and regulations, is hereby\ndirected to review its organizational structure and internal policies and programs,\nrationalize its operation and refocus its objectives to include other WSPs,\nwhenever feasible or applicable to facilitate implementation of and conform with\nthe policies enunciated in this Order. To this extent, LWUA shall constitute and\ndesignate from its current organizational setup, a Water Development Group\n(WDG), a Water Development Financier (WDF) and a Technical Assistance Group\n(TAG), or similar structures, with functions and responsibilities as follows:\nWater Development Group (WDG)\nThe WDG shall have the following responsibilities:\nThe WDG which shall be primarily charged with the continuation of\nLWUA's current institutional development services aimed at\ngraduating WSPs, as well as the classification of WSPS.\nThe WDG shall classify the WSPs into either creditworthy, semi-\ncreditworthy, pre-creditworthy or non-creditworthy for the purpose\nof determining the appropriate sources of financing. WSPs initially\nclassified by WDG as creditworthy and/or non-creditworthy shall be\nsubject to further review by the Oversight Committee pursuant to"}},{"id":"PH-H19050-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"of this Order.\nWSPs classified as semi-creditworthy and pre-creditworthy and\nnon-credit worthy shall be subject to periodic review by the WDG at\nleast once every three (3) years for purposes of reclassification. At\ntheir own instance, WSPs may request the WDG for an annual\nreclassification review.\nGraduation - The WDG shall develop a graduation plan for non-\ncredit worthy, pre-creditworthy and semi-creditworthy WSPs based\non the following graduation initiatives:\n6\nPOMA Hologram • 24225\n\nPOMA Hologram * 24226\nCost Recovery Tariff Initiatives - These are initiatives aimed\nat achieving widespread full cost recovery tariffs in the long-\nterm. The initiatives shall include the inventory of non-credit\nworthy, semi-creditworthy and pre-creditworthy WSPs to\ndetermine the degree to which tariffs are sufficient to\naccumulate at least a minimal reserve for collateral or\ncounterpart equity. In addition, should the LGUs invest in\nWSPs, they should be allowed recovery of and some minimal\nreturn on its investment.\nAmalgamation and Private Sector Participation Initiatives -\nThese are initiatives aimed at achieving economies of scale\nand efficiency of service through the use of identified\namalgamation and private sector participation techniques\nbased on technical, geographical, economic and other\nindicators.\nLWUA shall develop the necessary guidelines during the\ntransition period for the amalgamated WDs and LGUs.\nManagement Structure and Governance - These initiatives\npertain to institutional improvements within the WSPs'\nstructure leading to greater accountability and improved\nLGU/SP Resource Coordination for Credit Enhancement -\nThis refers to the pooling of resources between semi-\ncreditworthy and/or pre-creditworthy or semi-creditworthy\nand/or non-creditworthy WSPs and the relevant LGUs in\ntheir service areas to finance water supply and sewerage\nprojects or create the collateral needed to borrow from GFIs\nEducation - This refers to communication and information\ninitiatives on the benefits of graduation initiatives including\ncost recovery tariffs, amalgamation, private sector\nparticipation and LGU/SP resource coordination.\nTechnical Assistance to non-credit worthy and pre-\ncreditworthy WSPs - This refers to technical assistance to\nsupport graduation initiatives which may be given with or\nwithout charge within a value threshold that may be\ndetermined by LWUA-WDG.\n7\n\nLWUA-WDG shall monitor the implementation of the\ngraduation plan and evaluate the effectiveness of the\ngraduation initiatives undertaken by the semi-creditworthy,\npre-creditworthy and non-credit worthy WSPs.\nLWUA-WDG shall initially cover the classification and\ngraduation plan and initiatives of WDs. It may also cover\nother WSPs as deemed applicable or feasible.\nReporting - LWUA-WDG shall prepare and submit quarterly reports\non its activities to the Oversight Committee and DOF.\nWater Development Financier (WDF)\nThe WDF shall have the following responsibilities:\n(a) The WDF which shall be primarily tasked to enhance and/or\nstrengthen LWUA's lending functions and evaluate the applications\nfor financial assistance.\nRe-orientation Towards Banking Principles - LWUA, through the\nWDF, shall enhance and/or strengthen its lending policies and\nfunctions to carry out and implement its mandate to provide\nfinancing particularly to non-credit worthy, pre-creditworthy and\nsemi-creditworthy WDs, grounded on sound development banking\nprinciples. To this effect, LWUA shall adopt development banking\nprinciples which cater to the financing needs of WSPs and shall\ndevelop its own procedures for the monitoring of its loan portfolio.\nLWUA shall develop lending policies and guidelines in pursuit of the\npolicies and principles espoused under this Executive Order within\n90 days from its effectivity and submit the same to the Oversight\nCommittee. LWUA shall conduct its operations in a transparent,\nefficient and effective manner.\nStrengthening of Collection Function - In the exercise of its lending\nfunctions, LWUA shall also strengthen its collection function from\nWDs as well as enhance its payment of loans to LWUA creditors.\nTo this effect, all collections arising from LWUA's receivables shall\nconstitute a special fund to be apportioned between debt servicing\nof LWUA loans and the additional funding necessary to support the\nLWUA's graduation and technical assistance functions under the\nWDG and the TAG.\nPOMA Hologram / 24227\n8\n\nSegregation of LWUA Loan Portfolios -\nFor purposes of\nidentification and administrative efficiency, LWUA shall maintain\nseparate accounting, payment and collection systems for existing\nloans and loans to be granted henceforth pursuant to the reforms\ninstituted in this Executive Order.\nTechnical Assistance Group (TAG)\nTAG shall have the following responsibilities:\n(a) TAG shall continue LWUA's program of providing technical\nassistance to WSPs, in accordance with the proceeding sections.\nTAG shall extend project-related technical assistance to GFIs and\ncreditworthy WSPs on a competitive basis, consistent with\napplicable laws, rules and regulations on government procurement.\n(c) Above a certain value threshold, which threshold shall be\ndetermined by LWUA, TAG shall extend project-related technical\nassistance to semi-creditworthy WSPs on a competitive basis,\nconsistent with applicable laws, rules and regulations on\ngovernment procurement.\nLWUA-TAG shall extend project-related assistance to non-\ncreditworthy and pre-creditworthy WDs which may be with or\nwithout charge within a certain value threshold to be determined\nby LWUA to support projects funded by LWUA-WDF.\nWithin thirty (30) days from the effectivity of this Order,\nLWUA shall review its current structure and submit its rationalized plan to the\nOversight Committee, consistent with the policy reforms enunciated under this\nOrder. The Oversight Committee shall evaluate the rationalization plan within\nthirty (30) days from receipt. LWUA, with the endorsement of the Oversight\nCommittee, shall submit the rationalization plan to the President for final\nUpon approval by the President of the reforms in the water supply and\nsewerage sector, including the rationalized organization and manpower structure\nof LWUA, LWUA shall then be transferred to DOF. Pursuant to Section 51 of PD\n198, at least three (3) of the trustees must be employees of the National\nGovernment. DOF shall always be represented in the LWUA-BOT.\nPaMd Hologram # 24228\n9\n\nFINANCING POLICIES\nResponsibility of LGUs - In line with the principle of\ndevolution of the provision of basic services under the Local Government Code,\nLGUs shall be encouraged to provide delivery of water supply and sewerage\nservices through, but not limited to, investments in, or loans to WSPs. LGUs shall\nas a general policy, be financially and operationally responsible for the WSPs\nwithin their respective jurisdictions.\nSources of Financing - The sources of financing for the\nwater supply and sewerage sector shall be as follows:\nCreditworthy WSPs shall be eligible to source financing at\ncommercial lending rates from GFIs and PFIs. Pursuant thereto,\nLWUA, with respect to creditworthy WDs shall enhance and\nstreamline its waiver procedures to effect the reform\nobjectives/policies enunciated herein. GFIs shall strengthen their\nskills base and develop lending programs specially tailored to the\nneeds of the water supply and sewerage sector.\nSemi-creditworthy WDs shall be eligible to source concessional debt\nfinancing from the LWUA-WDF, as well as GFIs and PFIs when\nPre-creditworthy WDs shall be eligible to source grants from donors\nand deep concessional financing from the LWUA-WDF.\nNon-creditworthy WDs shall continue to be eligible for financing\nunder the LWUA-WDF. However, LGUs are hereby encouraged to\nprovide financial and operational support for such WDs and other\nWSPs within their respective jurisdictions. DILG and MDFO shall\nprovide the necessary technical and financial support within their\nrespective mandates.\nWSPs, including eligible WDs, can access financing from GFIs, PFIs,\nMDFO, and LGUs, whenever possible.\nLWUA-WDG shall provide the necessary incentives for graduation such as\nextension of greater flexibility in WD's operation as a WD graduate from one\nstage to the next. LWUA-WDG shall provide guidelines to encourage graduation,\nwhich shall be approved by LWUA-BOT for submission to the Oversight\n10\nPOMA Hologram # 24229\n\n..\nRole of Financial Institution - The classification of WSPs\nshall merely be a determinant of eligibility for the various sources of financing,\nand shall not in any way be construed as an outright guarantee of actual\nfinancing from the designated source.\nFINAL PROVISIONS\nThe Oversight Committee shall formulate the IRR of this\nOrder within 90 days from its effectivity, which shall be published in accordance\nwith the requirements of the Administrative Code of 1987 and other pertinent\nThe Oversight Committee shall cease to exist three (3) years\nafter the approval by the President of the rationalized organization and\nmanpower structure of LWUA, with any remaining function of the Committee to\nbe assumed by the DOF.\nAny violation of this Order and of its IRR shall be subject to\ndisciplinary action and other penalties as provided for in said IRR and other\nrelevant laws and issuances.\nIf any provision of this Order is declared unconstitutional or\ninvalid, the other provisions not affected thereby shall remain in full force and\nAll orders, executive issuances, rules and regulations,\nadministrative resolutions, or parts thereof, inconsistent with the provisions of\nthis Order are hereby repealed or modified accordingly."}},{"id":"PH-H19050-A19","no":19,"noLabel":{"en":"SEC 19"},"text":{"en":"This Order shall take effect upon its publication in the Official\nGazette or in a newspaper of general circulation in the Philippines.\nDONE, in the City of Manila, this 2nd day of FEB\nin the vear of our\nLord, Two Thousand and Four.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE010090\nPOMA Hologram * 24230\n11"}}],"pack":"ph-p158"};
  FT["PH-H19051"] = {"id":"PH-H19051","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 279","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00279_2008.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00279_2008.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19051-A1","no":1,"noLabel":{"en":"SEC 1"},"text":{"en":"Transfer to the Department of Health - The LWUA is hereby attached to\nthe Department of Health. The LWUA Board of Trustees, however, shall be\nappointed by the President of the Philippines."}},{"id":"PH-H19051-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"All orders, executive issuances, rules and regulations, administrative\nresolutions, or parts thereof, inconsistent with the provisions of this order are hereby\nrepealed or modified accordingly."}},{"id":"PH-H19051-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"This order shall take effect immediately.\nDONE in the City of Manila, this IS day of August, in the year of Our Lord, Two\nThousand and Eight.\nflair A. herage\n^7523\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMA Hologram # 45236"}}],"pack":"ph-p158"};
  FT["PH-H19052"] = {"id":"PH-H19052","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 280","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00280_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00280_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19052-A1","no":1,"noLabel":{},"text":{"en":"4230\nOFFICIAL GAZETTE\nof Japanese and other foreign nationals previously placed\nunder the administration and disposition of the National\nAbaca and Other Fibers Corporation, pursuant to the\nprovisions of Executive Order No. 29, dated November 25,\n1946, and Executive Order No. 99, dated October 22, 1947,\nwhich are actually occupied and/or cultivated and developed\nby war veterans and other persons at their own expense, ;\nare hereby returned to, and placed under, the jurisdiction, *\ncontrol and disposition of the Department of Agriculture\nand Natural Resources and the Burean of Lands, in ac-\ncordance with the provisions of Act No. 3638 and Cormon-\nwealth Act No. 141, as amended.\nThe Bureau of Lands shall cause the lands herein in-\nvolved to be surveyed to determine the actual occupants\nthereof; to require the actual occupants to file sales ap-\nplications for their respective holdings, and to pay the\nnecessary. occupation fees to said Bureau from the time\nit takes over the administration thereof, and to take such\nother steps as may be necessary in accordance with existing\nlaws and regulations for the proper administration and\ndisposition of said lands.\nExecutive Orders Nos. 29 and 99, dated November 25,\n1946, and October 22, 194%, respectively, are hereby\nmodified accordingly.\nDone in the City of Manila, this 12th day of October,\nin the year of Our Lord, nineteen hundred and forty-nine,\nand of the Independence of the Philippines, the fourth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19053"] = {"id":"PH-H19053","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1957/eo_280_1957.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Waiving the Additional Progressive Taxes to Be Collected From, and Paid By, Proprietors and Operators of Certain Sugar Mills for the Crop Year 1956-1957","orig":"Waiving the Additional Progressive Taxes to Be Collected From, and Paid By, Proprietors and Operators of Certain Sugar Mills for the Crop Year 1956-1957"},"level":"law","status":"active","docNumber":"Executive Order No. 280","issuingBody":"President of the Philippines","promulgatedDate":"1957-11-19","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00280_1957_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00280_1957_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19053-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 280, November 19, 1957 ]\nWAIVING THE ADDITIONAL PROGRESSIVE TAXES TO BE COLLECTED FROM, AND PAID BY,\nPROPRIETORS AND OPERATORS OF CERTAIN SUGAR MILLS FOR THE CROP YEAR 1956-1957\nWHEREAS, most of the sugar centrals in the Philippines are still undertaking the rehabilitation of their\nfacilities, including the buildings and dwelling houses of their laborers, which were damaged during the last\nwar, and are incurring heavy expenditures for this purpose;\nWHEREAS, some of these centrals have been operating at a loss, and others at profits which are\ninconsiderable; and\nWHEREAS, the imposition of the additional progressive taxes on these centrals would be unduly oppressive\nand, in a few instances, even confiscatory in effect;\nNOW, THEREFORE, I, CARLOS P. GARCIA, President of the Philippines, do hereby waive the additional\nprogressive taxes to be paid by the proprietors and operators of the following sugar mills for the 1956-1957\ncrop under section 2 of Commonwealth Act No. 567:\n1. Ormoc Sugar Company, Inc., provided that the central shall continue to give its planters transportation\nallowances as provided for in the revised milling contract between the central and its planters.\n2. Bog-Medellin Milling Co., Inc., provided that improvements being undertaken to increase the capacity of\nthe mill and factory shall be continued and that the increase in the planters’ participation of 1 ½%given since\n1952-1953, thus making the planters’ participation 57-½%, in addition to the escalator clause giving the\nplanters 60% of all sugar and molasses manufactured from and including the 131st milling day, shall be\ncontinued to be enforced,\n3. Asturias Sugar Central, Inc., provided that the planters’ participation shall continue to be increased to\n57-½%.\n4. Central Azucarera Don Pedro.\n5. Central Azucarera del Norte.\n6. Hind Sugar Company, provided that 55% of the equivalent of the progressive tax shall be paid to the central\nplanters as additional benefits.\n7. Central Santos Lopez Co., Inc., provided that the planters’ participation shall be increased as follows until\nthe planters’ participation will have reached 60% effective the crop year 1957-1958 as provided for in the\n10-year contract between the central and the planters:\n58-½% for the crop year 1956-1957; and\n60% effective the crop year 1957-1958."}}],"pack":"ph-p158"};
  FT["PH-H19054"] = {"id":"PH-H19054","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1970/eo_280_1970.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating a Presidential Census Coordinating Board, Authorizing the Establishment of Local Census Boards, and Proclaiming April 1, 1971, as Census Day for Agriculture and Fisheries.","orig":"Creating a Presidential Census Coordinating Board, Authorizing the Establishment of Local Census Boards, and Proclaiming April 1, 1971, as Census Day for Agriculture and Fisheries."},"level":"law","status":"active","docNumber":"Executive Order No. 280","issuingBody":"President of the Philippines","promulgatedDate":"1970-12-13","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00280_1970_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00280_1970_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19054-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 280, December 13, 1970 ]\nCREATING A PRESIDENTIAL CENSUS COORDINATING BOARD, AUTHORIZING THE\nESTABLISHMENT OF LOCAL CENSUS BOARDS, AND PROCLAIMING APRIL 1, 1971, AS CENSUS\nDAY FOR AGRICULTURE AND FISHERIES\nWHEREAS, Commonwealth Act No. 591 authorizes the Bureau of the Census and Statistics “to prepare for\nand undertake all censuses of population, agriculture, industry and commerce”, and to conduct, for statistical\npurposes, investigations and studies of social and economic problems and conditions in the country; and\nRepublic Act No. 6130 sets aside an appropriation for the taking of the 1971 Censuses of Agriculture and\nWHEREAS, pursuant to the provisions of the above-mentioned Acts, the Bureau of the Census and Statistics\nwill undertake the 1971 Censuses of Agriculture and Fisheries; and\nWHEREAS, to insure the success of this nationwide undertaking, it is deemed necessary to enlist the\ncooperation and assistance of the various agencies of the national government as well as the local\ngovernments;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby create a Presidential Census Coordinating Board, which shall be responsible\nfor the systematic coordination of government agencies and instrumentalities involved in the conduct of the\n1971 Censuses of Agriculture and Fisheries, to be composed of the following:\nThe Executive Secretary\nThe Secretary of Commerce and Industry\nVice-Chairman\nThe Secretary of National Defense\nThe Secretary of Education\nThe Secretary of Public Works and Communications\nThe Secretary of Agriculture and Natural Resources\nThe Presidential Assistant on Community Development\nThe Director-General of the Presidential Economic Staff\nThe Board is hereby authorized to issue such rules and regulations as may be necessary to carry out the\nobjectives of this Order.\nAs counterpart of the Presidential Census Coordinating Board, at the local government level, there shall be\nestablished Provincial, City, Municipal/Municipal District and Barrio Census Board in each province, city,\nmunicipality/municipal district and barrio to act as a consultative body and to provide such facilities and\nassistance as shall be required by the Bureau of the Census and Statistics in the conduct of the 1971 Censuses\nof Agriculture and Fisheries within their respective jurisdictions without extra compensation.\nThe Provincial Census Boards shall be composed of the Provincial Governors as chairman, and the highest\nranking provincial officials of the Philippine Fisheries Commission, the Bureau of the Agricultural\nEconomics, and the Agricultural Productivity Commission or, in their absence, the officials acting in their\nstead, Division Superintendents of Schools, Provincial PACD Officers, Philippine Constabulary Commanders\nand Provincial/District Engineers, as members.\nThe City Census Boards shall be composed of the City Mayors as chairman, and the highest ranking city\nofficials of the Philippine Fisheries Commission, the Bureau of Agricultural Economics, and the Agricultural\nProductivity Commission or, in their absence, the officials acting in their stead, City Superintendents of\nSchools, City PACD Officers and City Engineers, as members.\nThe Municipal/Municipal District Census Boards shall be composed of the Municipal/Municipal District\nMayors as chairman, and the highest ranking municipal/municipal district officials of the Philippine Fisheries\nCommission, the Bureau of Agricultural Economics, and Agricultural Productivity Commission or, in their\nabsence, the officials acting in their stead, municipal PACD Officers, Public School Supervisors or Principal\nTeachers, as members.\nEach Provincial, City, and Municipal/Municipal District Census Board shall have a Secretariat to be headed\nby an Executive Officer, which shall be composed of personnel from the different bureaus and agencies\nrepresented in the Presidential Census Coordinating Board as well as from local governments. The Executive\nOfficer of the Presidential Census Coordinating Board shall be the Director of the Bureau of the Census and\nStatistics.\nThe Barrio Census Boards shall be composed of the Barrio Captains as chairman, and the Barrio Councils and\nPublic School Head Teachers in the barrios, as members.\nThe supervisors, enumerators and other subordinate personnel for the census work shall be appointed by the\nDirector of the Census and Statistics and/or may be drafted from personnel of the Government, including\nprovincial, city and municipal officials and employees, school teachers, field forces of the different bureaus\nand offices of the national government, city and municipal police forces, members of the Armed Forces of the\nPhilippines, and barrio captains.\nAll heads of departments, bureaus, offices and agencies of the government, including provincial, city and\nmunicipal officials, and Philippine Constabulary Provincial Commanders, are hereby enjoined to make\navailable for purposes of census taking their facilities as well as the services of such personnel as may be\nrequested or requisitioned by the Bureau of the Census and Statistics.\nApril 1, 1971, is hereby designated as Census Day for Agriculture and Fisheries on which date collection of\nall pertinent data shall commence and shall proceed on consecutive days from daylight to darkness including\nSaturdays, Sundays and holidays until finally completed.\nDone in the City of Manila, this 13th day of December, in the year of Our Lord, nineteen hundred and\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) ALEJANDRO MELCHOR\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19055"] = {"id":"PH-H19055","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"EXECUTIVE ORDER NO.","orig":"EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 280","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00280_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00280_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19055-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"-Con\nproce ssing\nincen tives.\n-\nand existing\npresidential\nadministrative\nand regulations,\n1352,\nas an interruption,\ndisruption,\ndiminution\nment whatsoever\nprivileges,\nand incentives\n1352,\neffect.ivi~y..\nXmplementation.\nDepartment\n.\nRegulatory\nthe Philippines,\nPhilippine\nand such other\nand instrumentalities\nas may be resp°I!sible\nobservance,\napplication\nand implementation\n-.\n1352,\nto facilitate\nparticularly\nand Customs\nthe Philippines\nand the National\nexecu ti ve orders,.\ninstructions,\nof implementation,\nregulations-inconsistent\nprovisions\nsuperseded\naccordingl)'.\n-\n\n-\n!\nSeparability\nprovisions-\nOrde~ are declared\nto be separable.,\nany pr?vision\nor the application\nor unconstitutional,\nthe validity\nprovisions\nnot be affected\n\",.,' ,\n~\nEffectivitr.\nimmed~ately\nupon completion\npublication\nand\" Eighty-Seven.\n~..,\n..\n..0'\n,\".\n-\n#ii.ER P. ARROYO\n'\"'\n."}}],"pack":"ph-p158"};
  FT["PH-H19056"] = {"id":"PH-H19056","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO.","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 280","issuingBody":"President of the Philippines","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00280_1995.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00280_1995.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19056-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Leadership, Composition and Organizational Structure. The Task\nForce shall be headed by the Chief, Intelligence Service, Armed Forces of the Philippines,\nassisted by a PNP officer who shall serve as the Deputy Task Force Commander for\nIntelligence/Operations, and an NBI official who shall be designated as the Deputy Task\nForce Commander for Investigation and Legal Affairs. Structurally, the Task Force shall be\norganized as follows:\nDirectly under the Task Force Commander are the Executive Officer\nand a functional staff that shall assist the Task Force Commander in\n\n2\nthe implementation, supervision and orchestration of the Task Force\npolicies and orders within their respective functional areas.\nA Task Force Operations Center (TFOC) shall be created to monitor and\norchestrate the day-to-day operational activities of the Task Force. It\nshall be manned by elements from the different agencies involved.\nComponent force shall be organized separately to be composed of\ncompetent and dedicated elements from the PNP, NBI, DOJ, NICA,\nAFP Major Service CI Units, ISAFP and other units/agencies concerned,\nas may be deemed necessary. They shall be directly under the\nsupervision and control of the Task Force Commander.\nThe national organizational setup shall be replicated or similarly\norganized in the regions except the National Capital Region which shall\nbe placed under the jurisdiction of the NCR-based national\norganization. The creation of Regional Task Groups outside NCR shall\nbe phased in and selectively determined according to operational\nnecessity. Among the regions which will be given priority after NCR are\nRegion 9, Region 12, the Autonomous Region for Muslim Mindanao\n(ARMM), Region 7, Region 6, Region 3, and Region 4. Other regions\nmay follow as the need arises.\nThe Assistant Group Commanders of the Field Military Intelligence\nGroups, ISAFP, shall act as the Regional Task Group Commander for\ntheir respective regions.\nTransportation, communications, firearms and individual equipment of\npersonnel of the component forces shall be provided by their respective\nmother agencies."}},{"id":"PH-H19056-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Coordination. The Task Force is hereby authorized to enlist the assistance\nof any branch, department, bureau, office, agency or instrumentality of the Government,\nincluding government-owned and/or controlled corporations, in the performance of its\nofficial functions."}},{"id":"PH-H19056-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Command and Control. The line of command and control of the Task\nForce is as follows:\nThe Task Force Commander shall report and be directly responsible to\nthe President.\nThe Task Force Commander shall have the direct responsibility,\nsupervision and control over all component forces of the Task Force. He\nis hereby authorized to select and designate all the personnel who will\nwork under him.\nThe component forces/elements from the NBI, PNP, DOJ, NICA and\nAFP Service Counterintelligence Units must be attached and assigned\n\n3\nto the Task Force, i.e., their respective mother units shall provide/assign\na permanent force to the Task Force. The component force so attached\nand assigned shall hold office or report to the Task Force Headquarters\ndaily. The Task Force Commander shall have directive and supervisory\nauthority over them.\nEach component force shall have a designated Commander who shall\ndirectly be responsible for his unit. He shall report and receive orders\ndirectly from the Task Force Commander."}},{"id":"PH-H19056-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Powers and Functions. The Task Force shall have the following powers\nand functions:\nConduct intelligence and counterintelligence operations to detect and\nidentify active and former military and police personnel and their\ncohorts involved in criminal activities.\nCause or direct the immediate arrest, investigation and speedy\nprosecution of such military and police personnel and their cohorts in\naccordance with constitutional processes.\nRefer the cases at hand, as the Task Force may deem proper and\nnecessary, in the interest of efficient and expeditious dispensation of\ncriminal justice, to the Presidential Anti-Crime Commission (PACC\nand/or other appropriate law enforcement agency or prosecution office,\nfor investigation or prosecution, as the case may be.\nMonitor the progress of on-going investigation and prosecution of cases\ntaken cognizance of wy the Task Force.\nRecommend appropriate anti-crime issuances and legislations to the\nPresident, PACC and Congress.\nConduct other special anti-crime operations as the President may direct."}},{"id":"PH-H19056-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"Duties and Tasks. The Personnel and component units of the Task Force\nshall perform the following duties and tasks:\nTask Force Commander. Principally responsible for the successful\nimplementation of Task Force mission and functions, directs and\nsupervises the overall conduct of Task Force operations and perform\nsuch other functions as the President may direct.\nDeputy Task Force Commander for Intelligence/Operations.\nAssists and advises the Task Force Commander on matters pertaining\nto intelligence/operations.\n\nPROPOSED ORGANIZATIONAL STRUCTURE\nOF TASK FORCE \"HAMMERHEAD\nIntel/Operation\nLegal & Investigation\nInvestigation\nComponment\nTask Groups\n*TFOC - Task Force Operation Center\n\n4\nDeputy Task Force Commander for Legal and Investigation.\nAssists and advises the Task Force Commander on legal and\ninvestigation matters.\nExecutive Officer. Principal Staff Adviser of the Task Force\nCommand. Supervises and ensures that all policies and instructions of\nthe Task Force Commander are properly implemented by concerned\nstaff officers; ensures the normal and smooth functioning and\ncoordination of staffs.\nWorking Staff. Advises and is responsible to the Commander on\nvarious matters including personnel, supply and logistics requirements,\ntechnical and signal support, intelligence/operations,\nlegal/investigation matters.\nTask Force Operations Center (TFOC). Monitors the day to day\noperational activities of the Task Force.\nDO Component. Directly responsible for the prosecution of cases and\nsecuring Warrants of Arrest and Search Warrants\nNICAPNP/NBI/AFP Major Service and ISAFP CI Units and\nOther Components. Conduct case buildup and counteraction\noperations against targeted personalities/syndicates. Gather, collect and\npreserve pieces of evidence for use against targeted suspects.\n1. Regional Task Groups (RTG's). Conduct case buildup, counteraction\noperations and prosecution of targeted criminal syndicates in their\nrespective AORs."}},{"id":"PH-H19056-A7","no":7,"noLabel":{"en":"SEC 7"},"text":{"en":"Operating Guidelines. In the implementation of this Executive Order, the\nTask Force must follow the following guidelines:\nThe Task Force shall focus its efforts primarily against scalawags in the\nAFP and other law enforcement agencies, or their former members,\ninvolved in criminal activities although in the process, the Task Force\ncan initiate neutralization measures against their associated and\naccomplices in these crime syndicates.\n'The destruction of organized big-time criminal groups/syndicates\ninvolving military, police and former military, or police personnel shall\nbe the operational priority of the Task Force. Along this line, it shall\ndirect its efforts against the following criminal activities.\nKidnap for Ransom\n2.\n)\n)\n)\nPrimary/Immediate\nRobberies of Banks,\nPawnshops, etc.\n\n5\n3. Drug Trafficking\n)\n4. Gunrunning\n)\n5. Carnapping\nAll operations conducted shall have prior clearance and knowledge of the\nTask Force Commander. The Intelligence and Operation Officer shall\nclosely monitor and supervise the conduct of the operation.\nOn orders/instructions of the Task Force Commander, component forces\nmay operate either independently or jointly depending on the nature of\nthe target and operational necessity or practicality.\nRespective component forces will be given the first opportunity to conduct\ninvestigation/case build-up of identified scalawags in their respective\nunits/agencies.\nCounteraction operations conducted against target personalities are\nprimarily aimed at bringing the suspects to the bar of justice for\nsuccessful prosecution."}},{"id":"PH-H19056-A8","no":8,"noLabel":{"en":"SEC 8"},"text":{"en":"Funding. The Task Force shall be provided with an initial\nallocation of TWENTY MILLION PESOS (P20,000,000) to be drawn from the Office\nof the President's contingency fund and/or from the government's savings for CY\n1995, and such amount as may be approved by the President to be drawn from the\nContingency Fund for CY 1996, thereafter to be included in the annual budget of the\ngovernment."}},{"id":"PH-H19056-A9","no":9,"noLabel":{"en":"SEC 9"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 16th day of October in the year of Our Lord,\nNineteen Hundred and Ninety-Five.\nBy the President:\nRUBEN D. TORRES\nExecutive Secretary\nRCGIJFL/mao ROM"}}],"pack":"ph-p158"};
  FT["PH-H19057"] = {"id":"PH-H19057","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"AiVIENDING ORDER ~O. 45 DATED JANUARY OS, 1993 ADOPTING PHILIPPINE SYSTEM OF. 1992 AS THE REFERENCE SYSTEM OF SVRVEYS IN THE PHILIPPINES","orig":"AiVIENDING ORDER ~O. 45 DATED JANUARY OS, 1993 ADOPTING PHILIPPINE SYSTEM OF. 1992 AS THE REFERENCE SYSTEM OF SVRVEYS IN THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 280","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00280_2000.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00280_2000.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19057-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The third sentence of Section 2 of Executive Order No. 45 dated January.\n05,1993 is hereby amended to read as follows:\n:::::..\n\"SEC. 2. x x x There shall be a transition period up to year 2005 to allow::::...\nintegration of the old surveys, after which only PRS Q2 shall be recognized as the.:::\nstandard reference system for all surveys and maps in the country.\"\n.: ..."}},{"id":"PH-H19057-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"This Order shall take effect immediately.\nDone in the City of Manila\" this {4 1\\1'\\\ntwo thousand.\n, in the year of Our Lord.\nr; .~s LIBRARYj\n~\n.,.\nBy the President:\nRONALDO B. ZAMORA\n-Executive Secretary\nPMS LIBRARY BCODEOO4430"}}],"pack":"ph-p158"};
  FT["PH-H19058"] = {"id":"PH-H19058","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES DEFINING THE POWERS, FUNCTIONS, AND RESPONSIBILITIES OF GOVERNMENT AGENCIES IN RESPONSE TO AVIAN INFLUENZA (AI) OR BIRD FLU VIRUS AND RELATED MATTERS THERETO","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES DEFINING THE POWERS, FUNCTIONS, AND RESPONSIBILITIES OF GOVERNMENT AGENCIES IN RESPONSE TO AVIAN INFLUENZA (AI) OR BIRD FLU VIRUS AND RELATED MATTERS THERETO"},"level":"law","status":"active","docNumber":"Executive Order No. 280","issuingBody":"President of the Philippines","completenessNote":"全文，共 10 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00280_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00280_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19058-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Crisis Manager. - The Secretary of Health is hereby\ndEsignated Over-all Crisis Manager for the Avian Influenza or Bird Flu Virus\npandemic influenza.\nmade Hologram • 24306\n\nThe Department of Agriculture, through the Secretary of Agriculture, is\nhereby designated as Co-Manager for matters pertaining or primarily affecting\npoultry, birds, other fowl, and any other animal, including their by-products."}},{"id":"PH-H19058-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Delineation of Powers and Authority. - The Secretary of\nHealth is hereby granted and bestowed such powers and authority as would be\nnecessary in order to prevent, restrict, or otherwise regulate the entry,\nmovement, or surveillance of people coming from infected countries or in any\ninstance where the highly pathogenic avian influenza has infected, or suspected\nto have infected, humans.\nThe Secretary of Agriculture is hereby granted and bestowed such powers\nand functions as would be necessary in order to contain, control, prevent,\nregulate and otherwise restrict the entry, movement, proliferation, of poultry,\nfowl, birds, and other animals, including their by-products, which are infected, or\nsuspected to be, infected or potential carrier of the Avian influenza virus."}},{"id":"PH-H19058-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The Secretary of Health: Specific Area of Concern and\nResponsibility. - The Secretary of Health shall exercise such powers and\nprerogatives, incidental or otherwise, as would:\na. Prevent, minimize, regulate, or otherwise restrict the entry of\nthe avian flu virus, through the Bureau of Quarantine and\nInternational Health Services (BQIHS), by adopting, restricting,\nor regulating the movement and entry of people coming from\ninfected countries or other countries suspected to be carriers, or\npotential carriers, of the virus, through a system of surveillance\nmethods utilizing rigid screening and identification procedures in\nall ports of entry, and adopting isolation and quarantine\nmeasures whenever deemed necessary;\nb. Prevent, minimize and regulate the spread and local\ntransmission of the virus through enforcement of triage, contact\ntracing, surveillance, quarantine and isolation procedures of\npeople, as may be appropriate;\nc. Care, render assistance, cure, or minimize death or sickness\nthrough effective clinical management of people, resources,\nhospitals, and other facilities, whether public or private;\nThe Secretary of Health shall also exercise such other functions and\npowers as may be incidental, related or otherwise connected with the\nabove mentioned authority.\nPGMA Helegram • 24307"}},{"id":"PH-H19058-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The Secretary of Agriculture: Specific Area of Concern\nand Responsibility. - The Secretary of Agriculture shall take such measures\nand actions as would:\na. Prevent, Restrict, minimize or otherwise regulate the entry of\npoultry, fowl, birds, or other animals coming from infected\ncountries or from any other country which are potential or\nsuspected to be, afflicted or carriers of the avian flu virus,\nincluding the imposition of total or partial bans on imports of\npoultry and other animals;\n• .\nb. Conduct surveillance, mapping, identification,\nquarantine of chickens, their by-products, and other animals\ninfected or suspected to be infected by the avian flu virus within\nthe country, or any part thereof, including the culling or\nstamping out of infected chickens and quarantine of chicken or\npoultry farms and other affected areas, as may be determined\nby the Secretary.\nc. Monitor, trace, plot, or otherwise observe, in coordination with\nthe Department of Environment and Natural Resources (DENR),\nthe sanctuaries and movement patterns of migratory birds from\nwithin and without the country taking into consideration the\nsafety and well being of the people and giving due regard to\nThe Secretary of Agriculture shall also exercise such other functions\nand powers as may be incidental, related or otherwise connected with the\nabove mentioned authority."}},{"id":"PH-H19058-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Information Dissemination and Coordination. - As Crisis\nManager, the Secretary of Health shall have the responsibility to:\na. Continuously educate and disseminate information, as\nappropriate, in order to prepare and educate the media and the\ngeneral public with a better understanding of the avian flu virus,\npromote positive health values and behavior, and prevent\ndisinformation, confusion, or panic;\nb. Coordinate responses together with other government agencies\nand the private sector through meetings, conferences and the\nlike; or otherwise constructively engage the public and affected\nsectors in general;\nPOMA Hologram • 24308\n\n)\nc. Issue the necessary bulletins, advisories and health warnings on\nmatters concerning the foregoing."}},{"id":"PH-H19058-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Assistance and Support. - The Over-All Crisis Manager is\ntereby empowered to call upon all agencies of Government for support and\nasistance in the enforcement of this Order, including but not necessarily limited\nDepartment of Agriculture (DA)\nDepartment of Interior and Local Government (DILG);\nDepartment of Foreign Affairs (DA);\n•\nDepartment of Transportation and Communications (DoTC);\nDepartment of Finance (DoF);\nDepartment of Education (DepEd);\nDepartment of Labor and Employment (DOLE);\nDepartment of National defense (DND);\nOffice of the Press Secretary (OPS);\nThe Crisis Manager shall be empowered to seek the assistance and\nsport of the abovementioned agencies, including their respective attached\nofices, in order to effectively implement the provisions of this Order.\nAll agencies, offices, managers, and personnel are hereby directed to\noperate and provide such assistance and support as may be requested or\nneeded by the Crisis Manager in the containment of the Avian flu virus.\nDefense and law enforcement agencies, particularly the Armed Forces of\ntre Philippines (AFP), the Philippine National Police (PP) and the Philippine\nCast Guard (PCG), shall give priority to the directives or orders issued and\npromulgated by the Crisis Manager affecting their specific areas of concern."}},{"id":"PH-H19058-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Funding. - An amount not exceeding Two Hundred Fifty Million\n(# 250,000,000.00) Pesos is hereby set aside from the funds of the Philippine\nCrarity Sweepstakes Office (PCSO) to cover the financial requirements of this"}},{"id":"PH-H19058-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"Rules and Regulations. - The Secretary of Health shall\npromulgate such rules and regulations as may be necessary, related, incidental\no* consistent with the purpose, intent, and objective of this Order."}},{"id":"PH-H19058-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"Applicability of Executive Order No. 201. - For purposes of\nths Order and in so far as it may be practicable, the provisions of Order No. 201,\nseres of 2003, shall be deemed suppletory hereto.\nen Hologram • 24309"}},{"id":"PH-H19058-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Constitutionality. - Should any of the provisions contained\nherein be declared illegal or unconstitutional, the rest or other such provisions\nnot so declared shall remain valid and effective.\nEffectivity. - This Executive Order shall take effect\nimmediately.\nDONE in the City of Manila, this 5tbday of February, in the year of Our\nLord, Two Thousand and Four.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPOMA Hologram / 24310"}}],"pack":"ph-p158"};
  FT["PH-H19059"] = {"id":"PH-H19059","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"M ALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES EFFECTUATING THE PURPOSES OF GENERAL RULING NO. 5, JUNE 6,1940, OF THE SECRETARY OF THE TREASURY OF THE INITED STATES, APPROVED JUNE 6,1940, BY THE PRESIDENT OF THE UNITED STATES, UNDER SECTION 5 (8) OF THE ACT OF OcTOBER6,1917(40sTAT.411),AsAMENDED,EXEcurIVEORDERNO.8389OFAPRILio, 1940,ASAMENDED,OFTHEPRESIDENTOFTHEUNITEDSTATESANDREGULATIONS ISSUED PURSUANT THERETO AND UNDER ALL OTHER AUTHORITY OF LAW.","orig":"M ALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES EFFECTUATING THE PURPOSES OF GENERAL RULING NO. 5, JUNE 6,1940, OF THE SECRETARY OF THE TREASURY OF THE INITED STATES, APPROVED JUNE 6,1940, BY THE PRESIDENT OF THE UNITED STATES, UNDER SECTION 5 (8) OF THE ACT OF OcTOBER6,1917(40sTAT.411),AsAMENDED,EXEcurIVEORDERNO.8389OFAPRILio, 1940,ASAMENDED,OFTHEPRESIDENTOFTHEUNITEDSTATESANDREGULATIONS ISSUED PURSUANT THERETO AND UNDER ALL OTHER AUTHORITY OF LAW."},"level":"law","status":"active","docNumber":"Executive Order No. 281","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00281_1940.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00281_1940.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19059-A1","no":1,"noLabel":{},"text":{"en":"MESSAGES   0F   THE   PRESIDENT\nQl/E`,ZON  I  Vo/wn}e 4\nWhereas,  on  June  7,  1940,  the  Secretary  of  the  Treasury  of  the  United  States  provided  that,\nuntil   further  notice,  securities   coming  into  the  Unit€d   States   from   Great  Britain,  France,  Canada`\nNewfoundland  or  Bermuda  need not  be  forwarded to  a  Federal  Reserve  Bank  for  examination under\nsaid General Ruling No. 5; and\nWhereas  the  United  States  High  Commissioner  to  the  I'hilippines  has  been  designated  as  the\nperson  to  whom  any  securities  or  evidences  thereof  brought  Into  the  Philippines  as  provided  in  said\nGeneral Ruling No. 5 should be delivered as therein provided, in lieu of a Federal Reserve bank;\nNow,  therefore,  pursuant  to  the  authority  herein  stated,  and  to  the  authority  vested  in  me  as\nPresident  of  the  Philippmes,  in  order  to  assist  in  effectuating  the  purposes  of  said  General  Ruling\nNo.  5  and the  delivery to  the United  States High  Commissioner to the Philippines  of any securities  or\nevidences thereof brought into the Philippines, as aforesaid, it is hereby ordered that:\n1.    The Insular Collector of Customs of the Commonwealth of the Philippines shall deliver to the\nUnited States High Commissioner to the Philippines all securities and all evidences of securities coming\ninto  the  Philippines  on  and  after  June  7,1940,  from  any  foreign  country,  other  than  Great  Britain,\nFrance,  Canada,  Newfoundland  or  Bermuda,  which  to  his  knowledge  may  come  into  his  possession\nor custody  or  into  that  of any  officer  or  employee  of the  Bureau  of  Customs  of the  Commonwealth\nGovernment, for the purposes in said General Ruling No. 5, in exchange for the written receipt therefor\nof said United States High Commissioner or his authorized agent.\n2.     The  Director  of  Posts  of  the  Commonwealth  of the  Philippines  shall  deliver  to  the  United\nStates  High  Commissioner  to  the  Philippines  all  securities  and  all  evidences  of securities  coming  Into\nthe Philippines on  and  after June  7,  1940, from any foreign  country, other than  Great Britain, France,\nCanada, Newfoundland or Bermuda, which to his knowledge may come into his possession or custody\nor Into that of any  officer or employee of the Bureau  of Posts of the  Commonwealth Government, for\nthe purposes  in said  General  Ruling No.  5, in  exchange  for the  written  receipt therefor of said United\nStates High Commissioner or his authorized agent.\n3.     The  Insular  Collector  of  Customs  shall  cause  all  articles  coming  into  the  Philippines  from\nany  foreign  country  other  than  Great  Britain,  France,  Canada,  Newfoundland  or  Bermuda  through\nthe  Bureau  of Customs  of the  Commonwealth  of the  Philippines  on  and  after June  7,  1940, which  in\nthe opinion  of any customs officer c>r employee may contain  securities  or evidences of securities, to  be\ninspected  by  officers  or  employees  of  said  Bureau  thereunto  by  him  authorized,  in  accordance  with\nexisting customs and postal regulations.\n4.     If any artlcl€ opened  by an addressee  or his  agent in the presence  or  under the supervlslon of\na  customs  officer  or  employee  is  found  to  contain such  securities  or  evidences  thereof,  such  securities\nor evidences thereof shall  be surrendered forthwith to such customs officer or employee for delivery to\nthe Insular Collector  of Customs, who thereupon  forthwith shall deliver the same to the United  States\nHigh Commissioner to the Philippmes as hereinabove provided.\n5.     The  Director  of  Posts  shall  cause  all  articles  coming  into  the  Philippines  from  any  foreign\ncountry other than  Great Britain, France,  Canada, Newfoundland  or Bermuda through the  Bureau  of\nPosts of the  Commonwealth of the Philippines  on and after June 7,1940, which in the opinion of any\npostal  officer  or  employee  may  contain  securities  or  evidences  of securities,  tc)  be  inspected  by  officers\nor  employees  of  said  Bureau  thereun[o  by  him  authorized,  in  accordance  with  existing  customs  and\npostal regulations.\n6.     If any  article  opened  by  an  addressee  or  his  agent  in  the  presence  or  under  the  supervision\nof a  postal  officer  or employee is  found to contain such  securities or evidences thereof, such securities\nor  evidences  thereof  shall  be  surrendered  forthwith  to  such  postal  officer  or  employee  for  dellvery\nOFFICIAL   GAZETTE\nQU£ZON  I Volume 4\nto  the  Director  of  Posts,  who  thereupon  forthwith  shall  deliver  the  same  to  the  United  States  High\nCommissioner to the Philippines as hereinabove provided.\nDone at the  City of Manila, this fifteenth day of June, in the year of Our Lord, nineteen hundred\nand forty, and of the Commonwealth of the I'hilippines, the fifth.\nMANUEL L. QUEZON\nPresident of the  Philippines\nBy  the  I'resident:\n]ORGE 8. VARGAS\nSecretary to the Presideut\nSource.  Presidential  Museum and Library\nOffice  of  the  President  of the  Philippines.  (1940).  /Excc#f/I;e  Order  Nos.:  248  -399j.  Manila:\nPresidential Museum and Library."}}],"pack":"ph-p158"};
  FT["PH-H19060"] = {"id":"PH-H19060","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF LAPINIG,","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF LAPINIG,"},"level":"law","status":"active","docNumber":"Executive Order No. 281","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00281_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00281_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19060-A1","no":1,"noLabel":{},"text":{"en":"OFFICIAL GAZETTE\ndistrict of Jipapad, all of the Province of Samar, more\nparticularly described and bounded as follows:\nOn the north, northwest, and west, by a straight line running\nsouthwesterly from a point on the shore line half way between the\ncenter of the mouth of Gamay River and the poblacion of the barrio\nof Cagamutan to the intersection of the south branch of Gamay\nRiver with the trail connecting the barrios of Cagamutan and Bagon\nde Gamay, thence southwesterly to a point one-half kilometer west!\nof the poblacion of the barrio of Can Maria; on the southwest,\nby a straight imaginary line running from the said point one-half\nkilometer west of Can Maria to a point on Catumsan River ap-\nproximatcly une-half kilometer southwest of the poblacion of barrio\nCatumsan: on the southeast, by the course of the Catumsan River\ndownstream to the mouth of the said river which is at the Helm\nHarbur; and on the northeast, by the limits of municipal waters\nwhich Lapinig shall have pursuant to section 2321 of the Revised\nAdministrative Code.\nThe municipality of Lapinig contains the following\nbarrios: Cagamutan, Potong, Pio del Pilar, Canomanio,\nLouk, Lapinig, Can Maria and Catumsan, and the following\nsitios: Cahugwayan, Palanas and Mabini.\nThe municipalities of Gamay and Oras and the municipal\ndistrict of Jipapad shall have their present territories,\nminus and respective portions thereof included in the\nmunicipality of Lapinig.\nThe municipality of Lapinig shall begin to exist upon\nthe appointment and qualification of the mayor, vice-mayor,\nand a majority of the councilors thereof, but in ro case\nearlier than November 15, 1949.\nDone in the City of Manila, this 13th day of October, in\nthe year of Our Lord, nineteen hundred and forty-nine,\nand of the Independence of the Philippines, the fourth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary\n4231"}}],"pack":"ph-p158"};
  FT["PH-H19061"] = {"id":"PH-H19061","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1957/eo_281_1957.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Executive Order No. 271, Dated October 4, 1957, Entitled, Creating a Presidential Incentives Committee","orig":"Amending Executive Order No. 271, Dated October 4, 1957, Entitled, Creating a Presidential Incentives Committee"},"level":"law","status":"active","docNumber":"Executive Order No. 281","issuingBody":"President of the Philippines","promulgatedDate":"1957-12-18","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00281_1957_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00281_1957_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19061-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 281, December 18, 1957 ]\nAMENDING EXECUTIVE ORDER NO. 271, DATED OCTOBER 4, 1957, ENTITLED, “CREATING A\nPRESIDENTIAL INCENTIVES COMMITTEE”\nThe first paragraph of Executive Order No. 271, dated October 4, 1957, is hereby amended to read as follows:\n“By virtue of the powers vested in me by law, I, CARLOS P. GARCIA; President of the Philippines, do\nhereby create a Presidential Incentives Committee” to study ways and means of giving incentives to producers\nin order to increase production of principal products. The Committee shall be composed of the following:\nHon. Antonio de las Alas\nThe President, Chamber of Commerce of the Philippines\nThe President, Philippine Chamber of Industries\nThe President, Philippine Chamber of Agriculture\nThe President, Philippine Bankers Association\nMr. Gaudencio E. Antonio, President, Producers and Exporters Association of the Philippines\nMrs. Trinidad F. Legarda\nMr. Jose Hernandez\nMr. Domingo C. Abadilla, President, National Press Club\nMiss Helena Z. Benitez Secretary\nMember & Secretary"}}],"pack":"ph-p158"};
