  FT["PH-H19065"] = {"id":"PH-H19065","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACANANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 281","issuingBody":"President of the Philippines","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00281_2000.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00281_2000.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19065-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Transfer\nor Re-employment of NSF Personnel.\nNSF personnel\nshall be given priority in hiring\nfor existing vacant positions in other government\nagencies, subject to compliance with established qualification standards set by the\nreceiving agencies. The transfer to or re-employment of NSF personnel with other\nagencies shall be exempt from the prohibition on new hiring under Administrative\nOrder No. 100 dated December 1, 1999.\n'.~ ::;;,~:':'\n\"\"':-~\n\n2/\nSeparation\nRetirement\nof NSF Personnel.\npersonnel qualified\nfor retirement may elect optional retirement as they may deem\nbenefits, including\npayment of accrued leave\ncredits, that may\nbe given to NSF employees by virtue of\ntheir transfer, retirement or\nseparation from service shall be paid within one (I) month from the filing of the\nnecessary clearances and other pertinent documents."}},{"id":"PH-H19065-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Transfer of Assets and Liabilities.\nthe NSF are bereby transferred without cost to the\npending appropriate final disposition.\nAll assets and liabilities of\nDepartment of Agriculture"}},{"id":"PH-H19065-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Extension of Period.\nThe Special Task Force, in coordination\nwith other concerned agencies, is hereby given until September 30, 2000 within\nwhich to fully implement the deactivation of the NSF."}},{"id":"PH-H19065-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"Support of Other Agencies.\nThe Special Task Force may\nrequest assistance from the Civil\nService Commission and the Commission on\nAudit and such other agencies as may be necessary to assist in\nimplementation of this Order."}},{"id":"PH-H19065-A7","no":7,"noLabel":{"en":"SEC 7"},"text":{"en":"Funding Requirements.\nFunds for existing vacant positions in\nother agencies to be filled up by NSF personnel shall be sourced from agency\nrequest, augmented by\nDepartment of\nManagement (DBM).\nThe DBM shall give preference to the payment of accrued\ncredits, separation and retirement benefits to NSF personnel from the\nMiscellaneous Personnel Benefits fund."}},{"id":"PH-H19065-A8","no":8,"noLabel":{"en":"SEC 8"},"text":{"en":"Final Report.\nThe Special Task Force shall submit its final\nreport and recommendation on the deactivation of the NSF to the President not\nlater than September 30, 2000."}},{"id":"PH-H19065-A9","no":9,"noLabel":{"en":"SEC 9"},"text":{"en":"Separability Clause. Any portion or provision of this Executive\nOrder that may be declared unconstitutional shall not have the effect of nullifying\nother portions\nor provisions of the Order for as long as such remaining portions\ncan still subsist and be given effect.\n\n3/"}},{"id":"PH-H19065-A10","no":10,"noLabel":{"en":"SEC 10"},"text":{"en":"Repealing\nexecutive orders, rules, regulations and\nother issuances or parts thereof which are inconsistent with the provisions of this\nExecutive Order are hereby revoked or modified accordingly."}},{"id":"PH-H19065-A11","no":11,"noLabel":{"en":"SEC 11"},"text":{"en":"Effectivity.\nThis Executive Order shall take effect immediately.\nDone in the City of Manila, this -t); ~J. day of\nOur Lord, Two Thousand.\n~.\n.~:.~~~\nrft1S LIBRARY\n/'\n~19701\nBy the President:\nRAMON B. CARDENAS\nActing Executive Secretary\n\"\".\n12"}}],"pack":"ph-p158"};
  FT["PH-H19066"] = {"id":"PH-H19066","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES PROVIDING FOR DEFERMENT OF EVICTION, FORECLOSURE AND CANCELLATION ACCOUNTS AND FORMULATION AND IMPLEMENTATION OF AFFORDABLE LOAN RESTRUCTURING PROGRAMS DURING... SUCH DEFERMENT","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES PROVIDING FOR DEFERMENT OF EVICTION, FORECLOSURE AND CANCELLATION ACCOUNTS AND FORMULATION AND IMPLEMENTATION OF AFFORDABLE LOAN RESTRUCTURING PROGRAMS DURING... SUCH DEFERMENT"},"level":"law","status":"active","docNumber":"Executive Order No. 281","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00281_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00281_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19066-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Deferment of Eviction, Foreclosure and Cancellation of\nHousing Accounts. There shall be a deferment of eviction, foreclosure and\ncancellation of housing accounts for a period of six (6) months from date hereof."}},{"id":"PH-H19066-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Coverage. This deferment shall cover all delinquent housing loan\naccounts for cancellation and foreclosure, foreclosed accounts and consolidated\naccounts with all government agencies and institutions under the National\nShelter Program (NSP), such as the National Home Mortgage Finance\nCorporation (NHMFC), Home Development Mutual Fund (HDMF), Government\nService Insurance Corporation (GSIS), and Social Security System (SSS)."}},{"id":"PH-H19066-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Exclusions. However, this Order shall not apply to the following:\na. unoccupied housing units\nb. accounts with no single payment since take-out\nc. restructured accounts\nd. consolidated accounts which were already disposed through sale or\nrent-to-own scheme\ne. accounts covered by Developers Buyback Guarantee;\nPOMP Hologram # 24359"}},{"id":"PH-H19066-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Implementation of Affordable Loan Restructuring Program\n(ALRP). The concerned agencies and institutions shall review their existing loan\nrestructuring programs and remedial measures with the end in view of adopting\naffordable schemes and remedies with terms and conditions that borrowers will\nbe able to comply with.\nThe revised ALP shall be offered to borrowers for availment within fifteen\n(15) days from date hereof."}},{"id":"PH-H19066-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Creation of an Inter-Agency Task Force, An Inter-Agency Task\nForce shall be created composed of the following:\nSecretary General, HUDCC\nPresident, NHMFC\nPresident, HDMF\nPresident, GSIS\nPresident, SSS\nThe Task Force shall invite representatives from the Senate Committee on\nUrban Planning, Housing and Resettlement and the House Committee on\nHousing and Urban Development to its meetings.\nThe Task Force shall formulate the implementing rules and regulations of\nthis Order and the Affordable Loan Restructuring Program within fifteen (15)\ndays from date of this Order.\nThe Housing and Urban Development Coordinating Council (HUDCC) shall\nmonitor the compliance by the concerned agencies with this Order."}},{"id":"PH-H19066-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"This Executive Order shall take effect immediately.\nDONE in the City of Manila, this gth day of rebruary, in the year of Our\nLord, Two Thousand and Four.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE010056\nPONy Hologram • 24360"}}],"pack":"ph-p158"};
  FT["PH-H19067"] = {"id":"PH-H19067","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ORGANIZING CERTAIN BARRIOS OF THE MUNIC IPALITY OF PILA, PROVINCE OF LAGUNA, INTO AN INDEPENDENT MUNICIPALITY UNDER THE NAME OF VIETORIA.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ORGANIZING CERTAIN BARRIOS OF THE MUNIC IPALITY OF PILA, PROVINCE OF LAGUNA, INTO AN INDEPENDENT MUNICIPALITY UNDER THE NAME OF VIETORIA."},"level":"law","status":"active","docNumber":"Executive Order No. 282","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00282_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00282_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19067-A1","no":1,"noLabel":{},"text":{"en":"4232\n• OFFICIAL GAZETTE\nSan Roque, San Francisco, San Benito, Masapang, San\nFelix, Daniw, and Bancabanca, all of the municipality of\nPila, Province of Laguna, are hereby segregated from the\nsaid municipality and organized into an independent\nmunicipality, under the name of Victoria, with the seat of\ngovernment at the barrio of Nanhaya and San Roque,\nsubject to the condition that this municipality shall assume\nits proportionate part of the loan obligation of Pila to the\nNational Government, which may be outstanding as of the\ndate of the organization.\nThe muricipality of Pila shall have its present territory,\nminus the barrios of Nanhaya, San Roque, San Francisco,\nSan Benito, Masapang, San Felix, Daniw, and Bancabanca.\nThe municipality of Victoria, as herein organized, shall\nbegin to exist upon the appointment and qualification of\nthe Mayor, vice-mayor, and a majority of the councilors\nthereof, but in no case earlier than November 15, 1949.\nDone in the City of Manila, this 14th day of October,\nin the year of Our Lord, nineteen hundred and forty-\nnine and of the Independence of the Philippines, the\nELIDIO QUIrINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19068"] = {"id":"PH-H19068","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1957/eo_282_1957.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Municipality of Tambulig in the Province of Zamboanga Del Sur","orig":"Creating the Municipality of Tambulig in the Province of Zamboanga Del Sur"},"level":"law","status":"active","docNumber":"Executive Order No. 282","issuingBody":"President of the Philippines","promulgatedDate":"1957-12-27","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00282_1957_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00282_1957_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19068-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 282, December 27, 1957 ]\nCREATING THE MUNICIPALITY OF TAMBULIG IN THE PROVINCE OF ZAMBOANGA DEL SUR\nUpon the recommendation of the Provincial Board of Zamboanga del Sur and pursuant to the provisions of\nsection sixty-eight of the Revised Administrative Code, there is hereby created in the province of Zamboanga\ndel Sur a municipality to be known as the municipality of Tambulig to consist of the following barrios and\nFrom the Municipality of Molave\n1. Lower Calolot\n10. Bag-ong Tudela\n17. Bag-ong Kauswagan\n11.Bogo-Kalabat\n18. Bag-ong Tabogon\n12. Alang-alang\nFrom the Municipality of Aurora\n4. Lower Lingconan\n5. Lower Usugan\n7. Sumalig Island\nwith the seat of government at the barrio of Tambulig.\nThe municipality of Tambulig as herein organized shall have the following boundaries:\n“Beginning at Point 1, intersection of Dipolo River and the National Highway at Dipolo Bridge to Point 2,\nintersection of Gabonon Creek and National Highway following a northeasterly direction to a distance of\n4,400 meters; thence to Point 3, due north until it intersects the provincial boundary line between Zamboanga\ndel Sur and Zamboanga del Norte to a distance of 26,000 meters; thence to Point 4, due east following the said\nprovincial boundary until it intersects the provincial .boundary line to the province of Zamboanga del Sur and\nMisamis Occidental to a distance of 4,800 meters; thence to Point 5, due south following the said provincial\nboundary line until it intersects the National Highway to a distance of 29,400 meters; thence to Point 6, on\nPangil Bay following a southeasterly direction to a distance of 10,000 meters; thence to Point 7, on the mouth\nof Dipolo River following the shore, line to a distance of 12,000 meters; thence following the course of\nDipolo River, a distance of 24,000 meters to Point 1.” (This technical description is furnished by the Office of\nthe Highway District Engineer of the Province of Zamboanga del Sur based on the sketch of the map prepared\nand submitted by said Office.)"}}],"pack":"ph-p158"};
  FT["PH-H19069"] = {"id":"PH-H19069","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1971/eo_282_1971.html","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Republic Act Numbered Nineteen Hundred Thirty-Seven, Otherwise Known as the Tariff and Customs Code of the Philippines, as Amended.","orig":"Modifying the Rates of Import Duty on Certain Imported Articles as Provided Under Republic Act Numbered Nineteen Hundred Thirty-Seven, Otherwise Known as the Tariff and Customs Code of the Philippines, as Amended."},"level":"law","status":"active","docNumber":"Executive Order No. 282","issuingBody":"President of the Philippines","promulgatedDate":"1971-01-04","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00282_1971_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00282_1971_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19069-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The articles specifically listed hereunder as classified under Section 104 of Republic Act\nNumbered Nineteen Hundred Thirty-Seven shall pay the following rates of import duty:\nDescription of Articles\nRate of Duty\n8.04\ng.w., 100. kgs. P40.00 or ad val. 30%\n8.06\nApples, pears and quinces, fresh:\ng.w., 100 kgs. P40.00 or ad val. 50%"}},{"id":"PH-H19069-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"After the expiration of thirty (30) days from the issuance of this Order, all the above-described\narticles entered or withdrawn from warehouses, in the Philippines, for consumption shall be subject to the\nrates of import duty herein prescribed."}},{"id":"PH-H19069-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Any unwarranted increase in prices of local products benefited by these tariff changes may be\nsufficient ground for the revocation of such tariff changes.\nDone in the City of Manila, this 4th day of January, in the year of Our Lord, nineteen hundred and\nseventy-one.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n\n(SGD.) ALEJANDRO MELCHOR\nExecutive Secretary"}}],"pack":"ph-p158"};
