  FT["PH-H19662"] = {"id":"PH-H19662","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating a Cabinet Committee to Study and Recommend Solutions tothe Chinese Problem","orig":"Creating a Cabinet Committee to Study and Recommend Solutions tothe Chinese Problem"},"level":"law","status":"active","docNumber":"Executive Order No. 374","issuingBody":"President of the Philippines","promulgatedDate":"1972-02-11","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00374_1972_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00374_1972_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19662-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 374 February 11, 1972\nCREATING A CABINET COMMITTEE TO STUDY AND RECOMMEND SOLUTIONS TO THE\nCHINESE PROBLEM\nBy virtue of the powers vested in me by law, I, FERDINAND E. MARCOS, President of the Philippines, do\nhereby create a cabinet committee to study and recommend solutions to the local Chinese problem as it affects\nnational security and protection of our sovereignty, composed of the following:\nSecretary of Foreign Affairs\nSecretary of Education\nSecretary of Finance\nChairman, National Economic Council\nGovernor, Central Bank of the Philippines\nChairman, Board of Investments\nSecretary of National Defense\nDone in the City of Manila, this 11th day of February, in the year of Our Lord, nineteen hundred and\nseventy-two."}}],"pack":"ph-p158"};
