  FT["PH-H19755"] = {"id":"PH-H19755","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES PROMULGATING THE SIXTH REGULAR FOREIGN INVESTMENT NEGATIVE LIST","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES PROMULGATING THE SIXTH REGULAR FOREIGN INVESTMENT NEGATIVE LIST"},"level":"law","status":"active","docNumber":"Executive Order No. 389","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00389_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00389_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19755-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Only the investment areas or activities listed in Annex A\nhereof shall be reserved to Philippine nationals, and hereafter shall be referred to\nas the Sixth Regular Foreign Investment Negative List. The extent of foreign\nequity participation in these areas shall be limited to the percentages indicated in"}},{"id":"PH-H19755-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Any amendment to List A may be made at any time to\nreflect changes instituted in specific laws while amendments to List B shall not be\nmade more oftem than once everv two vears, oursuant to Section 8 of RA 7042\nas amended, and its revised Implementing Rules and Regulations."}},{"id":"PH-H19755-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"All orders, issuances, rules and regulations or parts thereof,\nwhich are inconsistent with this Order are hereby revoked or modified\naccordingly.\nPOMPAniesian • 28617"}},{"id":"PH-H19755-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"This Executive Order shall take effect 15 days after\npublication in a newspaper of general circulation.\nDONE in the City of Manila, this 30th day of November, in the year of\nOur Lord, Two Thousand and Four.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nerie Halesam • 28618"}}],"pack":"ph-p158"};
  FT["PH-H19756"] = {"id":"PH-H19756","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES PRESCRIBING THE ORDER OF PRESIDENTIAL SUCCESSION AND ABOLlsHING THE DEI>ARTMEr`IT oF THE INTERloR","orig":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES PRESCRIBING THE ORDER OF PRESIDENTIAL SUCCESSION AND ABOLlsHING THE DEI>ARTMEr`IT oF THE INTERloR"},"level":"law","status":"active","docNumber":"Executive Order No. 390","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00390_1941.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00390_1941.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19756-A1","no":1,"noLabel":{},"text":{"en":"MESSAGES   0F  THE  PRESIDENT\nQUEZON I  VoJwme 4\nDone  at  the  City  of  Manila,  this  22nd  day  of  December,  in  the  year  of  our  Lord,  nineteen\nhundred and forty-one, and of the Commonwealth of the Philippines, the seventh.\n(SGD.) MANUEL L. QUEZON\nBy the President:\n(SGD.) ]ORGE 8. VARGAS\nSecretary to the President\nSo4roe.' Presidential  Museum and  Library\nOffice  of the  President  of the  I'hilippines.  (1941).  /Excc#fj.t;e  Order Nos...  33J  -400/.  Manila:\nPresidential Museum and Library."}}],"pack":"ph-p158"};
  FT["PH-H19757"] = {"id":"PH-H19757","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDING EXECUTIVE ORDERS NUMBERED THREE HUNDRED FIFTY-THREE, THREE HUN- DRED FORTY-TWO, THREE HUNDRED FIFTY- NINE, AND THREE HUNDRED SIXTY-THREE, AND FOR OTHER PURPOSES.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDING EXECUTIVE ORDERS NUMBERED THREE HUNDRED FIFTY-THREE, THREE HUN- DRED FORTY-TWO, THREE HUNDRED FIFTY- NINE, AND THREE HUNDRED SIXTY-THREE, AND FOR OTHER PURPOSES."},"level":"law","status":"active","docNumber":"Executive Order No. 390","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00390_1950.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00390_1950.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19757-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Section 1 of Executive Order No. 342 dated\nAugust 14, 1950, fixing the ceiling prices of commodities\nfor the different provinces of the Philippines is hereby\namended by excluding drugs, medicines, and household\nremedies from the operation thereof. In fixing the pro-\nvincial ceiling prices of drugs, medicines, and household\nremedies, the following increases to their basic ceiling\nprices in Manila shall be allowed:\nZone I, 2 per cent; Zone II, 3 per cent; Zone III, 4 per cent;\nZone IV, 4.5 per cent; and Zone V, 5 per cent: Provided, however,\nThat in cases of. Kotex, Kleenex, Modess, and Nursing Bottles, in\nthe Visayan provinces, 3 per cent shall be added and in the Min-\ndanao provinces, 5 per cent shall be added.\nSEc. 4. Section 1 of Executive Order No. 359 dated\nNovember 3, 1950, is hereby amended by eliminating the\nproducers' ceiling prices."}},{"id":"PH-H19757-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Section 1 of Executive Order No. 363 dated\nNovember 9, 1950, is hereby amended by eliminating the\nword \"refined\" in the last sentence so as to read as follows:\n\"Sugar packed in cellophane or cotton\n.....…... P0.05 additional per kilo.\""}},{"id":"PH-H19757-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"This Order shall take effect five days from the\ndate hereof.\nDone in the City of Manila, this 27th day of December,\nin the year of Our Lord, nineteen hundred and fifty, and\nof the Independence of the Philippines, the fifth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19758"] = {"id":"PH-H19758","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1960/eo_390_1960.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Fixing Office Hours During the Hot Season","orig":"Fixing Office Hours During the Hot Season"},"level":"law","status":"active","docNumber":"Executive Order No. 390","issuingBody":"President of the Philippines","promulgatedDate":"1960-03-26","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00390_1960_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00390_1960_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19758-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 390, March 26, 1960 ]\nFIXING OFFICE HOURS DURING THE HOT SEASON\nPursuant to the provisions of section 564 of the Revised Administrative Code, as amended by Republic Act\nNo. 1880, the office hours from Monday to Friday of all departments, bureaus, offices, agencies, and\ninstrumentalities of the Government, including the provincial, city, and municipal governments and all\ncorporations owned or controlled by the Government, during the period from April 1 to June 15, 1960, both\ndates inclusive, shall be from seven-thirty o’clock in the morning to twelve-thirty o’clock in the afternoon.\nThe provisions of this Order shall not apply to the offices in the City of Baguio, whether national, provincial,\nor municipal.\nThis Order shall not oblige the Head of any department, bureau, or office to reduce as herein provided the\noffice hours in his department, bureau, or office, but leaves the same to his discretion subject to the\nrequirements of the service and provided that the usual volume of work is not diminished by the reduction of\noffice hours.\nDone in the City of Manila, the 26th day of March, in the year of Our Lord, nineteen hundred and sixty, and\nof the Independence of the Philippines, the fourteenth.\n(Sgd.) CARLOS P. GARCIA\nPresident of the Philippines\nBy the President:\n(Sgd.) NATALIO P. CASTILLO\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19759"] = {"id":"PH-H19759","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Requiring the Filing of Criminal Complaints Against Government Personnel Charged Administratively, Wherethe Administrative Case Involves Dishonesty, Corruption or Moral Turpitude","orig":"Requiring the Filing of Criminal Complaints Against Government Personnel Charged Administratively, Wherethe Administrative Case Involves Dishonesty, Corruption or Moral Turpitude"},"level":"law","status":"active","docNumber":"Executive Order No. 390","issuingBody":"President of the Philippines","promulgatedDate":"1972-04-26","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00390_1972_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00390_1972_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19759-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 390 April 26, 1972\nREQUIRING THE FILING OF CRIMINAL COMPLAINTS AGAINST GOVERNMENT PERSONNEL\nCHARGED ADMINISTRATIVELY, WHERE THE ADMINISTRATIVE CASE INVOLVES\nDISHONESTY, CORRUPTION OR MORAL TURPITUDE\nWHEREAS, it has been observed that some government personnel have been charged administratively\nwithout the corresponding criminal complaints being filed against them, despite the fact that the offense\ninvolves dishonesty, corrupt or immoral acts punishable under penal laws;\nWHEREAS, such omission is not conducive to good government, as it enables dishonest or corrupt\nrespondents to avoid the penal sanction of the law in proper cases; and\nWHEREAS, sound public administration demands that the full force of the law be brought to bear upon erring\ngovernment personnel to upgrade the public service and to enhance the people's faith in the Government.\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby require that in all instances where administrative cases involving dishonesty,\ncorruption or moral turpitude are filed against government personnel, the corresponding criminal complaints\nmust be filed against such erring personnel. Department Secretaries and heads of government agencies,\nnational and local, shall see to the due enforcement or implementation of this Order.\nDone in the City of Manila, this 26th day of April, in the year of Our Lord, nineteen hundred and seventy-two."}}],"pack":"ph-p158"};
  FT["PH-H19760"] = {"id":"PH-H19760","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG EXECUfIVE ORDER NO. 390","orig":"MALACANANG EXECUfIVE ORDER NO. 390"},"level":"law","status":"active","docNumber":"Executive Order No. 390","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00390_1990.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00390_1990.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19760-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"of Executive Order No. 315, Series of 1988, is hereby\namended to read as follows:\nCom~osition. -The Committee shall be composed of\na Chairman who shall be appointed by the President and the following\nofficials or their duly authorized representatives:\nSecretary of Finance\nSecretary of Budget and Management\nSecretary of Science and Technology\nChaimian, Presidential Commission\non Good Government\nGovernor, Central Bank\nSolicitor General\n~\n,\nDirector P1.:t.: p,..i.,~ ~'~dt=dc\":\":.\"\":\n,\n\"'04\nResearch Institute\nPresident, National Power Corporation\nPresident#- Philippine\nNatioi1al OiL- .,.~-\n-~"}},{"id":"PH-H19760-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"(a) of Executive Order No. 315, Series of 1988, is\nhereby amended to read as follows:\n\"(a) Legal Division.\nto be headed by the Chairman, and\ncomposed of the Secretary of the Budget and Management,\nChairman of the Presidential Commission on Good Government, the\nSolicitor General and the President of the National Power Corporation,\nsupervisory\nresponsibility\nenforcement of all claims and/or legal options relative to the PNPP.\"\nSECfION 3. This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 4th day of January, in the year of Our Lord,\nnineteen hundred and ninety."}}],"pack":"ph-p158"};
  FT["PH-H19761"] = {"id":"PH-H19761","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG EXECUTIVE ORDER NO.","orig":"MALACANANG EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 390","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00390_1997.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00390_1997.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19761-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"This Executive Order shall take effect thirty (30) days following its complete\npublication in two (2) newspapers of general circulatio~ in the Philippines."}}],"pack":"ph-p158"};
  FT["PH-H19762"] = {"id":"PH-H19762","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES 22, 2003 BY EXTENDING THE PERIOD FOR THE SURRENDER AND LICENSING OF LOOSE FIREARMS TO SEPTEMBER 30, 2005, AND THE UTILIZATION OF FUNDS FROM THE PROCEEDS THEREOF","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES 22, 2003 BY EXTENDING THE PERIOD FOR THE SURRENDER AND LICENSING OF LOOSE FIREARMS TO SEPTEMBER 30, 2005, AND THE UTILIZATION OF FUNDS FROM THE PROCEEDS THEREOF"},"level":"law","status":"active","docNumber":"Executive Order No. 390","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00390_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00390_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19762-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The period for the registration and licensing of all loose firearms\nprovided for in Executive Order No. 171 is hereby extended to one (1) year, up to\nSeptember 30, 2005, and to utilize the funds from the proceeds thereof in accordance\nwith the provisions of Executive Order No. 171\nAll orders, issuances, rules and regulations or part thereof\ninconsistent with this Executive Order are hereby repealed or modified accordingly.\nThis order shall take effect immediately.\nDONE in the City of Manila this 13th day of December in the year of Our\nLord, Two Thousand and Four.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\n12\nPOMA Hologram 28837"}}],"pack":"ph-p158"};
  FT["PH-H19763"] = {"id":"PH-H19763","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1960/eo_391_1960.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Opening the Port of Mangagoy, Bislig, Surigao, as a Subport of","orig":"Opening the Port of Mangagoy, Bislig, Surigao, as a Subport of"},"level":"law","status":"active","docNumber":"Executive Order No. 391","issuingBody":"President of the Philippines","promulgatedDate":"1960-04-05","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00391_1960_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00391_1960_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19763-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 391, April 05, 1960 ]\nOPENING THE PORT OF MANGAGOY, BISLIG, SURIGAO, AS A SUBPORT OF ENTRY\nIn order to stimulate commerce and trade in Surigao and nearby areas which will redound to the economic\nbenefit of the inhabitants thereof and the country at large, I, CARLOS P. GARCIA, President of the\nPhilippines, by virtue of the powers vested in me by section 702 of Republic Act No. 1937, otherwise known\nas the Tariff and Customs Code of the Philippines, and upon the recommendation of the Secretary of Finance,\ndo hereby order:\n1. The port of Mangagoy in the province of Surigao is hereby established and opened as a subport of entry\nopen to both foreign and coastwise trade under the administrative jurisdiction of the Collector of Customs of\nTacloban, the principal port of entry.\n2. The Collector of Customs of Tacloban, with the approval of the Commissioner of Customs, shall assign the\nnecessary personnel for the proper conduct of the public business at said subport and, with the further\napproval of the Secretary of Finance, shall prescribe such rules and regulations as may be necessary for the\noperation thereof.\n3. The Commissioner of Immigration and the Director of Quarantine shall assign personnel from their offices\nto take charge of immigration and quarantine matters, respectively, at the subport."}}],"pack":"ph-p158"};
  FT["PH-H19764"] = {"id":"PH-H19764","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Appointing a Member ofthe Minority Party as Member in Committees on Pre-Qualifications and Awards in Each National Agency Undertaking Infrastructure Projects","orig":"Appointing a Member ofthe Minority Party as Member in Committees on Pre-Qualifications and Awards in Each National Agency Undertaking Infrastructure Projects"},"level":"law","status":"active","docNumber":"Executive Order No. 391","issuingBody":"President of the Philippines","promulgatedDate":"1972-05-02","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00391_1972_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00391_1972_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19764-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 391 May 2, 1972\nAPPOINTING A MEMBER OF THE MINORITY PARTY AS MEMBER IN COMMITTEES ON\nPRE-QUALIFICATIONS AND AWARDS IN EACH NATIONAL AGENCY UNDERTAKING\nINFRASTRUCTURE PROJECTS\nIn the interest of public service a Bi-Partisan Study and Evaluation of all proposed Awards of Contracts for\nInfrastructure Projects of the administration is imperative. For this purpose a representative of the minority\nparty should be made a member in all Committees on Pre-qualifications and Awards for Infrastructure\nProjects in the different Bureaus and Offices of the Department of Public Works and Communications and\nother national agencies undertaking Infrastructure Projects.\nIn view of the foregoing, I, FERDINAND E. MARCOS, President of the Republic of the Philippines, by\nvirtue of the powers vested in me by law hereby appoint one member of the minority party, who possesses the\nnecessary technical qualifications, to be recommended by the President of the said Party, as member of\nstanding Committees on Pre-qualifications and Awards in each of the different Bureaus and Offices under the\nDepartment of Public Works and Communications and in other national agencies undertaking Infrastructure\nProjects, with the same powers as regular members.\nIn this connection, the representative of the minority party, who are appointed as members of the\nabove-mentioned Committees Pre-qualifications and Awards, shall be entitled to per diem of One Hundred\nPesos (P100.00) per meeting, to be borne by the Agency concerned subject to auditing and accounting\nregulations.\nDone in the City of Manila, this 2nd day of May, in the year of Our Lord, nineteen hundred and seventy-two."}}],"pack":"ph-p158"};
  FT["PH-H19765"] = {"id":"PH-H19765","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANA-NG ESTABLISHING-THE PRESIDENTIAL COORDINATING SYSTEM FOR THE EXECUfIVE DEPARTMENT","orig":"MALACANA-NG ESTABLISHING-THE PRESIDENTIAL COORDINATING SYSTEM FOR THE EXECUfIVE DEPARTMENT"},"level":"law","status":"active","docNumber":"Executive Order No. 391","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00391_1990.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00391_1990.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19765-A1","no":1,"noLabel":{},"text":{"en":"of Foreign Affairs, National Defense, Justice, Local Government, and other\noffices involved in peace and order, law enforcement, national security, good\ngovernment, public ethics and accountability as well as for maintaining close\n2\nliaison with the Constitutional Commissions and offices and the Judicial and\nLegislative Departments.\nThe Presidential Coordinating Secretary for\nAgro-Industrial,\nEconomic and Financial\nshall be responsible\nfor monitoring,\ncoordinating and facilitating the operations and activities of the Departments\nof Budget and Management,\nFinance, Agriculture,\nEnvironment and Natural Resources, Tourism, Trade and Industry, Science\nand Technology,\nand Highways,\nTransportation\nCommunications, the NEDA Secretariat, and their attached agencies as well\nas maintaining close liaison with ~e Central Bank of the Philippines and the\nMonetary Board.\n.\nThe Presidential Coordinating Secretary for Human Resources\nand Public Welfare shall be responsible for monitoring, coordinating,\nfacilitating\nthe operations\nand activities of the Departments\nEducation, Culture and Sports, Labor and Employment, Social Welfare and\nDevelopment,\ntheir attached agencies and other offices involved in public\ninformation, housing, urban and rural developme,nt and public assistance.\nEacl) Presidential_Coordinating\nSecretary sha11~~aYe-\nUndersecretary as may be necessary I to be appointed by the President. The\nDeputy Presidential\nCoordinating\nSecretary shall assist the Presidential\nCoordinating Secretary in performing his functions.\nThe Presidential Management Staff shall serve as the\ncommon administTative research and technical secretariat to the Presidential\nCoordinating Secretaries.\nThe head of the Presidential Management Staff\nshall have the rank of a Cabinet Secretary.\nThe Executive Secretary shall continue\nmatters referred to the Office of the President, attend to matters intex:11al to the\nOffice of the President, including the.administration of the operati6ns of the\nOffice of the President,\nand be responsible for the offices and agencies\nattached to or under the Office of the President as defined by law. He shall\ncontinue to exercise the specific functions and powers provided for in Bookill,\nTitle ill, Chapter 9(B), Section 27 of the Administrative Code of 1987.\nThe Department Secretaries shall continue to perform\ntheir respective duties and functions as heads of the departments,\nresponsible directly to the President for their departments.\nThe Office of the President shall provide the necessary\nfunds from its appropriation\nor any applicable appropriation in the General\nAppropriations Act for the operations of the Presidential Coordinating\n.\nherein contained\nshall be interpreted\ndiminish the President's power of control of all the executive departments,\nbureaus and Qffices.\n-\nThis Executive Order sh.an take effect immediately.\nDONE in the City of Manila, this 5th day of January, in the year of Our\nLord, nineteen hundred and ninety.\n.\n.\n...,/\nBy the President:"}}],"pack":"ph-p158"};
  FT["PH-H19766"] = {"id":"PH-H19766","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANA]\\Ift;; BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO.","orig":"MALACANA]\\Ift;; BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 391","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00391_1997.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00391_1997.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19766-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Organizing\nfor the 30th ABEAN Year. There\nan Organizing\nAnniversary chaired by the Secretary of Foreign Affairs, with thefollowing\nCabinet-level\nPhilippine\nfor ASEAN and\n\nAPEC Cooperation\n(PCAAC), the Secretary of Education,\nSports, the Press Secretary and the Chairman\nof the Commission\nHigher Education. The Committee shall be assisted by the two Technical\nFunctional\nCooperation\nand the Technical\nBoard for Economic\nCooperation.\ndepartments\nand agel1cies of the government shall extend every possible\nsupport to the commemorative\nevents and activities, when requested by\nthe Organizing Committee."}},{"id":"PH-H19766-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Communication\nPlan. The PCAAC shall formulate\ncommunication\nunderstanding\nby the Filipino people of the benefits that ASEAN can\nbe given to political,\nfunctional cooperation.\n4.\nSecretariat.\nof ASEAN Affairs\nDepartment\nof Foreign Affairs\nshall serve as the secretariat\nOrganizing\nIt shall be assisted by the ASEAN units in all\ndepartments and agencies of the Government."}},{"id":"PH-H19766-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Funding.\nThe amount of fifteen million (P 15,000,000.00)\npesos ;s hereby allocated for the above-mentioned purposes, chargeable\nagainst the Contingency Fund of the Office of the President.\nimmediately.\n6. Effectivity.\nDONE in the City of Manila,\nday of January\nthe year of Our Lord, Nineteen Hundred and Ninety-~\nBy the President:\nPf,,1S LIBRARY\n~\n\"\"0,\",\n\"\n&~"}}],"pack":"ph-p158"};
  FT["PH-H19767"] = {"id":"PH-H19767","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PIMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES DIRECTING ALL GOVERNMENT AGENCIES AND INSTRUMENTALITIES, INCLUDING LOCAL GOVERNMENT UNITS, TO IMPLEMENT THE MEDIUM-TERM PHILIPPINE DEVELOPMENT PLAN (MTPDP), 2004-2010 AND THE MEDIUM-TERM PUBLIC INVESTMENT PROGRAM (MTPIP), 2005-2010","orig":"MALACAÑANG PIMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES DIRECTING ALL GOVERNMENT AGENCIES AND INSTRUMENTALITIES, INCLUDING LOCAL GOVERNMENT UNITS, TO IMPLEMENT THE MEDIUM-TERM PHILIPPINE DEVELOPMENT PLAN (MTPDP), 2004-2010 AND THE MEDIUM-TERM PUBLIC INVESTMENT PROGRAM (MTPIP), 2005-2010"},"level":"law","status":"active","docNumber":"Executive Order No. 391","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00391_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00391_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19767-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Coverage.\nAll GAs, including state universities and\ncolleges (SUCs), GOCCs, GFIs, and OGCEs and their subsidiaries, the local\ngovernment units (LGUs), and other instrumentalities under the Executive\nDepartment, whether or not they receive funding support through the General\nAppropriations Act, are hereby ordered to adopt and disseminate the MTPDP,\n2004-2010 and undertake efforts leading to its full implementation.\nAligning Budgetary and Departmental Programs with\nthe MTPDP 2004-2010. All heads of agencies, corporations and institutions\nare hereby directed to align the budgetary and departmental/corporate programs\nwith the strategies and activities identified in the MTPDP, 2004-2010.\nThe MTPIP, 2005-2010. All heads of national agencies,\ncorporations and institutions are hereby instructed to adhere to the MTPIP\nformulation guidelines issued by the National Economic and Development\nAuthority (NEDA) on 26 July 2004 and the Programming and Budgeting\nGuidelines for 2006-2010 issued by the Department of Budget and Management\n(DBM) in its Circular Letter No. 2004-11 dated 31 August 2004.\nThe formulation of the MTPIP, 2005-2010 shall be completed by December 2004\nand updated annually in parallel with the preparations of the annual National\nGovernment budget.\nMTPDP and MTPIP Monitoring and Reporting . All\nheads of agencies, corporations and institutions are hereby directed to submit to\nthe NEDA Board through the NEDA Secretariat, the annual agency\nperformance/accomplishment reports consistent with the MTPDP and MTPIP\nformat, that is, the Strategy Planning Matrix (SPM) and the Agency Three-Year\nRolling Public Investment List (PIL). The report shall detail actual performance\nvis-à-vis the priority strategies and activities (PSAs), major final outputs (MFOs),\nas well as status of implementation of the programs, activities and projects\n(PAPs). The NEDA Secretariat shall report the key accomplishments in the\nannual Socio-Economic Report (SER).\nThe NEDA Director -General is hereby authorized, upon\nconsultation with the President, to issue such memoranda, circulars or other\n\norders as may be considered necessary or advisable in the coordination of the\nimplementation, monitoring, assessment and updating of the MTPDP and MTPIP.\nThe DBM shall provide the necessary budgetary support for\nthe implementation, monitoring, assessment and updating of the MTPDP and\nMTPIP subject to the usual accounting and auditing requirements.\nRepealing Clause. All issuances, orders, guidelines, rules\nand regulations inconsistent herewith are hereby revoked.\nEffectivity.\nThis Executive Order shall take effect\nimmediately.\nDONE in the City of Manila, this 13tiday of December in the year of Our\nLord, Two Thousand and Four.\nBy the President:\n*\nEDUARDO R. ERMITA\nExecutive Secretary\nIMA Halogran , 28832"}}],"pack":"ph-p158"};
  FT["PH-H19768"] = {"id":"PH-H19768","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":34,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES FURTHER REORGANIZING THE DIFFERENT DE- PARTMENTS, BUREAUS, OFFICES AND AGEN- CIES OF THE GOVERNMENT OF THE REPUBLIC OF THE PHILIPINES, MAKING CERTAIN RE- ADJUSTMENTS OF PERSONNEL AND REALLOT- MENTS OF FUNDS IN CONNECTION THERE- WITH, AND FOR OTHER PURPOSES.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES FURTHER REORGANIZING THE DIFFERENT DE- PARTMENTS, BUREAUS, OFFICES AND AGEN- CIES OF THE GOVERNMENT OF THE REPUBLIC OF THE PHILIPINES, MAKING CERTAIN RE- ADJUSTMENTS OF PERSONNEL AND REALLOT- MENTS OF FUNDS IN CONNECTION THERE- WITH, AND FOR OTHER PURPOSES."},"level":"law","status":"active","docNumber":"Executive Order No. 392","issuingBody":"President of the Philippines","completenessNote":"全文，共 34 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00392_1950.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00392_1950.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19768-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Section seventy-six of the Revised Administra-\ntive Code, as amended, is hereby further amended to read\n\"SEc. 76. Secretaries of Departments.-The Department of Foreign\nAffairs shall perform its functions under the executive authority of\nthe Secretary of Foreign Affairs; the Department of Finance shall\nperform its functions under the executive authority of the Secretary\nof Finance; the Department of Justice shall perform its functions\nunder the executive authority of the Secretary of Justice; the Depart-\nment of Agriculture and Natural Resources shall perform its func-\ntions under the executive authority of the Secretary of Agriculture\nand Natural Resources; the Department of Public Works and Com-\nmunications shall perform its functions under the executive authority\nof the Secretary of Public Works and Communications; the Depart-\nment of Education shall perform its functions under the executive\n\nOFFICIAL GAZETTE\nauthority of the Secretary of Education; the Department of Labor\nshall perform its functions under the executive authority of the\nSecretary of Labor; the Department of National Defense shall per-\nform its functions under the executive authority of the Secretary\nof National Defense; the Department of Health shall perform its\nfunctions under the executive authority of the Secretary of Health;\nthe Department of Commerce and Industry shall perform its func-\ntions under the executive authority of the Secretary of Commerce\nand Industry.\""}},{"id":"PH-H19768-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Effective July first, nineteen hundred and fifty-\none, the scale of the minimum and maximum rates of\ncompensation of government officers or employees possess-\ning different civil service eligibilities shall be as follows:\n(a) First grade eligibles\n(6) Second grade eligibles\n1.440\n(c) Third grade eligibles\n1,140\n1,800\n(d) Senior stenographers\n(e) Junior stenographers\n1,440\n2,760\n(f) Senior typists\n1,560\n2,940\n(g) Junior typists\n1,320\n2,400\nPHILIPPINE INFORMATION COUNCIL"}},{"id":"PH-H19768-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Radio Broadcasting Board is hereby abol-\nished, and all the personnel, powers, duties, functions,\nactivities, equipment, materials, properties, records and\nthe unexpended balances of funds or appropriations per-\ntaining to said Board are transferred to the Philippine\nInformation Council created under Executive Order Num-\nbered Three hundred and forty-eight, dated September\ntwenty-ninth, nineteen hundred and fifty, as amended.\nBUREAUS AND OFFICES UNDER THE EXECUTIVE OFFICE\nSEc. 6. Section twenty-eight of Executive Order Num-\nbered Ninety-four, dated October four, nineteen hundred\nand forty-seven, is hereby amended to read as follows:\n\"Sec. 28. The Executive Secretary shall have immediate super-\nvision ard contwyl over the Bureau of Printing, the Fire Prevention\nBoard and th lames and Amusements Board.\""}},{"id":"PH-H19768-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"There is hereby created under the executive\nsupervision of the Executive Secretary an office to be\nknown as the Games and Amusements Board to be com-\nposed of three members appointed by the President with\nthe consent of the Commission on Appointments. The\npowers, duties and functions of the Racing Commission,\nthe Boxing and Wrestling Commission and the Jai-Alai are.\nhereby consolidated and transferred to, and shall be as-\nsumed and exercised by, the Games and Amusements\nBoard. One member of the Board shall administer and\nsupervise all activities on horse racing, the other member\nshall administer and supervise all activities on boxing and\nwrestling, and the third member shall administer and super-\nvise the Jai-Alai.\n5915\n\n5916\n•\nOFFICIAL GAZETTE\nDEPARTMENT OF FOREIGN AFFAIRS\nSEc. 8. Bureaus and offices under the Department of\nForeign Affairs. _The Department of Foreign Affairs shall\nhave executive supervision over the Board cf Foreign\nAffairs Service Personnel, Examination and Review; the\nOffice of Political and Economic Affairs; the Office of Ad-\nministration, Controls and Foreign Service Affairs; the\nOffice of International Social and Cultural Affairs; and\nover the Embassies, Legations, Consulates and other offices\nor wits composing the Foreign Service of tha Republic\nof the Philippines."}},{"id":"PH-H19768-A9","no":9,"noLabel":{"en":"SEC 9"},"text":{"en":"Abolition of National Commission on Education-\nal, Scientific and Cultural Matters.-The National Com-\nmission on Educational, Scientific and Cultural Matters is\nhereby abolished, and all its powers, duties and functions,\nand its records, property, equipment and personnel, except\nthe Chairman, the members and the executive secretary,\nare transferred to the Department of Foreign Affairs.\nDEPARTMENT OF FINANCE"}},{"id":"PH-H19768-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Section eighty-one of the Revised Administra-\ntive Code, as amended, is hereby further amended to read\n\"Sec. 81. Bureaus and offices under the Department of Finance.-\nThe Department of Finance shall have executive supervision over the\nBureau of Customs, the Bureau of Internal Revenue, the Bureau of\nthe Treasury, the Office of the Insurance Commissioner, the Bureau\nof Supply and the Tobacco Board. It shall also have general super-\nvision over the financial affairs and financial agencies of provincial,\nmunicipal and city governments, and, except as otherwise specially\nprovided, over all funds the investment of which may be authorized"}},{"id":"PH-H19768-A11","no":11,"noLabel":{"en":"Sec 11"},"text":{"en":"The position of Collector of Customs for the\nPort of Manila is hereby converted into Deputy Commis-\nsioner of Customs with the rank and duties of an assistant\nchief of a bureau or office. He shall be ap: vinted by the\nPresident of the Philippines with the consen of the Com-\nmission on Appointments and shall receive a cmpensation\nof seven thousand two hundred pesos per annum. The\nDeputy Commissioner of Customs shall perform the duties\nand functions of the Commissioner of Customs during the\nabsence or disability of the latter. In addition to his\nregular duties he shall be exofficio Collector of Customs\nfor the Port of Manila. The Port of Manila is hereby\nplaced for administrative purposes under the immediate\nsupervision of the Collector of Customs for the Port of"}},{"id":"PH-H19768-A12","no":12,"noLabel":{"en":"Sec 12"},"text":{"en":"The Procurement Office is hereby changed to\nand shall hereafter be known as the Bureau of Supply.\n\nOFFICIAL GAZETTE\nPHILIPPINE PURCHASING AGENCY IN NEW YORK"}},{"id":"PH-H19768-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"The Philippine Purchasing Agency in New York\nas provided in item F-IV-9, Republic Act Numbered Five\nhundred and sixty-three, is hereby abolished, and the Sec-\nretary of Finance is authorized to effect, subject to the\napproval of the President, the proper disposition of the\nfurniture, supplies, equipment, property, books and records,\nincluding the unexpended balance of the Philippine Pur-\nchasing Agency Revolving Fund, established by Executive\nOr Jer Numbered Eighty-one, series of nineteen hundred\nand forty-five.\n5917\nDEPARTMENT OF JUSTICE\nSEc. 14. The first paragraph of section eighty-three of\nthe Revised Administrative Code, as amended, is hereby\nfurther amended to read as follows:\n\"SEC. 83. Bureaus and offices under the Department of Justice.~\nThe Department of Justice shall have executive supervision over the\nOffice of the Solicitor General, the Courts of First Instance and the\nInferior Courts, the Public Service Commission, the Bureau of\nPrisons, the General Land Registration Office, the Court of Industrial\nRelations, the National Bureau of Investigation, the Bureau of\nImmigration, the Board of Pardons and Parole, the Deporation\nBoard, the Code Commission, and the Office of the Government Cor-\nporate Counsel. It shall also have general supervision and control\nof the provincial sheriffs and all law officers of the Government, the\nprovincial and city fiscals or attorneys and other prosecuting officers.\""}},{"id":"PH-H19768-A15","no":15,"noLabel":{"en":"SEC 15"},"text":{"en":"The legal Aid Office created under Republic Act\nNumbered Eighty, and the Office of Peple's Counsel\ncreated under the provisions of Section Thirty-eight of\nCommonwealth Act Numbered One hundred and. forty-\nsix, as amended, are hereby abolished."}},{"id":"PH-H19768-A16","no":16,"noLabel":{"en":"Sec 16"},"text":{"en":"The Office of Special Attorneys created under\nRepublic Act Numbered Three hundred and eleven, is\nhereby abolished and its powers, functions, and duties shall\nbe assumed by the provincial and city fiscals."}},{"id":"PH-H19768-A17","no":17,"noLabel":{"en":"Sec 17"},"text":{"en":"The Tenancy Law Enforcement Division created\nunder Commonwealth Act Numbered Four hundred and\nthirteen, is hereby abolished and its personnel, powers,\nduties and functions, records, property and equipment shall\nbe transferred to the Court of Industrial Relations.\nDEPARTMENT OF AGRICULTURE AND NATURAL RESOURCES"}},{"id":"PH-H19768-A18","no":18,"noLabel":{"en":"Sec 18"},"text":{"en":"Section eighty-four of the Revised Administra-\ntive Code, as amended, is hereby further amended to read\n\"SEc. 84. Bureaus and offices under the Department of Agriculture\nand Natural Resources.-The Department of Agriculture and Nat-\nural Resources shall have executive supervision over the Bureau of\nPlant Industry, the Bureau of Animal Industry, the Bureau of\nForestry, the Bureau of Lands, the Bureau of Mines, the Bureau of\n\n5918\nOFFICIAL GAZETTE\nFisheries, the Fiber Inspection Service, matters pertaining to colonies\nand plantations of public lands, and matters concerning hunting.\nfisheries, sponges, and other sea-products, including the issuance of\nlicenses therefor.\"\nDEPARTMENT OF PUBLIC WORKS AND COMMUNICATIONS\nSEc. 19. Section eighty-five of the Revised Administra-\ntive Code, as amended, is hereby further amended to read\n\"SEc. 85. Bureaus and offices under the Department of Public\nWorks and Communications. -The Department of Public Works and\nCommunications shall have executive supervision over the Bureau of\nPublic Works, the Bureau of Posts, the Bureau of Telecommunica-\ntions, the Motor Vehicles Office, he Irrigation Couneil, the Flood\nControl Commission, the National Transportation Board, the Radio\nControl Board and the Government Quarters Committee.\"\nTRANSFER OF RADIO CONTROL BOARD AND RADIO\nCONTROL DIVISION"}},{"id":"PH-H19768-A20","no":20,"noLabel":{"en":"Sec 20"},"text":{"en":"The Radio Control Board under the Department\nof Commerce and Industry, together with its personnel,\npowers, duties, functions, activities, records, equipment,\nproperties and unexpended balances of funds or appropria-\ntions, is hereby transferred to the Department of Public\nWorks and Communications."}},{"id":"PH-H19768-A21","no":21,"noLabel":{"en":"Sec 21"},"text":{"en":"The Radio Control Division under the Depart-\nment of Commerce and Industry, together with its per-\nsonnel, powers, duties, functions, activities, records, equip-\nment and properties, are hereby transferred to the Radio\nControl Board.\nREORGANIZATION OF RADIO CONTROL BOARD"}},{"id":"PH-H19768-A22","no":22,"noLabel":{"en":"Sec 22"},"text":{"en":"The Radio Control Board is hereby reorganized\nto be composed of the Undersecretary of Public Works\nand Communications, as Chairman, the Director of In-\nformation, the Collector of Internal Revenue, the Director\nof Public Schools and the Director of Posts, as members.\nThe President may appoint additional members if the needs\nof the service require. The Chief of the Radio Control\nDivision of the Bureau of Telecommunications shall be the\nSecretary of the Radio Control Board.\nDEPARTMENT OF EDUCATION"}},{"id":"PH-H19768-A23","no":23,"noLabel":{"en":"Sec 23"},"text":{"en":"Section eighty-two of the Revised Administra-\ntive Code, as amended, is hereby further amended to read\n\"Sec. 82. Bureaus and offices under the Department of Education.-\nThe Department of Education shall have exclusive supervision\nover the Bureau of Public Schools, the Bureau of Private Schools,\nthe Burezu of Public Libraries and Museum, the Board on Textbooks,\nthe Institute of National Language and the Philippines Historical\n99\n\nOFFICIAL GAZETTE\nSEc. 24. The National Museum under the Executive Of-\nfice is hereby abolished and all its powers, duties, functions,\nrecords, properties, equipment and personnel, except the\nDirector, are hereby transferred to the Bureau of Public\nLibraries which shall hereafter be known as the Bureau of\nPublic Libraries and Museum.\nSEc. 25. The Committee on School Health for Medical\nand Dental Services, now functioning under the Office of\nthe President, is hereby transferred, together with its\npersonnel, powers, duties, functions, activities, equipment,\nmaterials and records, to the executive supervision of the\nDepartment of Health.\nThe Secretary of Health shall be the Chairman of the\nCommittee on School Health for Medical and Dental Serv-\nThe Medical and Dental Services being administered by\nthe aforesaid committee shall be transferred from the\nBureau of Public Schools to the Bureau of Health.\nA Division of Home Economies is hereby created in the\nBureau of Public Schools.\nSEc. 26. The present Central Luzon Agricultural School\nlocated in Muñoz, Nueva Ecija, is hereby changed to Cen-\ntral Luzon Agricultural College which shall offer, in addi-\ntion to its present four-year secondary agricultural course,\none-year farm mechanics course and its special courses,\nalso a two-year, a four-year, and a post-graduate course\nleading to the title of Associate in Agricultural Education\nand the degree of Bachelor of Science in Agricultural\nEducation, and Master of Science in Agricultural Educa-\ntion, respectively.\nTRANSFER OF PHILIPPINE NAUTICAL SCHOOL"}},{"id":"PH-H19768-A27","no":27,"noLabel":{"en":"SEC 27"},"text":{"en":". The Philippine Nautical School, at present under\nthe Philippine Naval Patrol, is hereby transferred, together\nwith its personnel, powers, duties, functions, activities,\nproperties, equipment, materials and records, to the control\nand supervision of the Bureau of Public Schools.\nCOPYRIGHT FUNCTIONS RESTORED TO BUREAU OF PUBLIC\nLIBRARIES AND MUSEUM\nSEc. 28. The powers, duties and functions concerning the\nadministration of the Copyright Law, vested in the Patent\nOffice pursuant to the provisions of Republic Act Numbered\nOne hundred and sixty-seven, are hereby transferred, to-\ngether with the records, equipment and personnel con-\ncerned therewith, to the Bureau of Public Libraries and\nDEPARTMENT OF LABOR\nSEc. 29. Section four of Act Numbered Four thousand\none hundred and twenty-seven, as amended, is hereby\nfurther amended to read as follows:\n5919\n\n5920\nOFFICIAL GAZETTE\n\"Sec. 4. Bureaus and offices under the Department of Labor.-The\nDepartment of Labor shall have executive supervision over the\nBureau of Labor, the Labor-Management Advisory Board, the Place-\nment Bureau, and all bureaus, divisions and offices hereafter created\nconcerning labor alone and labor in its relation with capital, and\nalso the proper enforcement of all laws relative to labor and capital\nin the Philippines and over all other matters related to the welfare\nof the Filipino laborers in this country and abroad.\n\"The Secretary of Labor shall be the Chairman of he Labor-\nManagement Advisory Board.\"\nPLACEMENT BUREAU"}},{"id":"PH-H19768-A30","no":30,"noLabel":{"en":"Sec 30"},"text":{"en":"There is hereby created an office to be known\nas the Placement Bureau under the executive supervision\nuf the Department of Labor. It shall have a chief to be\nknown as Director of Repiacement whose compensation\nshall be seven thousand two hundred pesos per annum."}},{"id":"PH-H19768-A31","no":31,"noLabel":{"en":"Sec 31"},"text":{"en":"The Placement Bureau shall assist applicants\nfor employment in the civil service of the Government with\na view to placing them in suitable positions for which\nthey are duly qualified, taking into consiceration civil\nservice rules and regulations. Tt shall, from time to time,\ngather and compile statistical data relative to the vacancies\noccurring in the different executive departments, bureaus,\noffices, agencies, and other instrumentalities of the Gov-\nernment including the corporations owned or controlled"}},{"id":"PH-H19768-A32","no":32,"noLabel":{"en":"Sec 32"},"text":{"en":"To facilitate the employment of applicants for.\npositions in the civil service, the Director of Placement\nshall, in consultation with the Commissioner of Civil Serv-\nice, prepare a list of eligibles qualified for appointment\nto the various vacancies in the civil service. The list shall\nbe arranged according to priority of choice and only those\nwhose names are submitted by the Director of Placement\nshall be considered for appointment in the office where\nthe vacancy exists. No appointment shall be approved by\nthe Bureau of Civil Service.\nSEc. 33. The Placement Bureau shall also assist in the\nemplovment of private persons in private establishments\nand to this end it shall:\n(a) Keep a register of bona fide applicants or private em-\nployment and provide free placement service for labor of all\n(b) Collect and analvze in cooperation with the Director of\nthe Bureau of Census and Statistics the fullest available infor-\nmation on the employment situation.\n(c) Encourage and assist private organizations in social and\neconomic planning calculated to insure a favorable employment\n(d) Cooperate in the administration of such employment\ninsurance or assistance schemes and other measures as may be\nestablished for the relief of the unemployed.\n(e) Administer Act No. 2486 entitled \"An Act fixing a tax\nupon every person or entity engaged in recruiting or contracting\n\nOFFICIAL GAZETTE\nlaborers in the Philippines, and amending sub-section (a) of\nsection fifty-three of Act Numbered Twenty hundred and thirty-"}},{"id":"PH-H19768-A34","no":34,"noLabel":{"en":"Sec 34"},"text":{"en":"The Secretary of Labor, with the approval of\nthe President, shall promulgate the necessary rules and\nregulations to carry into effect the aims and purposes of\nthe Placement Bureau.\nSEc. 35 The Labor Placement Division of the Bureau of\nLabor is hereby abolished and all its personnel, activities\nand functions, records, properties ard equipment are here-\nby transferred to the Placement Bureau.\nABOLITION OF THE BUREAU OF INDUSTRIAL SAFETY"}},{"id":"PH-H19768-A36","no":36,"noLabel":{"en":"Sec 36"},"text":{"en":"Republic Act Numbered Three hundred sixty-\nseven creating the Bureau of Industrial Safety, is hereby\nrepealed, and Commonwealth Act Numbered One hundred\nfour, as amerded by Commonwealth Act Numbered six\nhundred ninety-six, is hereby revived. The provisions of\nthe two aforesaid Commonwealth Acts shall be limited in\ntheir application to industrial enterprises, and an Indus-\ntrial Safety Engineering Division shall be establisher\nunder the Bureau of Labor in order to carry out the provi-\nsions of the said Acts.\nThe powers, duties and functions conferred upon the\nSecrtary of Labor by the provisions of the two aforecited\nCommonwealth Acts concerning safety standards and the\nsafety of the laborers and employees in mines, quarries, or\nmetallurgical operations, are hereby transferred to, and\nshall hereafter be assumed and exercised by, the Director\nDEPARTMENT OF NATIONAL DEFENSE"}},{"id":"PH-H19768-A37","no":37,"noLabel":{"en":"Sec 37"},"text":{"en":"Section two of Commonwealth Act Numbered\nFour hundred thirty, as amended, is hereby further\namended to read as follows:\n\"SEc. 2. Bureaus and offices under the Department of National\nDefense. The Department of National Defense shall be charged.\nwith the duty of supervising the national defense program of the\ncountry, and for this purpose, it shall have executive supervision\nover the Armed Forces of the Philippines, the Philippine Veterans\nBoard, the Bureau of Coast and Geodetic Survey and the Munitions\nBoard. This Department shall function under the executive control\nof the Secretary of National Defense who may be assisted by an\nUndersecretary.\""}},{"id":"PH-H19768-A38","no":38,"noLabel":{"en":"Sec 38"},"text":{"en":"The Board on Pensions for Veterans is hereby\nabolished 'and its powers, duties, functions, properties,\nequipment and personnel, except the Chairman and the\nmembers, are hereby transferred to the Philippine Veterans\nBoard created under Republic Act Numbered sixty-five, as\namended, under the executive supervision of the Depart-\nment of National Defense.\n17394-§\n5921\n\n5922\nOFFICIAL GAZETTE\nThe Philippine Veterans Board shall be composed of a\nchairman and six members, two of whom shall be veterans\nof past Philippine revolutions or wars.\nDEPARTMENT OF HEALTH\nSEc. 39. The second paragraph of Executive Order\nNumbered Three hundred and seventeen, dated January\nseventh, nineteen hundred and forty-one, as amended, is\nhereby further amended to read as follows:\nThe Department of Health shall be charged with the protection\nof the health of the people, the maintenance of sanitary conditions,\nand the proper enforcement of the laws and regulations relative to\nhealth, sanitation, foods, drugs and narcotics, slum housing: garbage\nand other waste disposal, and for these purposes it shall exercise\nexecutive supervision over the Bureau of Health; the Bureau of\nQuarantine; the Bureau of Hospitals; the National Advisory Health\nCouncil; the Alabang Vaccine and Serum Laboratories; the Institute\nof Nutrition; the Committee on School Health for Medical and\nDental Services; the health department of chartered cities; and\nnational, provincial, city and municipal hospitals, dispensaries and\nclinics, except the Philippine General Hospital; the public markets\nand slaughterhouses; hotels, restaurants and other food establish-\nments; and health resorts and similar establishments.\"\nTRANSFER OF INSTITUTE OF NUTRITION"}},{"id":"PH-H19768-A40","no":40,"noLabel":{"en":"SEC 40"},"text":{"en":"The Institute of Nutrition, under the Executive\nOffice, together with its personnel, records, equipment,\nproperties, powers, duties, functions and activities, are\nhereby transferred to the Department of Health.\nThe Division of Biological Research and the Division of\nFood Technology of the Institute of Science, together with\ntheir activities and functions, personnel, equipment, rec-\nords and properties, shall be transferred to the Institute\nof Nutrition. The remaining divisions or units of the\nInstitute of Science are hereby organized and constituted\ninto the Institute of Applied Science and Technology which\nis hereby placed under the executive supervision of the\nAdministrator of Economic Coordination. The Board of\nRegents of the Institute of Science shall hereafter be known\nas the Advisory Board thereof.\nDIVISION OF TUBERCULOSIS"}},{"id":"PH-H19768-A41","no":41,"noLabel":{"en":"Sec 41"},"text":{"en":"There is hereby created, under the Department\nof Health, a Division of Tuberculosis to be composed of\nthe National Chest Center and the Section of Tuberculosis\nControl which is at present under the Office of the Sec-\nretary of Health.\nDEPARTMENT OF COMMERCE AND INDUSTRY\nSEc. 42. Section one hundred and thirty-four of Exec-\nutive Order Numbered Ninety-four, dated October fourth,.\nnineteen hundred and forty-seven, is hereby amended to\nread as follows:\n\nOFFICIAL GAZETTE\n\"Sec. 134. The Department of Commerce and Industry shall have\nexecutive supervision over the Bureau of Commerce, the Cooperative\nAdministration Office, the Securities and Exchange Commission, the\nWeather Bureau, the Patent Office, the Civil Aeronauties Adminis-\ntration, the Civil Aeronautics Board, the Manila Trading Center\nand Exchange, the Sugar Quota Administration, the Fair Trade\nBoard and the Bureau of the Census and Statistics.\nSUGAR QUOTA OFFICE RENAMED"}},{"id":"PH-H19768-A43","no":43,"noLabel":{"en":"SEC 43"},"text":{"en":"The Sugar Quota Office is hereby renamed\n\"Sugar Quota Administration.\"\nTRANSFER OF THE BUREAU OF THE CENSUS AND STATISTICS"}},{"id":"PH-H19768-A44","no":44,"noLabel":{"en":"Sec 44"},"text":{"en":"The Bureau of the Census and Statistics, under\nthe Executive Office, together with its persennel, records,\nequipment, properties, powers, duties, functions and ac-\ntivities, is hereby transferred to the Department of Com-\nmerce and Industry.\nSEc. 45. Officials and einployees who are separated from\nthe service by reason of the abolition of their positions in\nthis Executive Order shall be entitled to gratuity equivalent\nto one month salary for every year of continuous satis-\nfactory service rendered but not exceeding twelve months\non the basis of the last salary received payabie from the\nsavings from the appropriations provided in Republic Acts\nNos. 426, 461, 475, 485, 563, 575 and 576 as a result of the\nreorganization effected in this order; Provided, That any\nofficial or employee who has rendered less than one vear\nbut at least six months' service shall be entitled to a\ngratuity equivalent to one-half month salary; Provided,\nfurther, That, in case an official or employee is reinstated\nin the government service or in any government owned or\ncontrolled corporation, he shall be required to refund to the\nbureau, office, branch or entity from which he received the\ngratuity that portion which he would not yet have received\nhad it been paid to him in monthly installment; Provided,\nfurther, That those entitled to a! gratuity of not more than\nthree months shall be paid their gratuity in full imme-\ndiately upon their separation from the service; those\nentitled to more than three months but not exceeding six\nmonths shall be paid upon their separation an additional\none-half month salary for every month in addition to the\nfull gratuity corresponding to the first three months; and\nthose who are entitled to a gratuity of more than six\nmonths shall be paid their gratuity in full for the next\nfollowing three months. The balance due to those entitled\nto more than three months' gratuity shall be paid upon\ncertification by the Fund Release Control Committee\ncreated under Administrative Order No. 129 dated August\n8, 1950, of the availability of the necessary cash therefor\nbut not later than December 31, 1951.\n5923\n\n5924\nOFFICIAL GAZETTE\nSEc. 46. In filling of vacancies that may occur in any\nDepartment, bureau or office, after January 1, 1951, includ-\ning those in government-owned or controlled corporations,\npreference shall be given, unless otherwise authorized by\nthe President, to those separated from the service by\nreason of the abolition of their positions in this Executive"}},{"id":"PH-H19768-A47","no":47,"noLabel":{"en":"Sec 47"},"text":{"en":"Effective July first, nineteen hundred and fifty-\none, the scale of the minimum and maximum rates of com-\npensation of government officers or employees possessing\ndifferent civil service eligibilities shall be as follows:\n•\n(a) First grade eligibles\n(b) Second grade eligioles\n(c) Third grade eligibles\n(d) Senior Stenographers\n(e) Junior Stenographers\n(f) Senior Typists\n(g) Junior Typists\n1,140\n1,140\n1,800\n1,440\n2,760\n1,560\n2,940\n1.320\n2,400\nREALLOTMENT OF FUNDS"}},{"id":"PH-H19768-A48","no":48,"noLabel":{"en":"Sec 48"},"text":{"en":"From the total authorized appropriations of\nP344,163,197 consisting of-\n1. For the expenses of the Import Control Board\nand the Import Control Administration, Republic\n2. Additional appropriation for the Armed Forces of\nthe Philippines for the campaign for the mainte-\nnance of peace and order, Republic Act No. 461\n20,000,000.00\n3. For the maintenance and operation of the Port of\nCagayan, Province of Oriental Miamis, Republic\n45,000.00\n4. Additional appropriation for the maintenance and\noperation of the Bunawan National Junior Agri-\ncultural School, Republic Act No. 485\n12,585.00\n5. General Appropriations, Republic Act No. 563 .......\n261,049,574.00\n6. Additional funds for the operation and mainte-\nnance of the Government of the Republic of\nthe Philippines, Republic Act No. 575\n45,121,648.00\n7, Additional funds for the. Armed Forces of the\nPhilippines, Republic Act No. 576\n17,184,440.00\nREPEALING CLAUSE"}},{"id":"PH-H19768-A49","no":49,"noLabel":{"en":"SEC 49"},"text":{"en":"All Acts, Executive Orders, Administrative Or-\nders, or Proclamations or parts thereof inconsistent with\nany provision of this Order are hereby repealed or modified\naccordingly.\nPARTIAL INVALIDITY"}},{"id":"PH-H19768-A50","no":50,"noLabel":{"en":"Sec 50"},"text":{"en":"If any provision of this Order should be held\ninvalid, the other provisions shall not be affected thereby.\nEFFECTIVE DATE"}},{"id":"PH-H19768-A51","no":51,"noLabel":{"en":"Sec 51"},"text":{"en":"This Order shall take effect on January first,\nnineteen hundred and fifty-one,. except where otherwise\n\nOFFICIAL GAZETTE\nDone in the City of Manila, this thirty-first day of\nDecember, in the year of Our Lord, nineteen hundred and\nfifty and of the Independence of the Philippines, the fifth.\nELPIDIO QUIRINO\nPresident of the Philippines\n5925\nBy the President:\nTEODORO EVANGELISTA,\nPropative Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19769"] = {"id":"PH-H19769","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"rJ.?3I1JENCE OF THE PEESIDENT OF THE 'PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE OnDER NG. 392 . PROVIDING INSTRUCTIONS TO DE FCLLGWED IN THE CONWOT OF PUBLIC AFFA:ms DURING THE TIME THAT THE PRESIDENT IS OUTSIDE THE PHILIPPINES~","orig":"rJ.?3I1JENCE OF THE PEESIDENT OF THE 'PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE OnDER NG. 392 . PROVIDING INSTRUCTIONS TO DE FCLLGWED IN THE CONWOT OF PUBLIC AFFA:ms DURING THE TIME THAT THE PRESIDENT IS OUTSIDE THE PHILIPPINES~"},"level":"law","status":"active","docNumber":"Executive Order No. 392","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00392_1960.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00392_1960.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19769-A1","no":1,"noLabel":{},"text":{"en":"Providod, howover, That in the abscm60 of\n.unanimity  of op5~ion on any important question submittod,\nno. decision shall bo token until it sholl have boen sub\nmitted to tho President.\n- 2\n4. All official communications to tho President,\nwhother by letter or by radio, shall betronsmittod\nthrough or by the Executive Secretary.\n\"':'1:\n5. Tho Executive Socretary shall represent the\nPresident in social functions roquiring the presence\nof tho lattor and shall preside over official ,ceremo\nnies, receivo and return the offic~al calls of foreign\ndignitaries 'in behalf and in representation of the\nPresident, and on such occasions the Executive Secre\ntllI'Y shall::. be entitled to tho honors and courtosloB\ndue tho P!osident of the Philippinos.\n-'\"\nDone i~\" tho City of Manila, this 30th of AprU,\nin tho yoar df Our Lord, nineteen hundred and/ sixty,\nand of the Independence of tho Philippines, tho fdurteenth.\n(SOO.) CJ\\T'~OS P. GfiRCIA\nPresidont of the Philippines\nBy tho Prvsident~\n(SOO.) '-NATALIO P. CASTILLO\nExecutivo Secrotary\n)\n.,\n+"}}],"pack":"ph-p158"};
  FT["PH-H19770"] = {"id":"PH-H19770","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating a National Committee to Take Charge ofthe Celebration of Philippine Independence Day on June 12, 1972","orig":"Creating a National Committee to Take Charge ofthe Celebration of Philippine Independence Day on June 12, 1972"},"level":"law","status":"active","docNumber":"Executive Order No. 392","issuingBody":"President of the Philippines","promulgatedDate":"1972-05-09","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00392_1972_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00392_1972_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19770-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 392 May 9, 1972\nCREATING A NATIONAL COMMITTEE TO TAKE CHARGE OF THE CELEBRATION OF\nPHILIPPINE INDEPENDENCE DAY ON JUNE 12, 1972\nPursuant to the powers vested in me by law, I, FERDINAND E. MARCOS, President of the Philippines, do\nhereby create a national committee to take charge of the celebration of Philippine Independence Day on June\n12, 1972.\nThe Committee shall be composed of the following:\nThe Secretary of Education\nThe Commissioner of the Budget\nVice-Chairman\nThe Press Secretary\nThe Commissioner on National Integration\nThe Undersecretary of Public Works\nThe Undersecretary of Labor\nThe Undersecretary of National Defense\nThe Undersecretary of Commerce\nThe Assistant Executive Secretary (Local Governments)\nThe Deputy Administrator of Economic Coordination\nThe Mayor of Manila\nThe Chairman, National Historical Commission\nThe President, Philippine Association of Colleges and Universities\nThe President, Veterans Federation of the Philippines\nThe President, Civic Assembly of Women of the Philippines (CAWP)\nThe President, Chamber of Commerce of the Philippines\nRepresentative from Youth Group\nThe Presidential Protocol Officer\nMember-Secretary\nThe Committee shall meet at the call of the Chairman and for the purpose of discharging its functions, may\ncreate such sub-committees as may be necessary.\nThe Committee is hereby authorized to call upon any department, bureau, office, agency or instrumentality of\nthe Government, including government-owned or controlled corporations, for such assistance as it may need\nin the discharge of its duties and functions.\nDone in the City of Manila, this 9th day of May, in the year of Our Lord, nineteen hundred and seventy-two."}}],"pack":"ph-p158"};
  FT["PH-H19771"] = {"id":"PH-H19771","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG EXECU11VE ORDER NO.","orig":"MALACANANG EXECU11VE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 392","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00392_1990.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00392_1990.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19771-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"Local government units may group ~hemselves,.\nconsolidate or coordinate their efforts, services, and resources for\npurposes commonly beneficial to them in accordance with la\\v.\"\nWHEREAS, it is for the) best interest of the constituents of the .local\ngovernment\ncomprising\nMetropolitan\nconsolidation\nor coordination\nof the efforts, services and resources for\npurposes beneficial to them be administered by their duly elected1Q.cal chief\nexecutives;\n.\nWHEREAS, while Congress is tasked to pass a law that will provide for\nthe metropolitan authority on a more permanent basis, the present demands\nfor a cohesive consolidatkJn or coordination of basic services among the\ncomponent cities and municipalities\nof the Metropolitan Manila necessitate\nan urgent devolution\nof the powers and functions of the Metropolitan\nManila to an interim authority;\n\n'\\\n2\nWHEREAS, Article XVIII, Section 8 of the Constitution states:\nUntil otherwise provided by the Congress, the\nPresident may constitute the Metropolitan\ncomp°.sed of the heads of alllocal.government\nunits comprising\nthe Metropolitan Manila area.\"\nNOW, THEREFORE, I, CORAZON C. AQUINO,\nPresident of the\nPhilippines, by virtue of the powers vested in me by the Constitution and by\nlaw, do hereby order:\nUntil otherwise provided\nby the Congress, there is\nhereby constituted the Metropolitan Manila Authority, hereinafter referred to\nas the Authority,\nto be composed of the heads of the four (4) cities and\nthirteen (13) municipalities comprising the Metropolitan Manila area.\nThe Authority shall have jurisdiction over the delivery of basic urban\nservices requiring\ncoordination\nin the Metropolitan\nThese basic\nurban services shall include among others:\nland use, planning and zoning;\nmanagement;\nsafety; urban development\nand renewal;\nmanagement and control of operations during calamities and emergencies\naffecting public welfare and safety; and sanitation and waste management.\nAny change in the classification of zoning shall however be s~bje.ct to the\napproval of the Housing and Land Use Regulatory'Board (HLURB). ;\n~\nThe Authority\nshall be governed by the Metropolitan\nManila Council, hereinafter referred to as the Council, composed of the\nMayors of the four (4) cities and thirteen (13) municipalities of Metropolitan\nThe Chairman shall be elected from among the Mayor members of the\nCouncil to serve for a term of six (6) months. The Council shall be assisted by\na professional Metropolitan\nGeneral Manager and three Deputy General\nManagers to be appointed by the President of the Philippines.\nThe Secretaries of Transportation and Communications, Public Works\nand Highways, and Budget and Management shall attend all meetings of the\nCouncil as non-voting members.\nCouncil shall be responsible for the following:\n1.\nFormulation\nof policies\non the delivery\nof basic services\nrequiring coordination or consolidation for the operations of the Authority;\n2.\n.Promulgation\nresolutions\nmetropolitan-wide\napplication, approval of a code of basic services requiring\ncoordination, and exercise of its rule-making powers.\n\n3\nThe members of the Council shall have one (1) vote each. The Council\nshall establish the necessary technical, consultative and secretariat support.\nThe Metropolitan Manila Commission shall devolve to\nthe Authority\nall its power~ and functions,\nwhich are not otherwise\ninconsistent with the Constitution and existing laws, in order to carry out its\nbasic urban services requiring\ncoordination\nconsolidation in Metropolitan Manila.\nThe Chairman of the Council shall have the following\n1.\nCall and preside at the meetings of the Council;\n2.\nPresent for the approval of the Council the annual budget of the\n3.\nSubmit the organizational structure and staffing pattern of the\nAuthority for approval by the Council and the President;\n4.\nPresent for the approval of the Council after consultation with\nthe local government units and the appropriate\ngovernment entities the\nfollowing plans and proposals: the annual operations plan, proposeq policies\nand programs, revenue-raising measures and proposals, draft rules andregula\nsuch other plans and projects necessary to carry out the\npurpose of this Executive Order and which require the approval of the\n.\n5.\nPrepare and submit to the Council and to the President of thePhilip\nannual reports and evaluation of programs and projects;\n6.\nRecommend to the President and Congress, with the approval of\nthe Council, measures which will improve the quality of life of the people in\nMetropolitan\nManila or which will introduce services not covered by this\nExecutive Order which are necessary for the betterment of Metropolitan\n7.\nto the national\npolicy-making\nimplementation of plans and programs of agencies and/or local governments\nthat conform to the regional development plan; and\n8.\nPerform such other functions as may be required by law, by the\nPresident, or by the Council of the Authority\nin accordance with this\nExecutive Order.\n...\nThe Metropolitan General Manager of the Authority shall\nhave the following functions:\n\n4\n1.\nManage the day-to-day operations of the Authority;\n2.\nDevelop programs and implement projects along the policies set\nby the Council and assist the Chairman of the Council in the management\nand operations of the Authority;\n3.\nAct as head of the technical, consultative and management staff\nof the Authority;\n4.\nAssist the Chairman and the Council in the preparation of rules\nand regulations, the comprehensive development plan, the operations plan\nand appropriation measure, the basic services code, and such other measures\nwhich a're necessary to help the Chairman and the Council\nobjectives of this Executive Order;\n5.\nPrepare the annual reports and other reports of projects and\nprograms required by this Executive Order, for the approval of the Chairman;\n6.\nPerform such other functions as may be required by law, by the\nCouncil, or by its Chairman.\nThe local government units shall continue to. be primarily\nresponsible for the administration of their respective political jurisdictions.\nWhile local.. governments shall be-invol ved with specific problemS-and is\nconcerning their respective political jurisdictions, the Authority shall attend\nto metropolitan-wide\nandior common problems or those transcending. local\nboundaries.\nLocal city and municipal councils shall formulate and submit\ncity /municipal\nplans and priorities to Authority\nfor integration with the\nsectoral and regional plans. The Authority shall provide technical assistance\non the preparation of local development plans and programs to\nensure conformity\nwith the regional plan.\nThe Authority\nshall review\nlegislation proposed by the local legislative assemblies to ensure consistency\namong local governments and with the comprehensive development plan of\nMetropolitan Manila, and advise the local governments accordingly.\nTo carry out the purposes of this Executive Order, the\nshall submit to the Department of Budget and Management the\nbudget for its annual operating expenses for inclusion\nin the general\nappropriations law.\nand municipal\ntreasurers\nof the local government\ncomprising Metropolitan\nManila shall continue to collect all revenues and\nreceipts accruing to the Metropolitan\nManila Commission and remit the\nsame to the Authority; Provided, that such income coliections as well as the\nshare of the Authority\nfrom the regular sources of revenue in the General\nFund of the city or municipality as local counterpart for the integrated basic\nservices and developmental projects shall be treated as a trust fund in their\n\n5\nbooks of account; Provided, further,\nthat the remittances thereof shall be\neffected within the first thirty (30) days following the end of each month.\nFailure to remit the same within the prescribed period without justifiable\nreason shall subject the person or persons responsible for such delay to the\npenalties and sanctions imposed under existing laws.\nIn this regard, the\nCouncil is authorized to conduct an inquiry as to the cause of such delay.\nAll sources of revenues of the Metropolitan Manila Commission shall\nremain valid and in effect, and shall henceforth pertain to the Authority.\nAll city and municipal treasurers, municipal\nassistants as well as all other officials whose appointment is\nvested upon the Metropolitan\nCommission\nappointed by the President of the Philippines, upon recommendation of the\nCouncil, subject to the Civil Service law, rules and regulations.\n'\nOther treasury and assessment personnel shall be appointed by the\nlocal chief executive in the city or municipality in accordance with existing\nThe Authority, the Council, the Chairman of the Council,\nand the Metropolitan\nManager shall be under the direct supervision of the\nPresident of the Philippines.\nThe President shall have the power w revoke,\namend or modify any rule, resolution or act of the. Authority, the Council, the\nCliairinanorfue\nThe President shall continue to exercise administrative\ndisciplinary\njurisdiction over the elective City and Municipal officials in the Metropolitan\nTo enable the Preside~t of the Philippines to assess the\nperformance of the Authority and the management system of Metropolitan\nManila, the Authority\nshall undertake a periodic review of its functions,\norganiZational structure, and impact of its programs and projects at least once\nevery year and submit a special report thereof to the President with\nappropriate findings and recommendations. -\nTo prevent disruption\nin the delivery of basic urban\nservices pending the full implementation of the Authority's\norganizational\nstructure and staffing pattern, all officials and employees of. the Metropolitan .,\nCommission\nthe incumbent Commissioners\nautomatically become Deputy General Manager, shall continue to exercise\ntheir duties and functions under the direction of the Authority\nhave been given notice for change of duties and functions, transfer to another\noffice or position, or termination of service. Until otherwise provided by law,\nthe Authority shall be exempted from the coverage of Batas Pambansa BIg.\n337, the Local Government Code.\n\n6\n# .\nassets and properties\nin use and/or\naccountability of the Metropolitan Manila Commission and all its obligations,\nindebtedness or liabilities shall be transferred to the Authority\nconditions\nthat may be established by the Department of Budget and\nManagement, Office of the President and Commission on Audit.\nCivil service laws and regulations pertinent to the displacement of\npersonnel affected by this Executive Order shall be strictly enforced.\nThe Acting Governor of the Metropolitan\nManila shall\nsupervise the transfer to the Authority\nof such subsisting powers and\nfunctions, including\nthe transfer of properties, assets and liabilities,\npersonnel of the Metropolitan Manila Commission within the period of sixty\n(60) days from the date of this Executive Order. Upon the effectivity of this\nExecutive Order, the Acting Governor shall convene the mayors of the cities\nand municipalities\ncomprising Metropolitan Manila and shall preside at its\norganizational meeting, which shall include, among others, in its agenda the\nelection of the Chairman of the Council. After the election of the Chairman\nof the Council but within\nsixty (60) days referred to herein, the Acting\nGovernor shall turn over the affairs of the Metropolitan Manila Commission\nto the Council.\n-\nThis Executive Order shall take effect upon app:r;oval and\ncompletion\nof its publication\nin at ~east two\ngeneral-circulation;-:--~~\n-:- -,;;- --~\n'\n'\nDONE in the City of .Manila, this 9th\nOur Lord, nineteen hundred and ninety.\nday of January, in the year of\nBy the President:\n~;~~~~~~~~\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19772"] = {"id":"PH-H19772","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"THE PRESffiENT OF THE P~IPPINES EXECUTIVE ORDER NO. \"392.. DECLARING FULL DEREGULATION OF THE DOWNS11iE-AM OIL INDUSTRY","orig":"THE PRESffiENT OF THE P~IPPINES EXECUTIVE ORDER NO. \"392.. DECLARING FULL DEREGULATION OF THE DOWNS11iE-AM OIL INDUSTRY"},"level":"law","status":"active","docNumber":"Executive Order No. 392","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00392_1997.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00392_1997.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19772-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"of Republic Act No. 8180, otherwise known as the\n\"Downstream Oil Industry Deregulation Act of 1996,\" provides that \"the DOE shall, upon\napproval of the President, implement the full deregulation of the downstream oil industry\nnot later than March, 1997. As far as practicable, the DOE shall time the full deregulation\nwhen the prices of crude oil and petroleum products in the world market are declining and\nwhen the exchange rate of the peso in relation to the US dollar is stable;\"\nWHEREAS, pursuant to the recommendation of the Depanrnent of Energy, there is\nan imperative need to implement the full deregulation of the downstream oil industry\nbecause of the following recent developments: (i) depletion of the buffer fund on or about 7\nFebruary 1997 pursuant to the Energy Regulatory Board's Order dated 16 January 1997;\n(ii) the prices of crude oil had been stable at $21 -$23 per barrel since October 1996 while\nprices of petroleum products in the world market had been stable since mid-December of\nlast year. Moreover, crude oil prices are beginning to soften for the last few days while\nprices of some petroleum products had already declined; and (iii) the exchange rate of the\npeso in relation to the US dollar has been stable for the past twelve (12) months, averaging\nat around P26.20 to one US dollar;\n.\nWHEREAS, Executive Order No. 377 dated 31 October 1996 provides for an\ninstitutional framework for the administration of the deregulated industry by defining the\nfunctions and responsibilities of various government agencies;\nWHEREAS, pursuant to Republic Act. No. 8180, the deregulation of the industry\nwill foster a truly competitive market which can better achieve the social policy objectives\nof fair prices and adequate, continuous supply Qf environmentally-clean and high quality\npetroleum products;\nYING PLEASE CITEI\nH970194IIIIIIIIIIIIII\n197()194\n\n-2-\nNOW, THEREFORE, I, FIDEL V. RAMOS, President of the Republic of the\nPhilippines, by the powers vested in me by law, do hereby declare the full deregulation of\nthe downstream oil industry.\nDONE in the City of Manila, this ~y\n\"\"!l in the year of Our\nLord, Nineteen\nand Ninety-Seven.\nP~y1S LIBRARY\n~\nThis Executive Order shall take effect on 8 February 1997."}}],"pack":"ph-p158"};
  FT["PH-H19773"] = {"id":"PH-H19773","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES ENTITLED \"TRANSFERRING THE MEDICARE FUNCTIONS OF THE WORKERS WELFARE ADMINISTRATION PHILIPPINE HEALTH INSURANCE CORPORATION","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES ENTITLED \"TRANSFERRING THE MEDICARE FUNCTIONS OF THE WORKERS WELFARE ADMINISTRATION PHILIPPINE HEALTH INSURANCE CORPORATION"},"level":"law","status":"active","docNumber":"Executive Order No. 392","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00392_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00392_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19773-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Section 2 of Executive Order No. 182 dated February 14, 2003 is\nhereby amended to read as follows:\n\"SEC. 2. Transfer of Health Insurance Funds of the\nOWWA. - A portion of the Health Insurance Fund being administered by\nthe OWWA shall be transferred to the PHIC within sixty (60) days from\nthe effectivity of this Executive Order. The Fund to be transferred shall\nbe in the amount actuarially needed to fund the basic OFW Medicare\nProgram for a period of one (1) year to ensure continuity of service to\nOFWs provided, that the remaining portion of the Health Insurance Fund\nshall be retained and used by OWWA exclusively for implementing a\nsupplemental health benefit package for OFWs.\nThe transfer shall in no case result in any diminution or\ndiscontinuity of the existing benefit package.\nRepeal. - All orders, rules, regulations, issuances or parts\nthereof, which are inconsistent with this Executive Order are hereby repealed or\nmodified accordingly.\nEffectivity. - This Executive Order shall take effect fifteen (15)\ndays following its publication in the Official Gazette or in two (2) newspapers of general\ncirculation.\nDONE, in the City of Manila this 28th day of December\nin the year of Our\nLord Two Thousand and Four.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19774"] = {"id":"PH-H19774","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":12,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CONVERTING THE PRESENT CENTRAL LUZON AGRICULTURAL SCHOOL INTO THE CENTRAL LUZON AGRICULTURAL COLLEGE, CONFER- RING THE TITLE OF ASSOCIATE IN AGRICUL- TURAL EDUCATION AND THE DEGREES OF BACHELOR OF SCIENCE IN AGRICULTURAL EDUCATION AND MASTER OF SCIENCE IN AGRICULTURAL EDUCATION, PROVIDING FOR A BOARD OF TRUSTEES, DEFINING THE BOARD'S RESPONSIBILITIES AND DUTIES, PRO- VIDING PROFESSIONAL AND TECHNICAL IN STRUCTION, AND FOR OTHER PURPOSES.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CONVERTING THE PRESENT CENTRAL LUZON AGRICULTURAL SCHOOL INTO THE CENTRAL LUZON AGRICULTURAL COLLEGE, CONFER- RING THE TITLE OF ASSOCIATE IN AGRICUL- TURAL EDUCATION AND THE DEGREES OF BACHELOR OF SCIENCE IN AGRICULTURAL EDUCATION AND MASTER OF SCIENCE IN AGRICULTURAL EDUCATION, PROVIDING FOR A BOARD OF TRUSTEES, DEFINING THE BOARD'S RESPONSIBILITIES AND DUTIES, PRO- VIDING PROFESSIONAL AND TECHNICAL IN STRUCTION, AND FOR OTHER PURPOSES."},"level":"law","status":"active","docNumber":"Executive Order No. 393","issuingBody":"President of the Philippines","completenessNote":"全文，共 12 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00393_1950.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00393_1950.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19774-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The aim of the said College shall be to provide\nprofessional, technical, and special instruction, for special\npurposes, promote research, extension service, and progres-\nsive leadership in the field of agricultural education."}},{"id":"PH-H19774-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"The head of this institution shall be known as.\nthe President of the Central Luzon Agricultural College.\nHe shall be appointed by the President of the Philippines\nupon the recommendation of the Board of Trustees as\nhereinafter provided. The powers and duties of the Pres-\n\n5926\nOFFICIAL GAZETTE\nident of the College, in addition to those specifically pro-\nvided for in this order, shall be those usually pertaining\nto the office of the president of a college."}},{"id":"PH-H19774-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"The government of said college is hereby vested\nin a Board of Trustees of the Central Luzon Agricultural\nCollege. The Board of Trustees shall be composed of the\nSecretary of Education, who shall be exofficio Chairman\nof the Board, the Chairman of the Committee on Education\nof the Senate, the Chairman of the Committee on Educa-\ntion of the House of Representatives, the Director of Public\nSchools, the President of the College, and the President\nof the Central Luzon Agricultural College Alumni Asso-\nMembers of the Board shall serve without compensa-\ntion, other than actual and necessary expenses incurred\neither in attendance upon meetings of the Board or upon\nother official business authorized by resolution of the"}},{"id":"PH-H19774-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Board of Trustees shall have the following\npowers and duties, in addition to its general powers of ad-\nministration:\n(a) To receive and appropriate to the ends specified by\nlaw such sums of money as may be provided by law for the\nsupport of the College;\n(6) To confer the title of Associate in Agricultural Edu-\ncation and the degrees of Bachelor of Science in Agricul-\ntural Education and Master of Science in Agricultural\nEducation to successful candidates for graduation;\n(c) To appoint, on the recommendation of the President\nof the College, instructors, professors, lecturers, and other\nemployees of the College; to fix their compensation, hours\nof service and such other duties and conditions as it may\ndeem proper; to grant to them, in its discretion, leave of\nabsence under such regulations as it may promulgate, any\nother provisions of law notwithstanding, and to remove\nthem for cause after an investigation and hearing shall\nhave been had;\n(d) To approve the curricula and rules of discipline\ndrawn up by the College Council as hereinafter provided;\n(e) To fix the tuition fees required of students, as well\nas matriculation fees, graduation fees and for laboratory\ncourses, and all special fees, and to remit the same in\nspecial cases;\n(f) To provide fellowships for faculty members and\nscholarships to students showing special evidence of merit;\n(g) To provide rules for its own govermment, and to\nenact for the government of the College such general or-\ndinances and regulations, not contrary to law, as are\n\nOFFICIAL GAZETTE\nconsistent with the purposes of the College, as defined in\nsection two of this Order;\n(h) To receive in trust legacies, gifts, donations of real\nand personal property of all kinds and to administer the\nsame for the benefit of the College or for aid to any students,\nin accordance with the directions and instructions of the\ndonor, and, in default thereof, in such manner as the Board\nof Trustees may in its discretion determine."}},{"id":"PH-H19774-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"A quorum of the Board of Trustees shall consist\nof a majority of all the members. All process agairst the\nBoard of Trustees shall be served on the president or\nsecretary thereof."}},{"id":"PH-H19774-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"On or before the fiteenth of June of each year,\nthe Board of Trustees shall file with the President of the\nPhilippines a detailed report, setting forth the progress,\nconditions, and needs of the College."}},{"id":"PH-H19774-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"There shall be a College Council consisting of\nthe President of the College as presiding ufticer and of all\ninstructors and professors of the College as members.\nThe Council shall have the power to prescribe the curri-\ncula and rules of discipline, subject to the approval of the\nBoard on Trustees. It shall fix the requirements. for ad-\nmission to the College. as well as for graduation and the\nreceiving of a title or a degree. The Council alone shall\nhave the power to recommend students or others to be\nrecipients of titles or degrees. Through its president or\ncommittee, it shall have disciplinary power over the stu-\ndents within the limits prescribed by the rules of discipline\napproved by the Board of Trustees."}},{"id":"PH-H19774-A9","no":9,"noLabel":{"en":"Sec 9"},"text":{"en":"The body of instructors and professors of the\nCcllege shall constitute the faculty of the college. In the\nappointment of professors or instructors of the College; no\nreligious test shall be applied nor shall religious pinions\nor affiliations of the faculty of the College be made a matter\nof examination or inquiry: Provided, however, That no\ninstructor or professor in the College shall indulcate sec-\ntarian tenets in any of the teachings, nor attempts either\ndirectly or indirectly, under penalty of dismissal by the\nBoard of Trustees, to influence students or attendance at\nthe College for or against any particular church or reli-"}},{"id":"PH-H19774-A10","no":10,"noLabel":{"en":"Sec 10"},"text":{"en":"Professors and other regular instructors in the\nCollege shall be exempt as such from any civil service exam-\ninations or regulations as a requisite to appointment.\nSec. il. There shall be a Secretary of the. College, ap\npointed by the Board of Trustees. He shall be the sec-\nretary of such Board and also of the College, and shall keep\nsuch records of the college as may be designated by the\n5927:\n\n5928\nOFFICIAL GAZETTE\nSEc. 12. Heads of bureaus or offices of the National Gov-\nernment are hereby authorized to loan or transfer, upon\nrequest of the President of the College, such apparatus or\nsupplies as may be needed by the College, and to detail em-\nployees for duty therein, when in the judgment of the head\nof the bureau or office such supplies or employees can be\nspared without serious detriment to the public service."}},{"id":"PH-H19774-A13","no":13,"noLabel":{"en":"Sec 13"},"text":{"en":"The President of the College, with the coopera-\ntion of the Director of Public Schools, may use one or more\npublic schools as training or laboratory schools of the Col-"}},{"id":"PH-H19774-A14","no":14,"noLabel":{"en":"Sec 14"},"text":{"en":"In order not to interrupt the smooth functioning\nof the four-year secondary agricultural curriculum, tha one-\nyear farm mechanics curriculum, and other special curri-\ncula of the Central Luzon Agricultural School, the faculty\nof the school, consisting of the Principal, Assistant Prin-\ncipal and teachers, as well as the other personnel, shall be\nabsorbed by the new College. Salaries of this personnel\nshall be adjusted at the discretion of the Board of Trustees\nwithin the amount available for appropriation.\nSEc. 15. For the purpose of the giving effect to this\nOrder, all the unexpended balances of appropriation under\nthe control of the former Central Luzor Agricultural\nSchool are hereby made available for the operation of the\nCentral Luzon Agricultural College until June 30, 1951.\nThereafter, the necessary funds shall be provided in the\nannual General Appropriation Acts."}},{"id":"PH-H19774-A16","no":16,"noLabel":{"en":"Sec 16"},"text":{"en":"This Order shall take effect upon its promul-\nDone in the City of Manila, this 31st day of December,\nin the year of Our Lord, nineteen hundred and fifty, and\nof the Independence of the Philippines, the fifth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the Presicent:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19775"] = {"id":"PH-H19775","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1960/eo_393_1960.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Municipality of Mahayag in the Province of Zamboanga Del Sur","orig":"Creating the Municipality of Mahayag in the Province of Zamboanga Del Sur"},"level":"law","status":"active","docNumber":"Executive Order No. 393","issuingBody":"President of the Philippines","promulgatedDate":"1960-05-10","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00393_1960_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00393_1960_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19775-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 393, May 10, 1960 ]\nCREATING THE MUNICIPALITY OF MAHAYAG IN THE PROVINCE OF ZAMBOANGA DEL SUR\nUpon the recommendation of the Provincial Board ol Zamboanga del Sur and pursuant to the provisions of\nsection sixty-eight of the Revised Administrative Code, the barrios and sitios of Mahayag, Balanan, Bagong\nDalaguat, Bagong Balamban, Cabuhi, Dilosom, Diwan, Guisapok, Dao, Lower Salug, Panagaan, San Jose,\nSan Isidro, San Vicente, Sto. Niño, Sicpao, Tumapic, Tuboran, Upper Sicpao, and Upper Salug Daku, all of\nthe municipality of Molave, province of Zamboanga del Sur, and the barrios of Bongyao, Pugwan, and Yabu,\nall of the municipality of Dumingag, same province, are hereby segregated from said municipalities and\norganized into an independent municipality in said province, to be known as the municipality of Mahayag\nwith the seat of government at the barrio of Mahayag.\nThe municipality of Mahayag as herein organized shall have the following boundaries:\n“Beginning at point 1, Km. 158 of Salug-San Isidro Road; thence, to point 2, S-42-00-W with a distance of\nabout 3,500 meters, intersecting with Salub Daku River; thence, to point 3, following Salug Daku River\ndownstream until it intersects Dipolo River with a distance of about 3,500 meters; thence, to point 4,\nfollowing the course of Dipolo River with a distance of about 3,000 meters, until the intersections of the\nformer municipal boundary of Liargao and Molave with Dipolo River; thence, to point 5, following the former\nboundary of Liargao and Molave with a distance of about 3,200 meters; thence to point 6, N-11-00-W, with a\ndistance of about 14,500 meters, following the former municipal boundary of Dumingag and Molave; thence,\nto point 7, due north following the former boundary of Dumingag and Molave with a distance of about 18,600\nmeters at the intersection of the Provincial Boundary of Zamboanga del Norte and Zamboanga del Sur;\nthence, following a course S-38-00-E to a distance of about 18,200 meters, until it reaches barrio Diolon at\npoint 8; thence due south back to point 1 at Km. 158 of Salug-San Isidro Road.” (As described by E. T. Nery,\nActing Highway District Engineer of the province of Zamboanga del Sur, submitted and on file in this Office.)"}}],"pack":"ph-p158"};
  FT["PH-H19776"] = {"id":"PH-H19776","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Prescribing Regulations inthe Operation and Activities of Private Detectives, Watchmen and Security Guards","orig":"Prescribing Regulations inthe Operation and Activities of Private Detectives, Watchmen and Security Guards"},"level":"law","status":"active","docNumber":"Executive Order No. 393","issuingBody":"President of the Philippines","promulgatedDate":"1972-05-10","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00393_1972_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00393_1972_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19776-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 393 May 10, 1972\nPRESCRIBING REGULATIONS IN THE OPERATION AND ACTIVITIES OF PRIVATE DETECTIVES,\nWATCHMEN AND SECURITY GUARDS\nWHEREAS, the operation and activities of private detectives, watchmen and security guards are directly\nrelated to or affect the peace and order condition of the country;\nWHEREAS, to insure that the operations and activities of private detectives, watchmen and security guards\nwill not jeopardize or impair peace and order, it is necessary that such activities be subject to government\nsupervision and regulation;\nWHEREAS, the activities of certain persons who should be classified as private detectives, watchmen and\nsecurity guards, which should be regulated by the government, are not at present adequately provided for;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by the Constitution and existing laws, do hereby order that the power of supervision and such\nother powers vested in the Philippine Constabulary under Republic Act No. 5487, otherwise known as the\nPrivate Security Agency Law, over private detectives, watchmen and security guards agencies shall extend or\napply to any person who offers or renders personal services to watch or secure either residential or business\nestablishments, or both, or any building, compound or area including but not limited to logging concessions,\nagricultural, mining or pasture lands for hire or compensation, or as an employee thereof, who shall be known\nas a watchman or security guards; and to any person, association, partnership or corporation who permits,\ntrains, musters, furnishes, solicits individuals or business firms, private or government-owned or controlled\ncorporations to engage his services or those of its watchman, who shall be known as a watchman or security\nguard agency.\nDone in the City of Manila, this 10th day of May, in the year of Our Lord, nineteen hundred and seventy-two."}}],"pack":"ph-p158"};
  FT["PH-H19777"] = {"id":"PH-H19777","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG EXECUTIVE (\"\"'\"'ryER NO.","orig":"MALACANANG EXECUTIVE (\"\"'\"'ryER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 393","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00393_1990.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00393_1990.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19777-A1","no":1,"noLabel":{},"text":{"en":"integrate, direct, control and supervise all measures aimed at preventing or\nsuppressing all forms of hijacking or kidnapping involving civil aviation and\nairline industry operations; ensuring the safe and continuous operation of\nthe airline industry and civil aviation; and handling all incidents of hijacking\nand all other offensive and t~rroristic activities.\n2\nThe Committee shall adopt measures geared towards a\n\"total approach\" to the problem of preventing offensive and terroristic acts\ndirected against the airline industry and civilian aviation.\nThese measures\nshall include\na provision for an adequate organization for pljlnning\nimplementation\nat all the levels; organization of a control cl11d coordinating\ncenter in each domestic and international airports throug11.out the country\nwhich can effect immediate response from all tasked units cr agencies, with a\nclear delineation of their respective authority and functions; and formulation\nof guidelines for the mass media in reporting incidents of hijacking and other\noffensive and terroristic acts in order not to prejudice the effectiveness of\nanti-hijacking plans and operations.\nThe Committee is hereby authorized to call upon other\ndepartments,\noffices, agencies and instrumentalities\ngovernment'\nand the civilian\nfor assistance in the effective\nimplementation of this Executive Order.\nherein contained\nshall be construed\ndiminishing\nor altering the powers and functions of the Airport\nCenter under Section 14(b) of Executive Order No. 125, \"Reorganizing The\nMinistry of Transportation and Communications, Defining Its Powers and\nFunctions and For Other Purposes\", as amended.\nThis Executive Order shall take effect immediately.\nday of January, in the year of\nDONE in the City of Manila, this\nOur Lord, nineteen hundred and ninety.\nBy the President:\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19778"] = {"id":"PH-H19778","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"BY THE PRESmENT OF THE PHll..IPPINES EXECUTIVE ORDER NO. ~ ESTABLISHING THE SAJID BULIG PRESmENTIAL A W ARB FOR HERO ISM","orig":"BY THE PRESmENT OF THE PHll..IPPINES EXECUTIVE ORDER NO. ~ ESTABLISHING THE SAJID BULIG PRESmENTIAL A W ARB FOR HERO ISM"},"level":"law","status":"active","docNumber":"Executive Order No. 393","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00393_1997.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00393_1997.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19778-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Creation of the Award.\nHeroism is hereby established.\nThe Sajid Bulig Presidential Award for"}},{"id":"PH-H19778-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Objectives of the Awards. The primary objective of the Sajid Bulig\nPresidential Award, herein referred to as the Award, is to accord official recognition to an\nindividual who has demonstrated exemplary courage in the service of humanity, even at\nthe cost ofhis/her life. Specifically, the Award seeks to:\nConfer distinct recognition to an individual who risked his/her life in the service of\nthe community, nation and humanity;\nReward individuals for exemplary deeds, outstanding feats or acts of heroism; and\nGlorify examplars of the virtues of courage, selflessness, gallantry, bravery, and\nDatriotism worthy of emulation by all Filipinos.\n\nConstitution of National, Regional and Provincial Screening\nCommittees. Screening Committees at the national, regional and provincial levels are\nhereby organized with the following composition, functions and responsibilities:\nNational Screening Committee\nSecretary, Department of the Interior and Local Government\nNational President, League of Provinces\nNational President, League of Cities\nNational President, League of Municipalities\nNational President, Liga ng mga Barangay\nUndersecretary for Peace and Order, Dll..G\nUndersecretary for Local Government, DILG\nOne (1) private sector representative/NGO\nThe National Screening Committee shall undertake the following:\nactivities\nsuccessful\nInitiate and coordinate necessary\nimplementation of the Award;\nSelect the private sector representative/NGO partner of the National\nAwards Committee;\nSet policy guidelines, mechanics and criteria for the selection of the\nScreen regional nominees in accordance with the prescribed criteria;\n~\nRecommend to the President a possible awardee;\nPlan and implement appropriate awarding ceremonies; and\nProvide funding for operational expenses and prizes.\nThe Bureau of Local Government SupeIVision (BLGS) of the Department of the\nInterior and Local Government shall serve as the National Secretariat for the National\nScreening Committee and shall be the lead in the administration of the Award.\n\\~\n2\n\nRegional Screening Committee\nDILG Regional Director\nPNP Regional Director\nNAPOLCOM Regional Director\nRepresentative,\nLeague of Provinces\nRepresentative, League of Cities\nRepresentative, League of Municipalities\nRepresentative, Liga ng mga Barangay\nOne (1) private sector/NGO partner\nThe Regional Screemng Committee shall undertake the following:\nInitiate and coordinate necessary activities for the implementation of the\nAward in the region; and\n3.\nScreen, select, and nominate to the National Screening Committee a\ncandidate awardee from cities or from the Provincial Screening Committee.\nThe DILG Regional Office shall serve as the Secretariat for the Regional Screening\nProvincial Screening Committee\nProvincial Local Government Operations Officer, DILG\nPresident, Provincial Chapter, League of Municipalities\nPresident, Provincial Chapter, Liga ng mga Barangay\nPresident, Panlalawigang Pederasyon\nng Sangguniang\nPresident, Provincial Federation of Sanggunian Members\nOne (1) private sector/NGO partner\nThe Provincial Screening Committee shall undertake the following:\n\\~\n3\n\nInitiate and coordinate necessary activities for the implementation Qf the\nAward in the province;\nMobilize support of the municipalities and barangays withill the province in\nthe search for modem-day heroes; and\n.\nScreen, select and nominate to the Regional Screening Committee a\ncandidate awardee of the province.\nThe DILG Provincial Office shall serve as the Secretariat for the Provincial\nScreening Committee."}},{"id":"PH-H19778-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Activation of Committees.\nshall be convened whenever necessary.\nThe screening committees herein established"}},{"id":"PH-H19778-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Funding.\nFunding sources for operations of the committees and for\nprizes shall be identified by the National Awards Committee."}},{"id":"PH-H19778-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"Awards and Prizes. The Sajid Bulig Presidential Awardee shall receive a\nspecial Plaque of Commendation and other prizes as may be determined by the National\nScreening Committee."}},{"id":"PH-H19778-A7","no":7,"noLabel":{"en":"SEC 7"},"text":{"en":"Conferment of the Award. The President shall confer the Award to a\nselected Awardee. The Award may be conferred posthumously, on behalf of the deceased\nAwardee, to his/her legal heir or nearest of kin."}},{"id":"PH-H19778-A8","no":8,"noLabel":{"en":"SEC 8"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 22nQ day of January, in the year of Our Lord,\nNineteen Hundred and Ninety-Seven.\n4"}}],"pack":"ph-p158"};
  FT["PH-H19779"] = {"id":"PH-H19779","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES ABOLISHING THE ANTI-SMUGGLING INTELLIGENCE AND INVESTIGATION","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES ABOLISHING THE ANTI-SMUGGLING INTELLIGENCE AND INVESTIGATION"},"level":"law","status":"active","docNumber":"Executive Order No. 393","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00393_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00393_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19779-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Abolition.\nAnti-Smuggling\nIntelligence and\nInvestigation Center created under Executive Order No. 155, series of 2002, is hereby\nabolished. Its personnel are hereby returned to their mother units, and its assets are\nhereby transferred to the Presidential Anti-Organized Crime Commission.\nRepealing Clause. - All executive issuances, orders, rules and\nregulations or parts thereof inconsistent with the provisions of this Executive Order are\nhereby repealed or modified accordingly.\nEffectivity. - This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 28th day of Decarber in the year of our Lord\nTwo Thousand and Four.\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nachE Halegram • 28979"}}],"pack":"ph-p158"};
  FT["PH-H19780"] = {"id":"PH-H19780","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ESTABLISHING AN INTER-ISLAND SHIPPING AUTHORITY, WAR RISK INSURANCE FOR VESSELS ENGAGED IN THE COAST-VISE TRADE AND APPROPRIATING FOR THAT PURPOSE FIVE MLLION PESOS FROM THE FUNDS IN TIIE PHILIPPINE TREASURY SET ASIDE FOR DEFENSE AND CIVILIAN PROTECTION MEASURES.","orig":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ESTABLISHING AN INTER-ISLAND SHIPPING AUTHORITY, WAR RISK INSURANCE FOR VESSELS ENGAGED IN THE COAST-VISE TRADE AND APPROPRIATING FOR THAT PURPOSE FIVE MLLION PESOS FROM THE FUNDS IN TIIE PHILIPPINE TREASURY SET ASIDE FOR DEFENSE AND CIVILIAN PROTECTION MEASURES."},"level":"law","status":"active","docNumber":"Executive Order No. 394","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00394_1941.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00394_1941.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19780-A1","no":1,"noLabel":{},"text":{"en":"OFFICIAI.   GAZETTE\nQUEZON  I  VoJwmc 4\nPhilippine Treasury for the purposes set forth in this  Order. The expenses of the hterisland Shipping\nAuthority shall be made in accordance with a budget approved by the President of the Philippines.\nDone  at  the  City  of Manila.,  this  24th  day  of December,  in  the  year  of  Our  Lord,  Nineteen\nhundred and forty-one and of the Commonwealth of the Philippines, the seventh.\n(SGD. ) MANUEL L. QUEZON\nBy the President:\n(SGD.) TORGE 8. VARGAS\nSecretary to the President\nSouroe.. Presidential  Museum and  Library\nOffice  of the  President  of  the  Philippines.  (1941).  /Exccz4£j.ye  Order  Nas.;  33J  -400j.  Manila:\nPresidential Museum and Library."}}],"pack":"ph-p158"};
  FT["PH-H19781"] = {"id":"PH-H19781","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING AN ACCOUNTING OFFICE AND AN AUDITING UNIT FOR THE PHILIPPINE ARMY","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING AN ACCOUNTING OFFICE AND AN AUDITING UNIT FOR THE PHILIPPINE ARMY"},"level":"law","status":"active","docNumber":"Executive Order No. 394","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00394_1950.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00394_1950.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19781-A1","no":1,"noLabel":{},"text":{"en":"OFFICIAL GAZETTE\nElpidio Quirino, President of the Philippines, do hereby\n1. There are hereby created an Accounting Office and\nan Office of the Representative of the Auditor General to\nhandle the accounting and auditing work of the Philippine\nArmy, the said units to be composed of the following per-\nsonnel at salaries set opposite each:\n(a) Accounting Office:\n1. One accounting officer\n2. One accountant\n3. Ore bookkeeper\n4. Two clerks at P2,760 each\n5. Two clerks at P2,400 each\n6. Six clerks at P2,160 each..\n7. Three clerks at P1,220 each\n8. One stenographer\n9. Fifteen helpers at P1,440 each\n10. Fourteen helpers at P1,320 each\nDel aBalusi\n4,800.00\n2,760.00\n5,520.00\n4,800.00\n12,960.00\n5,760.00\n1,920:00\n21,600.00\n18,480.00\n5929\n(b) Office of the Representative of the Auditor General:\n1. One auditor\n2. One assistant auditor\n3. One audit clerk\n4. Three audit clerks at P2,280 each\n5. Two clerks at P2.160 each\n7. Three clerks at P1,920 each\n8. One stenographer\n10. Seven emergency employees at P5 each per day\n3,960.00\n2,580.00\n6,840.00\n4,320.00\n2,040.00\n1,800.00\n1,800.00\n10,500.00\n2. The appropriations needed for the aforesaid account-\ning and auditing units shall be taken from the following\nappropriations of the Philippine Army:\nR. A. No. Item No.\n563\n568\n563\n1\n13\n16\n384\n385\n386\n10,000.00\n34,380.00\n3. This Order shall take effect as of July 1, 1950.\n5080\nOFFICIAL GAZETTE\nDone in the City of Manila, this 31st day of December,\nin the year of Our Lord, nineteen hundred and fifty, and\nof the Independence of the Philippines, the fifth.\nELPIDIO QUIRINo\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19782"] = {"id":"PH-H19782","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1960/eo_394_1960.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Transferring the Seat of Government of the Municipality of Burgos, Province of Ilocos Sur, From Its Present Site At the Poblacion of Barrio Bato to the Barrio of Luna, Same Municipality","orig":"Transferring the Seat of Government of the Municipality of Burgos, Province of Ilocos Sur, From Its Present Site At the Poblacion of Barrio Bato to the Barrio of Luna, Same Municipality"},"level":"law","status":"active","docNumber":"Executive Order No. 394","issuingBody":"President of the Philippines","promulgatedDate":"1960-05-12","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00394_1960_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00394_1960_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19782-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 394, May 12, 1960 ]\nTRANSFERRING THE SEAT OF GOVERNMENT OF THE MUNICIPALITY OF BURGOS, PROVINCE\nOF ILOCOS SUR, FROM ITS PRESENT SITE AT THE POBLACION OF BARRIO BATO TO THE\nBARRIO OF LUNA, SAME MUNICIPALITY\nUpon the recommendation of the Provincial Board of Ilocos Sur and pursuant to the provisions of section\nsixty-eight of the Revised Administrative Code, the seat of government of the municipality of Burgos,\nprovince of Ilocos Sur, is hereby transferred from its present site at the poblacion of barrio Bato to the barrio\nof Luna, same municipality.\nThis Order shall take effect immediately.\nDone in the City of Manila, this 12th day of May, in the year of Our Lord, nineteen hundred and sixty, and of\nthe Independence of the Philippines, the fourteenth.\n(Sgd.) CARLOS P. GARCIA\nPresident of the Philippines\nBy the President:\n(Sgd.) NATALIO P. CASTILLO\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19783"] = {"id":"PH-H19783","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Further Amending Executive Order No. 263 Dated August 15, 1957, Entitled \"Creatingthe Pinaglabanan Commemorative Commission,\" as Amended By Executive Order No. 300 Dated May 29, 1958, and Executive Order No. 433 Dated June 20, 1961","orig":"Further Amending Executive Order No. 263 Dated August 15, 1957, Entitled \"Creatingthe Pinaglabanan Commemorative Commission,\" as Amended By Executive Order No. 300 Dated May 29, 1958, and Executive Order No. 433 Dated June 20, 1961"},"level":"law","status":"active","docNumber":"Executive Order No. 394","issuingBody":"President of the Philippines","promulgatedDate":"1972-05-16","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00394_1972_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00394_1972_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19783-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 394 May 16, 1972\nFURTHER AMENDING EXECUTIVE ORDER NO. 263 DATED AUGUST 15, 1957, ENTITLED\n\"CREATING THE PINAGLABANAN COMMEMORATIVE COMMISSION,\" AS AMENDED BY\nEXECUTIVE ORDER NO. 300 DATED MAY 29, 1958, AND EXECUTIVE ORDER NO. 433 DATED\nWHEREAS, at the initiative of the patriotic association called The Spirit of 1896, a campaign has been\nlaunched to enlist public support for the erection of an appropriate monument or memorial to commemorate\nthe first battle for the emancipation of the Filipino people which took place in San Juan del Monte, Province\nof Rizal, between midnight of August 28 and dawn of August 29, 1896;\nWHEREAS, in the Battle of San Juan, commonly, known as the Battle of Pinaglabanan, members of the\npatriotic association called the \"Katipunan\" founded by Andres Bonifacio gave up their lives for the freedom\nof the Philippines; and\nWHEREAS, the perpetuation of the memory of the Battle of Pinaglabanan is the concern not only of any\nlocality or entity but of the entire nation;\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, do hereby reorganize the\nCommission as follows:\nHon. Isidro Rodriguez, Governor of Rizal\nHon. Joseph Ejercito Estrada, Mayor of San Juan, Rizal\nCo-Chairman\nHon. Guillermo B. Guevarra, President of the Spirit of 1896\nExecutive Vice-Chairman\nMrs. Carmen Guerrero Napkil\nJustice Calixto Zaldivar\nArchitect Otillo Arellano\nMrs. Narda N. Camacho\nExecutive-Secretary\nThe Provincial Auditor of the Province of Rizal shall act as Auditor ex officio of the Commission.\nThe Commission is hereby entrusted with the following duties:\n1. Soliciting and collecting voluntary contributions from the public for the purpose of erecting a monument or\nmemorial to the Battle of Pinaglabanan.\n2. Selecting the site of the monument or memorial and taking steps for its acquisition through donation,\nnegotiated purchase or otherwise; and\n3. Directing and supervising the construction and erection of the monument or memorial up to its successful\ntermination.\nAll funds coming into the Commission shall be deposited with the Philippine National Bank in the name of\nthe Commission, and the necessary withdrawals therefrom shall be made only by checks duly signed by the\nChairman or Executive Vice-Chairman and countersigned by the Auditor.\nAll books of accounts kept in connection with the raising of funds and disbursements thereof shall always be\nmade available for audit by the authorized representative of the Auditor General.\nThe Commission shall submit to the President of the Philippines a progress report of its work on the first of\nJuly each year.\nDone in the City of Manila, this 16th day of May, in the year of Our Lord, nineteen hundred and seventy-two."}}],"pack":"ph-p158"};
  FT["PH-H19784"] = {"id":"PH-H19784","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG ANNUAL RATES OF OVERSEAS QUARTERS ALLOWANCES OF FOREIGN","orig":"MALACANANG ANNUAL RATES OF OVERSEAS QUARTERS ALLOWANCES OF FOREIGN"},"level":"law","status":"active","docNumber":"Executive Order No. 394","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00394_1990.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00394_1990.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19784-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"1 of Letter\nof Implementation\nher,eby amended to read\n\"8.1\nT~e following\nbe the basic\ngovernment\n$12,491\n$\n10,345\nHead of Diplomatic\nas Consul-General\n10,482\n8,621\n~3\n17\n~5;\n1\n10\n3\n0:\n1 \"\n\n-3\n7,\n6,\n6,\n5,\n5,\n4,\n4,\n4,\n3,\n3,\n3,\n6,\n5,\n5,\n4,\n4,\n3,\n3,\n3,\n3,\n3,\n3,\n(Counsellor)\n3.\nDepartment\nfrom the lump-sum appropriation\nthe purpose\nYear 1990 programmed\nappropriations\nDepartment\nrepresentatives\namount required\nrespective\nThereafter,\nas may be necessary\nbe included\nto the Congress.\n4.\n1990.\n1 ,\n6\n7\n4\n5\n0\n7\n,4\n2\n9\n9\n,9\n4.\n81\n2\n3\n3\n4\n6\n0\n2'\n2\n2\n4\n5\n281\n63\n9\n6\n66\n5\n7\n4\n6\n1\n9\n6\n4\n0\n.0\n0\n1\n3,\n0,0\n4:\n2\n6\n2\n5'\n5\n5'\n3\n11-\n4\n2\n221\n5666'\""}}],"pack":"ph-p158"};
  FT["PH-H19785"] = {"id":"PH-H19785","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"THE PRESmENT OF THE PBll,IPPINES EXECUTIVE ORDER NO. ~ EST ABLISBING THE LUPONG T AGAP AMA Y AP A INCENTWES AWARDS","orig":"THE PRESmENT OF THE PBll,IPPINES EXECUTIVE ORDER NO. ~ EST ABLISBING THE LUPONG T AGAP AMA Y AP A INCENTWES AWARDS"},"level":"law","status":"active","docNumber":"Executive Order No. 394","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00394_1997.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00394_1997.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19785-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Creation of the Awards.\nThe Lupong Tagapamayapa Incentives\nAwards, herein referred to as the Awards, is hereby created as an annual National Awards\nwith the following categories:\n.\nOutstanding Lupong Tagapamayapa in Highly-Urbanized Cities;\nOutstanding Lupong Tagapamayapa in Component Cities;\nOutstanding Lupong Tagapamayapa in First to Third Class Municipalities;\nPLEASE CITE\n#\nL970121IIIIIIIIIIIII.970121\n\nOutstanding\nMunicipalities.\nTagap amayap a\nAwards aim to:\nObjectn'es of the Awards.\nThe Lupong Tagapamayapa Incentives\nStrengthen the Katarungang Pambarangay as an indigenous conflict\nresolution structure at the grassroots;\nInstitutionalize a system of granting economic benefits and other incentives\nto Lupons which demonstrate exemplary performance~ and\nGenerate greater awareness among, and support from, the various sectors\nof Philippine society on the Katanmgang Pambarangay as a potent vehicle\ntoward social ordering and human development."}},{"id":"PH-H19785-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Constitution of Awards Committe!:'. There is hereby created Lupong\nTagap amayap a Awards committees at the municipal, city, provincial, regional and national\nlevels. The Lupong Tagapamayapa National Awards Committee shall be composed of:\nChairperson\nSecretary, Department of the Interior and Local\nGovernment\nVice-Chairperson\nSecretary, Department of Justice\nPresident, Liga ng mga Barangay\nRepresentative,\nNational Peace and Order Council\nTwo (2) Private Sector/NGO Representatives\nThe Chairman, upon the recommendation of the members of the National Awards\nCommittee, shall select the private sector/NGO representatives.\nThe National Awards Committee may invite one (1) representative from the\nSupreme Court to sit as member of the National Awards Committee.\nThe composition of the National Awards Committee may be replicated at the\nmunicipal, city, provincial and regional levels.\nThe DILG, through the Bureau of Local Government SupelVision, shall provide\ntechnical and secretariat support to the National Awards Committee."}},{"id":"PH-H19785-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Functions of the Lupong Tagapamayapa National Awards Committee.\nThe Committee shall have the following functions:\n2\n\nInitiate and coordinate necessary\nimplementation of the Awards;\nactivities\nsuccessful\nSet the guidelines and criteria for the selection of winners;\nOrganize the\nCommittees;\nRegional, Provincial, City\nSecure funding and additional prizes from ;he private sector;\nSelect from among the regional nominees the national awardees;\nProclaim the National Awardees; and\nPlan and implement appropriate awarding ceremonies.\n,"}},{"id":"PH-H19785-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Funding. For the 1996 Awards, the amount of TWO MILLION PESOS\n(P 2,000,000) for the operations of the National Awards Committee and THREE\nMILLION, EIGHT HUNDRED THOUSAND PESOS (P3,800,000) for cash awards shall\nbe allocated from the President's Social Fund (PSF). Funding for the subsequent years of\nthe Awards shall be incorporated in the annual budget of the Department of the Interior\nand Local Government. Additional funding may also be generated from the member-\nagencies of the Committee, and from the private sector."}},{"id":"PH-H19785-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"Awards and Prizes. The Awards shall be conferred to each national\nawardee, through the local chief executive concerned, in the form of a Presidential Trophy\nand a THREE HUNDRED THOUSAND (P 300,000) development grant.\nregional awardee, FIFTY THOUSAND PESOS (P 50,000) in development grant and a\nspecial plaque shall be awarded."}},{"id":"PH-H19785-A7","no":7,"noLabel":{"en":"SEC 7"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDONE m the City of Manila, this ~\nNmeteen Hundred and Nmety-Seven.\nday of January, in the year of our Lord,\nPMS LIBRARY\n3"}}],"pack":"ph-p158"};
  FT["PH-H19786"] = {"id":"PH-H19786","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE PREFERENTIAL TARIFF RATES ON CERTAIN PRODUCTS UNDER THE ASEAN INDUSTRIAL COOPERATION (AICO) SCHEME, IN FAVOR OF HONDA CARS PHILIPPINES, INC (HONDA)-(COE NOS. HONDA/","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE PREFERENTIAL TARIFF RATES ON CERTAIN PRODUCTS UNDER THE ASEAN INDUSTRIAL COOPERATION (AICO) SCHEME, IN FAVOR OF HONDA CARS PHILIPPINES, INC (HONDA)-(COE NOS. HONDA/"},"level":"law","status":"active","docNumber":"Executive Order No. 394","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00394_2004.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00394_2004.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19786-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The articles specifically listed in Annex \"A\" hereof, as\nclassified under Section 104 of the Tariff and Customs Code of 1978, as\namended, shall be accorded the AICO rate of 3% on parts/components as\nspecified in Column 7 thereof."}},{"id":"PH-H19786-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The AICO rate provided in Annex \"A\" shall be accorded to\nthe AICO entity in Indonesia (PT. Honda Prospect Motor and PT. Honda\nPrecision Parts Manufacturing) and Malaysia (Honda Malaysia Sdn.Bhd.. and\nHonda Autoparts Manufacturing (M) Sdn. Bhd.) upon the effectivity of this\nExecutive Order."}},{"id":"PH-H19786-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"In the event that any subsequent changes are made in the\nbasic (MFN) Philippine rate of duty on any of the articles listed in Annex \"A\" to a\nrate lower than the AICO rate prescribed in Column 7 of Annex \"A\" such articles\nshall automatically be accorded the corresponding reduced rate of duty."}},{"id":"PH-H19786-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Upon the effectivity of this Executive Order, the articles\nspecifically listed in the aforesaid Annex \"A\" which are entered or withdrawn\nfrom warehouses in the Philippines for consumption shall pay the applicable\nAICO preferential tariff rates specified under Section 1 hereof, subject to\nqualification under the Rules of Origin for the CEPT, as evidence by the\nCertificate of Origin- Form \"D'"}},{"id":"PH-H19786-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"This Executive Order shall take effect fifteen (15) days\nfollowing its complete publication in two (2) newspapers of general circulation in\nthe Philippines\nFOMA Halegerm\n29009\n\n3/\nDone in the City of Manila, this31stday of December\nOur Lord, Two Thousand and Four.\nin the year of\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\nPOMà Halagran • 29010\n\n(2)\nARTICLES GRANTED PREFERENTIAL TARIFF UNDER\nTHE APPROVED HONDA AICO SCHEME\n(5)\nVarious Components /Parts,\nBLOCK ASSY ,CYLN\nPassenger Cars HEAD ASSY CYLINDER(AE)\nHEAD SUB ASSY.GYLN\nWHEEL ASSY. SIRG\nPAD COMP STRG WHEEL\nVarious Components /Parts:\nFACE.FR BUMPER\nPassenger Cars FACE,FR BUMPER\nCOVER COMP. INST CTR LWR 77310-59H-1000-X4\nSHAFT ASSY FR.R DRIVE\nSHAFT ASSY FR,L DRIVE\nSHAFT ASS.Y FR, & ORIvE\nSHAFT ASSY FR, L DRIVE\nSHAFT ASSY ER,R DRIVE\nSHAF ASSY FR,L DRIVE\nSHAFT ASSY FR,R DRIVE\nSHAFT ASSY FR,L DRIVE\nINTERIOR LIGHT ASSY\nSOURCE COUNTRY APPLICABLE AICO\n(AICO COMPANY)\nPREFERENTIAL\nHonda Prospect\nMotor and PT\nHonda Precision\n3%\n(Honda Malaysia\nHonda Auto Parts\nManufacturing (M)\n3%"}}],"pack":"ph-p158"};
  FT["PH-H19787"] = {"id":"PH-H19787","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1960/eo_395_1960.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Municipalities of Tungawan and Titay in the Province of Zamboanga Del Sur","orig":"Creating the Municipalities of Tungawan and Titay in the Province of Zamboanga Del Sur"},"level":"law","status":"active","docNumber":"Executive Order No. 395","issuingBody":"President of the Philippines","promulgatedDate":"1960-05-24","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00395_1960_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00395_1960_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19787-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 395, May 24, 1960 ]\nCREATING THE MUNICIPALITIES OF TUNGAWAN AND TITAY IN THE PROVINCE OF\nZAMBOANGA DEL SUR\nUpon the recommendation of the Provincial Board of Zamboanga del Sur and pursuant to the provisions of\nsection sixty-eight of the Revised Administrative Code, there are hereby created in the province of\nZamboanga del Sur two new municipalities to be known as the municipalities of Tungawan and Titay which\nshall consist of certain portions of the territory of the municipality of Ipil, same province, with boundaries\ndescribed hereunder:\n1. The municipality of Tungawan which shall consist of the barrios and sitios of Tungawan, Tigbawang,\nTando, Looc, Tigbucay, Upper Tungawan,, Tigpalay, Cayamcan, Looc Sioral, Taglibong, Tigbongabong,\nBanca-an, Langon, Lihguisan, Gapas-gapas, Dawet, Mangalibod, Buhangin, and other adjacent barrios and\nsitios, with the seat of government at the barrio of Tungawan, and with the following boundaries:\nBeginning at point 1, at the center of the mouth of Tupilac River; thence, due south following the boundary of\nthe marine waters which this municipality shall have pursuant to the provisions of section 2321 of the Revised\nAdministrative Code, to point 2, the intersection of the boundary of the province of Zamboanga del Sur and\nthe City of Zamboanga; thence, due west following the said boundary of the province of Zamboanga del Sur\nand the City of Zamboanga, to point 3, the intersection of the provincial boundaries of Zamboanga del Sur and\nZamboanga del Norte and the City of Zamboanga; thence, due north following the boundary of Zamboanga\ndel Norte and Zamboanga del Sur till it intersects the 7° 40' latitude, point 4; thence, due east following the\n7° 40' latitude with an approximate distance of 6,100 meters to point 5;. the intersection of 7° 40' latitude and\nthe center of Tupilac River; thence, following the course downstream of the Tupilac River to point 1, the point\nof beginning. (Based on the data shown on the sketch plan or map of the proposed muncipality of Tungawan,\nprepared by the Office of the Highway District Engineer, province of Zamboanga del Sur, submitted and on\nfile in this Office; Scale: 1:100,000.)"}}],"pack":"ph-p158"};
  FT["PH-H19788"] = {"id":"PH-H19788","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Executive Order No. 120 Dated February 16, 1968, Creatingthe Metropolitan Area Command","orig":"Amending Executive Order No. 120 Dated February 16, 1968, Creatingthe Metropolitan Area Command"},"level":"law","status":"active","docNumber":"Executive Order No. 395","issuingBody":"President of the Philippines","promulgatedDate":"1972-05-16","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00395_1972_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00395_1972_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19788-A1","no":1,"noLabel":{},"text":{"en":"EXECUTIVE ORDER NO. 395 May 16, 1972\nAMENDING EXECUTIVE ORDER NO. 120 DATED FEBRUARY 16, 1968, CREATING THE\nMETROPOLITAN AREA COMMAND\nExecutive Order No. 120 dated February 16, 1968, creating the Metropolitan Area Command, is hereby\namended so as to include the municipalities of Pateros, Taguig and Muntinlupa, all in the Province of Rizal, as\nwell as the Municipality of Valenzuela, Province of Bulacan, in the area of operations of the Metropolitan\nArea Command.\nDone in the City of Manila, this 16th day of May, in the year of Our Lord, nineteen hundred and seventy-two."}}],"pack":"ph-p158"};
