  FT["PH-H19921"] = {"id":"PH-H19921","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER. No. 419 FIXING THE CEILING PRICES OF COMMODITIES AND FOR OTHER PURPOSES","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER. No. 419 FIXING THE CEILING PRICES OF COMMODITIES AND FOR OTHER PURPOSES"},"level":"law","status":"active","docNumber":"Executive Order No. 419","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00419_1951.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00419_1951.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19921-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The following essential commodities shall\nnot be sold at more than the maximum selling prices for\nimporters, wholesalers and retailers set opposite each\n•FOODSTUFF (IMPORTED)\nUnit Importer's\nRoasted ground coffee:\nSeaport Brand ...\nTable Queen Brand ...... 24/1#\nBaking powder:\nCresent. Brand ....."}},{"id":"PH-H19921-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The ceiling prices hereinabove fixed Include the\n7 per cent sales tax and 1 per cent municipal tax."}},{"id":"PH-H19921-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Order shall take effect five days from the\ndate hereof.\nDone in the City of Manila, this 8th day of March, in\nthe year of Our Lord, nineteen hundred and fifty-one, and\nof the Independence of the Philippines, the fifth.\nELPIDIO QUIRINO\nPresident of the Fhilippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19922"] = {"id":"PH-H19922","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1961/eo_419_1961.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Municipality of Socorro in the Province of Surigao Del Norte.Posted Under Executive Issuances, Executive Orders Tagged Carlos P. Garcia, Executive Issuances, Executive Orders","orig":"Creating the Municipality of Socorro in the Province of Surigao Del Norte.Posted Under Executive Issuances, Executive Orders Tagged Carlos P. Garcia, Executive Issuances, Executive Orders"},"level":"law","status":"active","docNumber":"Executive Order No. 419","issuingBody":"President of the Philippines","promulgatedDate":"1961-02-22","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00419_1961_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00419_1961_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19922-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 419, February 22, 1961 ]\nCREATING THE MUNICIPALITY OF SOCORRO IN THE PROVINCE OF SURIGAO DEL NORTE\nUpon the recommendation of the Provincial Board of Surigao del Norte and pursuant to the provinsions of\nsection sixty-eight of the Revised Administrative Code, there is hereby created in the province of Surigao del\nNorte a municipality to be known as Socorro, to consist of the following barrios and sitios of the\nmunicipalities of Dapa and Numancia, both of the same province:\nFrom the Municipality of Dapa\n2. Nueva Estrella\nFrom the Municipality of Numancia\n1. Pamosaingan\nThe seat of government of the municipality of Socorro shall be at the barrio of Socorro.\nThe territory of the municipality of Socorro shall comprise the whole Island of Bucas Grande where all the\nbarrios and sitios mentioned in the foregoing are situated, including the marine waters which this municipality\nshall have pursuant to Section 2321 of the Revised Administrative Code.\nThe municipalities of Numancio and Dapa shall have their present territories minus the territory comprised in\nthe municipality of Socorro.\nThe municipality of Socorro shall begin to exist upon the appointment and qualification of the mayor,\nvice-mayor an a majority of the councilors thereof and upon the certification by the Secretary of Finance that\nsaid municipality is financially capable of implementing the provisions of the Minimum Wage Law and\nproviding for all the statutory obligations and ordinary essential services of a regular municipality and that the\nmunicipalities of Dapa and Numancia, after the segregation therefrom of the territory comprised in the\nmunicipality of Socorro, can still maintain credibility their respective municipal governments, meet all their\nstatutory and contractual obligations and provide for the essential municipal services.\nDone in the City of Manila, this 22nd day of February in the year of Our Lord, nineteen hundred and sixty-one\nand of the Independence of the Philippines, the fifteenth.\n(SGD.) CARLOS P. GARCIA\nPresident of the Philippines\nBy the President:\n(SGD.) NATALIO P. CASTILLO\nExecutive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H19923"] = {"id":"PH-H19923","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating a Task Force on Human Settlements","orig":"Creating a Task Force on Human Settlements"},"level":"law","status":"active","docNumber":"Executive Order No. 419","issuingBody":"President of the Philippines","promulgatedDate":"1973-09-19","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00419_1973_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00419_1973_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19923-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"It is hereby declared that, for the purpose of promoting national development and enabling Filipinos to\nfully utilize benefits generated by national progress, a competent study be conducted on the nature, policy\nissues and strategies related to a comprehensive and integrative human settlements program in the Philippines."}},{"id":"PH-H19923-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"It is hereby further declared that a national human settlements program be formulated in conjunction\nwith the aforementioned study, to consist of the following:\n(a) Overall framework plan for the nation, which would pinpoint priority areas for human settlement projects,\nand serve as a general scheme for development.\n(b) Project identification, preparation and development of human settlement prototypes, together with\nrecommendations on planning and building design, management and a funding scheme for the human\nsettlements program. This aspect of the plan will draw heavily from the proposed in-depth study to be\nconducted by the Task Force. It will include, but not limited to, the following aspects:\n(1) Metro Manila Bay projects, which will include a development scheme and a zoning plan for the Manila\nBay reclaimed land areas to be allotted for various uses, such as provision for pollution control and the\nspecification of areas where the tourists can swim pollution-free, together with a specification and integration\nof all multi-sectoral requirements.\n(2) Frontier and slum resettlement projects with particular reference to the Tondo reclamation project. It will\ndevise a set of guidelines to be used in determining the necessity for either slum relocation or slum\nimprovement/rehabilitation projects.\n(3) Human settlement areas for integrated area development, which will include, but not be limited to, the\nareas northeast (Marikina-Infanta Road) and south (Laguna-Cavite-Batangas) of Metropolitan Manila.\n(4) Tourist development areas, to include the Looc Estate and other sites to be determined by the Task Force.\n(c) A national housing program for human settlements, specifying therein the organization, funding,\nconstruction, building and local materials development strategies and projects."}},{"id":"PH-H19923-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"To achieve the aforementioned purposes and objectives, there is hereby created a Task Force on\n\nHuman Settlements.\n(a) The Task Force shall be composed of the President of the Development Academy of the Philippines as\nChairman and the following as members:\n(1) The Deputy Director-General, National Economic and Development Authority\n(2) Director, Environmental Planning Center\n(3) Director, Bureau of Lands\n(4) Director, Bureau of Forest Development\n(5) Director, Bureau of Public Works\n(6) Director, Bureau of Public Highways\n(7) General Manager, Metropolitan Waterworks and Sewerage System\n(8) General Manager, People's Homesite and Housing Corporation\n(9) General Manager, National Housing Corporation\n(10) General Manager, Government Service Insurance System\n(11) Administrator, Social Security System\n(12) Chairman, Development Bank of the Philippines\n(13) Undersecretary for Tourism\n(14) Dean, U.P. Institute of Planning\n(15) Commissioner, National Water and Air Pollution Control Commission\n(16) Director, National Manpower and Youth Development Council\n(17) Undersecretary of Social Welfare\n(b) The specific functions, duties and powers of the Task Force area as follows:\n(1) To assess current or proposed human settlement project;\n(2) To set guidelines for the formation of sectoral programs which constitute an integrative human settlement\n(3) To contract with international and local specialists in planning, academic and authorities and institutions,\nresearch and consultancy services in specified areas related to the Philippine human settlement problems as\nmay further the attainment of the objectives of this act;\n(4) To establish and supervise a Task Force working staff which shall keep records, abstracts, collate, and\nsynthesize existing studies on human settlements for the Task Force. The Task Force working staff shall be\ndrawn from the Development Academy of the Philippines. The Executive Director of the Development\nAcademy of the Philippines shall serve as head of the Task Force working staff;\n(5) To train and employ architects, engineers, social scientists, researchers, statisticians, field researchers and\nsuch other persons as may assist the Task Force in fulfilling its functions and duties;\n(6) To determine the qualifications and fix the compensation of its Board, Task Force working group and\nother personnel which it is hereby authorized to hire for administrative operations; and to appoint, discipline\nand remove its employees; Provided, That except as to the technical staff and such other positions as are\nhighly technical, policy-determining or primarily confidential in nature, all positions in the Task Force shall\nbe subject to the coverage of the plans of the Wage and Position Classification Office;\n(7) To adopt rules and procedures for its government;\n(8) To apply for, receive and accept from sources within and without the Philippines, for its own use and not\n\nfor sale, grants or donations of equipment, materials or services. Such grants or donations shall be exempt\nfrom gift taxes and shall be deductible from the net taxable income of the grantor, or donor, and the donee,\nupon certification of the Task Force: Provided, however, That any grant or donation received in accordance\nwith this act shall be disclosed to the President through the annual report;\n(9) To call upon any department, bureau, office, agency or instrumentality of the Government for such\nassistance as it may require in the performance of its duties and functions;\n(10) To promote and publish information, studies and investigations on all aspects of Philippine human\nsettlements; and\n(11) To undertake and perform such other activities as are needful and desirable to promote the attainment of\nthe aforementioned purposes and objectives."}},{"id":"PH-H19923-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"A Board of Consultants is hereby also created to advise the Task Force to be headed by Architect\nAntonio Kayanan."}},{"id":"PH-H19923-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"The Chairman of the Task Force shall:\n(a) Preside over meetings of the Task Force;\n(b) Receive gifts or donations in whatever form and from whatever source;\n(c) Administer, obligate, and disburse appropriations gifts, or donations upon approval by a majority of the\nmembers of the Task Force; and\n(d) Hire and maintain such working group, staff or personnel as may be necessary to carry out the purposes\nand objectives of the Task Force."}},{"id":"PH-H19923-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"The Chairman of the Task Force may constitute continuing ad hoc committees consisting of the\nmembers of the Task Force and such other experts as are necessary to assist the Task Force in the discharge of\nits functions."}},{"id":"PH-H19923-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"The Task Force shall submit its report as soon as possible."}},{"id":"PH-H19923-A8","no":8,"noLabel":{"en":"Sec 8"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 19th day of September, in the year of Our Lord, nineteen hundred and\nseventy-three."}}],"pack":"ph-p158"};
  FT["PH-H19924"] = {"id":"PH-H19924","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":12,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY PROMULGATING THE RULES AND REGULATIONS TO IMPLEMENT THE SUM OF TEN BILLION PESOS FOR THE AID, RELIEF, AND REHABILITATION SERVICES TO PERSONS AND AREAS AFFECTED AND FOR THE SURVEY, REPAIR AND RECONSTRUCTION OF GOVERNMENT INFRASTRUCTURE DAMAGED OR DESTROYED BY THE EARTHQUAKES OF JULY 16, 1990 AND THEIR AFTERSHOCKS","orig":"MALACAÑANG PMS LIBRARY PROMULGATING THE RULES AND REGULATIONS TO IMPLEMENT THE SUM OF TEN BILLION PESOS FOR THE AID, RELIEF, AND REHABILITATION SERVICES TO PERSONS AND AREAS AFFECTED AND FOR THE SURVEY, REPAIR AND RECONSTRUCTION OF GOVERNMENT INFRASTRUCTURE DAMAGED OR DESTROYED BY THE EARTHQUAKES OF JULY 16, 1990 AND THEIR AFTERSHOCKS"},"level":"law","status":"active","docNumber":"Executive Order No. 419","issuingBody":"President of the Philippines","completenessNote":"全文，共 12 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00419_1990.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00419_1990.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H19924-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"This Executive Order hereby promulgates the rules and\nregulations implementing Republic Act No. 6960 which was approved on\nAugust 7, 1990 and became effective on August 9, 1990, the said law having\nbeen published on said date in two (2) national newspapers of general\ncirculation."}},{"id":"PH-H19924-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"As used in this Executive Order, the following definition of\nterms shall govern:\nThe term \"victims\" refers to individuals who sustained\nserious injuries or suffered death in the family as a result of\nthe earthquakes which occurred on 16 July 1990, and their\naftereffects. It shall include individuals whose homes have\nbeen destroyed or rendered uninhabitable.\nThe term \"aid\" or \"relief\" refers to any assistance in the form\nof food, clothing, shelter, money or any other form of\nassistance to the end that life may return to normal at the\nearliest possible time.\nThe term \"repair\" refers to the action of making a facility or\ninfrastructure usable or serviceable even on a partial or\ntemporary basis within a short period of time.\nThe term \"reconstruction\" refers to the action of restoring a\nfacility or infrastructure to the original condition and\nwhenever necessary strengthening or putting in appropriate\nimprovements to make it more resistant to calamities such as\nearthquakes. It shall also include the action of constructing a\n\n- 2 -\nsimilar facility or infrastructure in another location in place\nof the damaged facility or infrastructure.\nThe \"Presidential Task Force on Rehabilitation\" refers to the\nTask Force created pursuant to Memorandum Order No. 311:\ndated 1 August 1990."}},{"id":"PH-H19924-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"The projects that will be funded by the appropriation\ncontained in Republic Act No, 6960 must contribute to any or all of the\nfollowing objectives:\nPreservation of life;\nRestoration of home; and,\nResumption of production.\nThe following agencies shall be responsible for the identification of the\nprojects within their respective jurisdiction and whenever necessary, in\nconsultation with local government units, viz.:\nDepartment of Public Works and Highways - for Roads,\nHighways and Bridges, Flood Control and Seawalls, Water\nSupply (level I), and Other Public Buildings and Facilities;\nPhilippine National Railways - for Railways;\nPhilippine Ports Authority - for Ports;\nAir Transportation Office/Department of Transportation and\nCommunications - for Airports;\nPostal Services Office/Department of Transportation and\nCommunications - for Post Offices;\nTelecommunications Office/Department of Transportation\nand Communications - for Telecommunication Facilities;\nNational Power Corporation - for Power Facilities;\nNational Electrification Administration - for Electrification\nFacilities;\nNational Irrigation Administration - for Irrigation Facilities;\n\n- 3 -\nDepartment of Education, Culture and Sports - for\nSchoolbuildings;\nDepartment of Health - for Hospitals/Health Centers and\nPublic Health Programs;\nNational Housing Authority - for Housing Facilities;\nDepartier - National Defense - for Defense Facilities;\nExport Processing Zone Authority - for Export Processing\nZone Facilities;\n0)\nDepartment of Social Welfare and Development - for Social\nWelfare Projects;\nLocal Water and Utilities Administration - for Water Supply\nFacilities (Levels Il and III); and,\nDepartments of Agriculture, Agrarian Reform, Environment\nand Natural Resources, Labor and Employment and Trade\nand Industry, Education, Culture and Sports, Local\nGovernment, Tourism, and the National Livelihood Support\nFund - for Livelihood and Emergency Employment\nAssistance Projects.\nThe above enumerated agencies shall also be responsible for the\nimplementation of the projects except those projects determined by the\nPresidential Task Force to be more appropriately implemented by local\ngovernment units."}},{"id":"PH-H19924-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"In general, the repair or reconstruction of infrastructure\nprojects shall be prioritized by using the following factors:\n6)\nEconomic importance of the facility, with preference to\nfacilities which significantly contribute to or support\nproduction and distribution of essential goods in substantial\nvolumes over large geographical areas;\nSocial significance of the facility, with emphasis on facilities\nwhich provide basic shelter, health, and education services\naffecting large/depressed communities;\nStructural condition of the facility, with attention to facilities\nwhich are structurally unsafe for use or prone to further\n\n4:\nFeasibility of the repair / reconstruction works, with emphasis\non those which can be started quickly and be completed\nwithin a relatively short period.\nOn the basis of the above enumerated factors, the following general\ntypes of infrastructure shall be given priority:\nImmediate opening and rehabilitation of blocked or hardly\npassable major interregional/interprovincial and secondary\nintermunicipal transport routes in order to restore the major\nmovements of goods, services and people;\nRestoration of power, water, irrigation, flood control and\ncommunication services;\nRehabilitation of social infrastructure such as schools,\nhospitals and public markets with structural damage and\ntemporary shelters for homeless families."}},{"id":"PH-H19924-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"The levels of repair and reconstruction work shall be as\nThis consists of basic emergency repair not\nnecessarily to restore in the original condition but merely for\nthe purpose of quickly making the facility or infrastructure\nusable or serviceable even on a partial or temporary basis, e.g.\ntemporary bailey bridge on one-way pilot road. These\nprojects can generally be completed within a short period of\ntime, i.e. one or two months.\nLevel II: This consists of the reconstruction or restoration to\nthe original condition of the facility or infrastructure and\nwhenever necessary includes strengthening, improvement\nor relocation of the facility to make it resistant to natural\ncalamities like earthquake e.g. removal of slides,\nreconstruction of damaged embankment and pavement, or\nslope protection works.\nThese projects are normally\ncompleted between the period of six (6) months to two (2)\nLevel IlI: This consists of the reconstruction of damaged\ninfrastructure and facilities and development of new facilities\nto minimize the disruption of infrastructure services in case\nnatural calamities such as earthquake should occur in the\n\n- 5 -\nfuture e.g. new alternative route, new towns, relocated\nproduction areas and reconfigured transport networks. These\nprojects are normally completed between the period of two\n(2) years to five (5) years.\nThe projects that will be implemented and funded pursuant to the\nprovisions of Republic Act No. 6960 will normally be those falling under\nLevels I and II. However, projects falling under Level IlI may also be\nimplemented and funded if they are found to be extremely urgent and\nnecessary, after due consultation with concerned sectors and officials of the\nnational and local government."}},{"id":"PH-H19924-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"The Presidential Task Force shall undertake the identification,\nprioritization, programming of projects and fund allocation within three (3)\nmonths from 9 August 1990. For this purpose, the procedure shall be as\nEach concerned agency mentioned in Section 3 hereof shall\nidentify the earthquake-damaged infrastructure facilities\nunder its responsibility, and define the extent and impact of\nthe damage thereto and submit the same to the Presidential\nTask Force for consideration and approval. All possible\nsources of information shall be used, including its own\nagency reports, as well as those of other concerned national\nagencies and officials, local government units, non-\ngovernmental organization, media and the general public.\nThe agency shall then determine the repair and\nreconstruction works required on the damaged infrastructure\nusing the levels defined in Section 5 hereof, prepare an\nestimate of their cost and implementation periods, and\nprioritize them based on the criteria enumerated in Section 4\nof this Executive Order.\nThe prioritized schedule be\nsubmitted to the Presidential Task Force for consideration\nand approval.\nThe agency shall thereafter prepare a preliminary program\nfor the repair and reconstruction of the damaged\ninfrastructure, which shall contain the following\ninformation:\n1. List of projects and their locations;\n\n- 6 -\n2. Description of extent and impact of damage for each\n3. Description of work to be done for each project;\n4\nEstimated cost per project at each level of action;\n5.\nImplementation schedule per project, and\napproximate quarterly cash flow.\nImplementing agency must provide appropriate information\nto and consult with concerned local and national officials\nfrom the area on rehabilitation projects to be implemented\nThe agency program shall be submitted by the Presidential\nTask Force to the President for final approval."}},{"id":"PH-H19924-A7","no":7,"noLabel":{"en":"SEC 7"},"text":{"en":"The procurement and implementation procedures shall be as\nEncineering Services\nPrior to project implementation, the concerned agency shall\nprovide appropriate engineering preparations:\nWhenever deemed necessary, the agency may engage in each\naffected area, project or cluster of projects, in-house consultants\nfrom reputable firms to assist and advise it.\nActual Project Implementation\nThe implementing agencies or local government units\nresponsible for the actual repair and reconstruction of the\ninfrastructure facilities shall determine the most appropriate mode\nof implementing each project in the program. For this purpose, the\nagencies or local government units may adopt any of the following\noptions, whichever is appropriate:\n1. Administration or force account shall generally be\nadopted as a mode of project implementation for Level I\nor when the scope is difficult to quantify for contracting\n\n7\n2.\npurposes and it is within the implementing capability of\nthe agency or local government unit.\nNegotiated contract may be adopted as a mode of project\nimplementation for Levels I and I when the works are\nurgent and beyond the force account capability of the\nconcerned agency or local government unit especially\nthose involving structural damage, imminent danger to\nlife and property, significant social and economic losses\nand where time is of the essence in project\nimplementation. Negotiated contracts may be entered\ninto not later than six, (6) months from the effectivity of\nRepublic Act No. 6960 and in accordance with Section 5\n3\nContract after public bidding may be adopted as a mode of\nproject implementation for Levels I and III projects\nwhich are less urgent and cannot be completed within one\nyear. As much as possible the provisions of Presidential\nDecree No. 1594 and its implementing rules and\nregulations, as amended, shall be followed. However, in\nso far as advertisement for the project, prequalification of\ncontractors and award of contracts are concerned, the\nimplementing agencies or local government units may\nshorten the requirements for notice and evaluation\nAll funds covering contracts entered into under Republic Act\nNo. 6960 and this Executive Order shall be obligated within one (1)\nyear from the effectivity of the said Act."}},{"id":"PH-H19924-A8","no":8,"noLabel":{"en":"SEC 8"},"text":{"en":"The supervision of the repair and reconstruction works shall\nbe performed by the concerned implementing agency or local government\nunit, through its own units and/or through consultants, in accordance with\nexisting technical standards and procedures.\nThe implementing agency or local government unit shall give\npreference to the residents of the affected areas, especially the victims, in the\nhiring or employment of the workers required in the repair and\nreconstruction of damaged infrastructure under the approved program."}},{"id":"PH-H19924-A9","no":9,"noLabel":{"en":"SEC 9"},"text":{"en":"The assistance to earthquake victims shall primarily address\nthe immediate concern of survival and normalization of their lives. In this\n\n- 8 -\nregard, the assistance shall encompass the basic needs for food, clothing,\nshelter and emergency employment.\nAssistance for the survival of earthquake victims may take any of the\nfollowing forms:\nCommunal meal service;\nSubsidized source of foodstuffs and clothing;\nHealth services; or\nMoney to cover medical and funeral expenses.\nAssistance for the normalization of the lives of the earthquake victims\nmay take any or all of the following forms:\nResettlement assistance;\nEmployment placement assistance;\nSchool placement assistance;\nLoan or grant for livelihood projects; or\nDeferment or restructuring of some obligations such as real\nestate taxes, salary loans and the like, when so warranted or\nauthorized."}},{"id":"PH-H19924-A10","no":10,"noLabel":{"en":"SEC 10"},"text":{"en":"The Department of Social Welfare and Development shall be\nprimarily responsible for identifying the persons eligible for assistance\nmentioned in Section 9 hereof and the nature of assistance needed. The\nassistance shall be extended by the concerned agencies in coordination with\nAll concerned agencies shall submit to the President, through\nthe Presidential Task Force on Rehabilitation, for consolidation and\ntransmittal to Congress, a quarterly report on the fund allocated for aid or\nrelief services and funds allocated for the repair and reconstruction of vital\nand essential infrastructure projects, the list of such infrastructure which\nshall be financed, the list of names of approved individual beneficiaries, the\npurpose for which the appropriations was utilized and the accomplishments\nfor the expanded appropriations, including the percentage of completion of\n\n- 9 -\nrepair and reconstruction projects, as well as an evaluation of the\neffectiveness of the delivery system of relief services."}},{"id":"PH-H19924-A12","no":12,"noLabel":{"en":"SEC 12"},"text":{"en":"The Department of Justice shall, upon a complaint or upon\nits own initiative, investigate and prosecute persons or entities charged with\nviolations of pertinent provisions of penal laws, rules and regulations in\nrelation to the provisions of Republic Act No. 6960 particularly on the\nutilization and application of the funds provided therein.\nThe Department of Justice is hereby authorized to avail itself of the\nservices of all law enforcement agencies as may be necessary in the\nperformance of its tasks."}},{"id":"PH-H19924-A13","no":13,"noLabel":{"en":"SEC 13"},"text":{"en":"This Executive Order shall take effect immediately upon its\npublication in two (2) national newspapers of general circulation.\nDONE in the City of Manila, this 22nd day of August, in the year of Our\nLord, nineteen hundred and ninety.\nkaragon be legacier\nBy the President:\nExecutive Secretary"}}],"pack":"ph-p158"};
