  FT["PH-H20103"] = {"id":"PH-H20103","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1961/eo_451_1961.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Directing Municipal and City Treasurers to Issue Certificates of Indigency Pursuant to Republic Act No. 747, as Implemented By Executive Order No. 578, Dated March 24, 1953Posted Under Executive Issuances, Executive Orders, Laws and Issuances Tagged Carlos P. Garcia, Executive Issuances, Executive Orders","orig":"Directing Municipal and City Treasurers to Issue Certificates of Indigency Pursuant to Republic Act No. 747, as Implemented By Executive Order No. 578, Dated March 24, 1953Posted Under Executive Issuances, Executive Orders, Laws and Issuances Tagged Carlos P. Garcia, Executive Issuances, Executive Orders"},"level":"law","status":"active","docNumber":"Executive Order No. 451","issuingBody":"President of the Philippines","promulgatedDate":"1961-11-20","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00451_1961_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00451_1961_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20103-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 451, November 20, 1961 ]\nDIRECTING MUNICIPAL AND CITY TREASURERS TO ISSUE CERTIFICATES OF INDIGENCY\nPURSUANT TO REPUBLIC ACT NO. 747, AS IMPLEMENTED BY EXECUTIVE ORDER NO. 578,\nDATED MARCH 24, 1953\nWHEREAS, the medically indigent population of the country is the primary concern of the government;\nWHEREAS, government hospitals, charity clinics, health centers, and dispensaries are established primarily\nfor the treatment and care of the poor; and\nWHEREAS, the socio-economic investigation of patients being conducted by the Department of Health,\nthrough its operating field health units, to determine their financial condition can be done more effectively\nwith the cooperation and assistance of municipal and city treasurers;\nNOW, THEREFORE, by virtue of the powers vested in me by law, I, Carlos P. Garcia, President of the\nPhilippines, do hereby order all municipal and city treasurers to issue certificates of indecency, based on the\nclassification made in Republic Act No. 747, as implemented by Executive Order No. 578, dated March 24,\n1953, in favor of patients who may wish to take advantage of the benefits thereof. For this purpose, municipal\nand city treasurers are hereby authorized to enlist the assistance of other government agencies to determine\naccurately the income of patients for their proper classification under said Act, as implemented by Executive\nDone in the City of Manila, this 20th day of November, in the year of Our Lord, nineteen hundred and\nsixty-one, and of the Independence of the Philippines, the sixteenth.\n(SGD.) CARLOS P. GARCIA\nPresident of the Philippines\nBy the President:\n(SGD.) EDILBERTO B. GALLARES\nAssistant Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H20104"] = {"id":"PH-H20104","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Excluding Cement From the List of Export Products Subject to Duty Provided for Under Republic Act No. 1937, Otherwise Known as the \"Tariff and Customs Code\", as Amended","orig":"Excluding Cement From the List of Export Products Subject to Duty Provided for Under Republic Act No. 1937, Otherwise Known as the \"Tariff and Customs Code\", as Amended"},"level":"law","status":"active","docNumber":"Executive Order No. 451","issuingBody":"President of the Philippines","promulgatedDate":"1975-06-02","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00451_1975_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00451_1975_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20104-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Cement is hereby excluded from the list of export products subject to duty as provided under Section\n515, Title III of the Tariff and Customs Code, as amended."}},{"id":"PH-H20104-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 2nd day of June, in the year of Our Lord, nineteen hundred and seventy-five."}}],"pack":"ph-p158"};
  FT["PH-H20105"] = {"id":"PH-H20105","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALJ.\\CANANG BY THE PRESIDENT OF THE PHILIPPINES FURTHER THE DURATION OF OPERATION PRESIDENTIAL EAST PREPAREDNESS COMMITTEE (PMEPC) to DECEMBER 31, 2005","orig":"MALJ.\\CANANG BY THE PRESIDENT OF THE PHILIPPINES FURTHER THE DURATION OF OPERATION PRESIDENTIAL EAST PREPAREDNESS COMMITTEE (PMEPC) to DECEMBER 31, 2005"},"level":"law","status":"active","docNumber":"Executive Order No. 451","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00451_2005.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00451_2005.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20105-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Funding\nCommittee shall be provided an additional\nallocation\nof FOUR MILLION\nadministrative\nand operational expenses to be provided by the Office of the\nAdditional\nrequirements\nmay be needed by the\nCommittee shall be sourced out by the Department of Budget and Management\nfrom available funds of the .concerned agencies forming part of the PMEPC,\nsubject to the usual government accounting and auditing rules and regulations.\nother rules, regulations and issuances or parts\nthereof which are inconsisten~ with this Executive Q'rder are hereby repealed or\nmodified accordingly."}},{"id":"PH-H20105-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Effectivity\n-This Order shall take effect immediately.\nDONE in the City of Manila this :?fttl\"day of July\nof our Lord, Two Thousand and Five.\n~llllllllllllllllllljllllllllllll\nBy the. President:\nEDUARDO R. ERMITA\nExecutive Secretarv"}}],"pack":"ph-p158"};
