  FT["PH-H20155"] = {"id":"PH-H20155","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"NOW, THEREFORE, I, GLORIA MACAPAGAL-ARROYO,","orig":"NOW, THEREFORE, I, GLORIA MACAPAGAL-ARROYO,"},"level":"law","status":"active","docNumber":"Executive Order No. 460","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00460_2005.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00460_2005.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20155-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Section 5 of Executive Order No. 119 (s. 2002) is hereby\namended to read as follows:\n\"Section 5. Assumption\nof Rural Electrification Loans. -To\nensure that\nthe implementation\nof the Program is in accordance with law which\nrequires that only Rural Electrification Loans shall be assumed by PSALM,\nand to further\nconsumer welfare,\nthe assumption\nElectrification\nLoans shall be subject\nconditions:\ncommensurate\nwith the resulting savings due to the removal of the\namortization payments on the Rural Electrification Loan/s.\nPOMA Hologrlm N 32139\n\nNothing in this Section shall mean that the effectivity date of the loan\ncondonation will commence on the day ERC issues to the ECs Provisional\nAuthority to reduce rates, such loan condonation being effective on June\n26, 2001 as provided for in the EPlRA and assumption of which loan by\nPSALM having commenced on said date.\""}},{"id":"PH-H20155-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Section 7 of Executive Order No. 119 (s. 2002) is hereby\namended to read as follows:\nAssumption and Payment by PSALM of Rural Electrification\nLoans. -Pursuant\nto Section 60 of EPlRA, PSALM shall assume all Rural\nElectrification Loans upon the effectivity thereof.\nThe assumption of the\nRural Electrification Loans by PSALM shall retroact from the effectivity of\nThereafter,\nPSALM and NEA or other creditor government agencies shall\ninto contracts\nagreements,\nnecessary and proper,\nundertake the payment of the assumed Rural Electrification Loans through\nan amortization schedule to be agreed upon between PSALM on the one\nhand, and NEA or other creditor government agencies, on the other.\nWhere necessary, such contracts and/or agreements may include mutual\nstipulations on the modification and/or amendments of existing contracts\nof mortgage and other security between ECs and NEA or other creditor\ngovernment agencies."}},{"id":"PH-H20155-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Repealing\nexecutive issuances, orders, rules\nand regulations or parts thereof inconsistent with the provisions of this Executive\nOrder are hereby repealed or modified accordingly."}},{"id":"PH-H20155-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Effectivity. -\nimmediately.\nThis Executive Order shall take effect\nDONE in the City of Manila, this 2rrl day of September in the Year of ourLord,\nTwo Thousand and Five.\n/\nEDUARDO R. ERMITA\nExecutive Secreta ry\n2"}}],"pack":"ph-p158"};
  FT["PH-H20156"] = {"id":"PH-H20156","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDING EXECUTIVE ORDERS NUMBERED FOUR HUNDRED FORTY-SEVEN, FOUR HUNDRED FORTY-NINE, FOUR HUNDRED FIFTY-ONE AND FOUR HUNDRED FIFTY-TWO.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDING EXECUTIVE ORDERS NUMBERED FOUR HUNDRED FORTY-SEVEN, FOUR HUNDRED FORTY-NINE, FOUR HUNDRED FIFTY-ONE AND FOUR HUNDRED FIFTY-TWO."},"level":"law","status":"active","docNumber":"Executive Order No. 461","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00461_1951.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00461_1951.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20156-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Section 1 of Executive Order No. 447, dated\nJune 9, 1951, is hereby amended by fixing the retailer's\nprice of Mello Cup Roasted Ground Coffee at P3.28."}},{"id":"PH-H20156-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":". Section 1 of Executive Order. No. 449, dated\nJune 9, 1951, is hereby amended by fixing the retailer's\nprice of \"Peco\", Dixon Lead Pencil at P0.06; of \"Zero\",\nEberhard Faber Pencil at F0.06; of Manila Paper, size\n36\" by 48\" _80 Ibs.480 sheets at P0.06."}},{"id":"PH-H20156-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Section 1 of Executive Order No. 451, dated June\n9, 1951, is hereby amended by fixing the retailer's price of\nHighway Type Truck & Bus Tires, size 10.00-22, 12-ply\nrating at P388 and changing the ply rating of Farm\nTractor Tires Ribbed Front. Tires, size 5.50-16, from"}},{"id":"PH-H20156-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Section 1 of Executive Order No. 452, dated\nJune 9, 1951, is hereby amended by fixing the wholesaler's\nprice and the retailer's price of Number Stories--Book\nTwo at P3.45 and P3.98, respectively.\nSEc.. 5. This Order shall take effect as of June 9, 1951.\n\nDone in the City of Manila, this 27th day of July, in\nthe year of Our Lord, nineteen hundred and fifty-one, and\nof the Independence of the Philippines, the sixth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nMARCIANO ROQUE\nActing Assistant Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H20157"] = {"id":"PH-H20157","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1961/eo_461_1961.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the Municipality of Matalam in the Province of Cotabatoposted Under Executive Issuances, Executive Orders, Laws and Issuances Tagged Carlos P. Garcia, Executive Issuances, Executive Orders","orig":"Creating the Municipality of Matalam in the Province of Cotabatoposted Under Executive Issuances, Executive Orders, Laws and Issuances Tagged Carlos P. Garcia, Executive Issuances, Executive Orders"},"level":"law","status":"active","docNumber":"Executive Order No. 461","issuingBody":"President of the Philippines","promulgatedDate":"1961-12-29","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00461_1961_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00461_1961_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20157-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 461, December 29, 1961 ]\nCREATING THE MUNICIPALITY OF MATALAM IN THE PROVINCE OF COTABATO\nUpon the recommendation of the Provincial Board of Cotabato and pursuant to the provisions of section\nsixty-eight of the Revised Administrative Code, there is hereby created in the province of Cotabato a\nmunicipality to be known as Matalam to consist of the following barrios and sitios of the municipalities of\nKidapawan, Kabacan, and M’lang, all of the same province:\nFrom the Municipality of Kidapawan\n14. Natutungan\n4. Datu Mantawil\nFrom the Municipality of Kabacan\nFrom the Municipality of M’lang\n3. New Bugasong\nwith the seat of government at the barrio of Kilada.\nThe municipality of Matalam as herein organized shall have the following boundaries:\nBeginning at the intersection of Malamote and Pandan Creeks on the original boundary of the M’lang and\nKabacan municipalities marked Point 1, on the map; thence, in a northeasterly direction following the\nTaculen-Malamote Road to its junction on the National Highway, marked Point 2; thence, in a straight line in\na northeasterly direction till it intersects the old Kabacan-Kidapawan boundary on the Kabacan River near the\nsitio of Minanga, marked Point 3; thence, following the said old boundary of Kabacan and Kidapawan till it\nreaches the Punlangi River, marked Point 4; thence, following the Pulangi River till it reaches the junction\nwith the Arakan River, marked Point 5; thence, following the Arakan River to its source on the Tuail\nMountain Range, market Point 6; thence, it goes directly south to a point on the Tuail River near the sitio of\nRoxas, marked Point 7; thence, following the Tuail River downstream to its junction with the Kabacan River,\nmarked Point 8; thence, going southwest in a straight line to the junction of the Magpet and Marbel Rivers,\nmarked Point 9; thence, in a straight line direct to the junction of the Patadon-Estado Road and the\nCotabato-Davao Road, marked Point 10; thence, in a straight line in a southerly direction till it intersects the\nold boundary of M’lang and Kidapawan municipalities, marked Point 11; thence, in a straight line in a\nwesterly direction to the intersection of the Malamote and Pandan Creeks, marked Point 1, the point of\nbeginning. (Based on the description in Resolution No. 598, dated November 27, 1961, of the Provincial\nBoard of Cotabato, of the sketch plan or map prepared by the Office of the District Engineer of Cotabato, on\nfile in this Office, Scale: 1:250,000)"}}],"pack":"ph-p158"};
  FT["PH-H20158"] = {"id":"PH-H20158","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Certifying that the Production of Sodium Tripoly- Phosphate as a Preferred Pioneer Industry, Shall Be Entitled to Post-Operative Tariff Protection","orig":"Certifying that the Production of Sodium Tripoly- Phosphate as a Preferred Pioneer Industry, Shall Be Entitled to Post-Operative Tariff Protection"},"level":"law","status":"active","docNumber":"Executive Order No. 461","issuingBody":"President of the Philippines","promulgatedDate":"1976-02-02","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00461_1976_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00461_1976_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20158-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The articles specifically listed hereunder as classified under Section 104 of Republic Act Number\nNineteen Thirty-Seven as amended by Presidential Decree Number Thirty Four shall pay the following rates\nof import duty:\nTariff Heading No.\nDescription of Articles\nRate of Duty\n28.40\nPhosphates, hypophosphates and phosphates\nA. Articles not included in Subheading B\nB. Sodium tripolyphosphates"}},{"id":"PH-H20158-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Upon the expiration of thirty (30) days from the issuance of this Order, all the above described articles\nentered or withdrawn from warehouses in the Philippines for consumption shall be subject to the rates of\nimported duty herein above-prescribed.\nDone in the City of Manila, this 2nd day of February, in the year of Our Lord, nineteen hundred and\nseventy-six."}}],"pack":"ph-p158"};
