  FT["PH-H20239"] = {"id":"PH-H20239","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES IMPLEMENTING REPUBLIC ACT NUMBERED SIX HUNDRED THIRTY-TWO, ENTITLED \"AN ACT CREATING THE PHILIPPINE SUCAR INSTI TUTE, PRESCRIBING ITS POWERS, FUNCTIONS AND DUTIES, AND PROVIDING FOR THE RAIS- ING OF THE NECESSARY FUNDS FOR ITS","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES IMPLEMENTING REPUBLIC ACT NUMBERED SIX HUNDRED THIRTY-TWO, ENTITLED \"AN ACT CREATING THE PHILIPPINE SUCAR INSTI TUTE, PRESCRIBING ITS POWERS, FUNCTIONS AND DUTIES, AND PROVIDING FOR THE RAIS- ING OF THE NECESSARY FUNDS FOR ITS"},"level":"law","status":"active","docNumber":"Executive Order No. 478","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00478_1951.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00478_1951.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20239-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The tax on annual sugar production levied\nunder Section 15 of Republic Act No. 632 shall be collected\nby the Collector of Internal Revenue under such rules\nand regulations as may be prescribed by the Secretary\nof Finance. No sugar quedan and/or warehouse receipt\nshall be released to sugar cane planters and sugar centrals,\nunless the said tax is first paid.\nSEc. 2. This Order shall take effect immediately.\nDone in the City of Manila, this 25th day of October,\nin the year of Our Lord, nineteen hundred and fifty-one,\nand of the Independence of the Philippines, the sixth.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nMARCIANO ROQUE\nActing Assistant Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H20240"] = {"id":"PH-H20240","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Extending the Term of the Presidential Committee to Study Government Corporations Created Under Executive Order No. 464, Series of 1976","orig":"Extending the Term of the Presidential Committee to Study Government Corporations Created Under Executive Order No. 464, Series of 1976"},"level":"law","status":"active","docNumber":"Executive Order No. 478","issuingBody":"President of the Philippines","promulgatedDate":"1976-12-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00478_1976_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00478_1976_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20240-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Committee is directed to submit its report and recommendations on or before June 30, 1977 and to\noversee the installation and implementation of such of its recommendations as may be approved and adopted\nby the appropriate authorities for the period covering July 1, 1977 to December 31, 1977."}},{"id":"PH-H20240-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"An appropriation of P600,000 is authorized for the incurrence of operating and necessary expenditures\nin connection with its study of government corporations.\nThis Order shall take effect immediately.\nDone in the City of Manila, this 27th day of December, in the year of Our Lord, nineteen hundred and\nseventy-six."}}],"pack":"ph-p158"};
  FT["PH-H20241"] = {"id":"PH-H20241","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Imposing special duties on crude oil and oil products under","orig":"Imposing special duties on crude oil and oil products under"},"level":"law","status":"active","docNumber":"Executive Order No. 478","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00478_1991_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00478_1991_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20241-A104","no":104,"noLabel":{"en":"Section 104"},"text":{"en":"of the Tariff and Customs Code of the Philippines, as amended\nSigned 1991-08-23  |  Source: LawPhil (source has HTML full text only)  |\nMALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 478, August 23, 1991 ]\nIMPOSING SPECIAL DUTIES ON CRUDE OIL AND OIL PRODUCTS UNDER SECTION 104 OF THE\nTARIFF AND CUSTOMS CODE OF THE PHILIPPINES, AS AMENDED.\nPursuant to the powers vested in me under Sections 104 and 401 of the Tariff and Customs Code of the\nPhilippines, as amended, I, CORAZON C. AQUINO, President of the Philippines, do hereby order:\nSection 1. A special duty of P0.95 per liter or P151.05 per barrel on imported crude oil falling under Hdg.\nNo. 27.09 and P1.00 per liter on imported oil products falling under Hdg. Nos. 27.10 and 27.11 of Section 104\nof the Tariff and Customs Code of the Philippines, as amended, and listed in Annex “A” hereof shall be levied\nin addition to the existing ad valorem rates imposed on these articles.\nSection 2. Upon the effectivity of this Executive Order, the articles listed in Annex “A” hereof when\nentered or withdrawn from warehouses in the Philippines for consumption shall be subject to the additional\nrates of duty prescribed therein.\nSection 3. This Executive Order shall take effect after thirty (30) days following its publication in two (2)\nnational newspaper of general circulation in the Philippines.\nDONE in the City of Manila, this 23rd day of August, in the year of Our Lord, nineteen hundred and\nCORAZON C. AQUINO\nPresident of the Philippines\nBy the President:\nFRANKLIN M. DRILON\nExecutive Secretary\nNOMENCLATURE AND SPECIAL DUTY ON CRUDE OIL AND OIL PRODUCTS\nDescription\nDate of Duty\n2709.00 00\nPetroleum oils and oils obtained from bituminous minerals, crude.\n10% ad val. plus P0.95/liter or P151.05/barrel\n2710.00 00\nPetroleum oils and oils obtained from bituminous minerals, other then crude; preparations not elsewhere\nspecified or included, containing by weight 70% of more of petroleum oils or of oils obtained from\nbituminous minerals, these oils being the basic constituents of the preparations.\n\n2710.00 10\n2710.00 20\n- - - Lubricating oil, including lubricating oil basestock when imported with special authorization by the\nEnergy Regulatory Board\n10% ad val. plus P1.00/liter\n2710.00 30\n- - - Fuel oils, naptha, low aromatic solvents:\n2710.00 31\n2710.00 32\n- - - - Naptha, when imported with special authorization by the Energy Regulatory Board\n2710.00 33\n- - - - Other naptha\n10% ad val. plus P1.00/liter\n2710.00 34\n- - - - Low aromatic solvents, when imported with special authorization by the Energy Regulatory Board.\n2710.00 35\n- - - - Other low aromatic solvents\n10% ad val. plus P1.00/liter\n2710.00 40\n2710.00 50\n- - - Gas oils (including diesel oil), kerosene (including kerosene type jet fuel) and motor gasoline; other heavy\n2710.00 51\n- - - - Gas oils (including diesel oil), when imported with special authorization by the Energy Regulatory\n2710.00 59\n20% ad val. plus P1.00/liter\n2710.00 90\n- - - Other oils and preparations\n\n20% ad val. plus P1.00/liter\n27.11\nPetroleum gases and other gaseous hydrocarbons\n2711.11 00\n- - Natural gas\n10% ad val. plus P1.00/liter\n2711.12 00\n10% ad val. plus P1.00/liter\n2711.13 00\n10% ad val. plus P1.00/liter\n2711.14 00\n- - Ethylene, propylene butylenes and butadiene\n10% ad val. plus P1.00/liter\n2711.19 00\n- In gaseous state:\n10% ad val. plus P1.00/liter\n2711.21 00\n- - Natural gas\n10% ad val. plus P1.00/liter\n2711.29 00\n10% ad val. plus P1.00/liter"}}],"pack":"ph-p158"};
  FT["PH-H20242"] = {"id":"PH-H20242","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO.","orig":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 478","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00478_1998.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00478_1998.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20242-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"of Republic\nAct No. 8178, otherwise\nknown as the\n\"Agricultural\nTariffication\nAct\", provides that in case of shortages\nor abnormal\nin agricultural\n'vA/hose quantitative\nrestrictions\nare lifted under\nthe said law, the President\nmay propose revisions,\nmodifications\nor adjustments\nMAV to Congress\nVJhich has to act within fifteen days from receipt of the proposal,\nthe same shall be deemed approved;\nWHEREAS. a proposal was submitted by the President to Congress on\nFebruary 6. 1998 to increase the 1998 MAV for coffee beans by 5.000 rl/1T from\nWHEREAS, the Congress did not act on the aforesaid proposal within the\nprescribed period.\nNOW, THEREFORE,\nI, FIDEL V. RAMOS,President\nof the Philippines\nand pursuant to the provisions of Republic Act No. 81'78. do hereby order:\nThe Minimum Access Volume (MAV) for coffee beans in the\nauthorized 1997 MAV of 1,060 r:1etric tons (MT) is hereby increased to 6,060\nmetric tons (MT); Provided. That any unavailed balance at the end of 1398 shaii\nnot be carried over to 1999.\nThe MAV Management Committee is hereby authorized to\nallocate volume importation to qualified importers of coffee beans pursuant to the\nRules and Regulations for the Implementation of Agricultural MAVs\n~\n\n3.\nThis Executive Order shall take effect immediately.\nDone in the City of Manila, this 22E-.Q.\nday of May, in the year of Our Lord,\nnineteen hundred and ninety-eight.\nBy the President:\nPMS LfBRARY"}}],"pack":"ph-p158"};
  FT["PH-H20243"] = {"id":"PH-H20243","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THf PHILIPPINES","orig":"BY THE PRESIDENT OF THf PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 478","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00478_2005.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00478_2005.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20243-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The Bases Conversion and Development Authority (BCDA)\nand all its subsidiaries and attached agencies il1c1uding Subic Bay Metropolitan\nAuthority (SBMA).. are hereby placed under the policy supervision; ,of. the\n...,\nDepartment of Trade and Indu'stry (DTI).\n~~/"}},{"id":"PH-H20243-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"The Secretary of DTI shall recommend to the President nominees\nfor the position of Chairman, President and r~embers of the Board of BCDA and\n'"}},{"id":"PH-H20243-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"AU orders, issuances,\nrules and regulations or parts thereof\ninconsistent with this Executive Order are hereby repealed and modified\naccordingly.\n...\"\n/\nSEC. ,4. This E)(ecutiv~ Order shall take effect immedjately upon\npublication in a newspaper\nof general circulation.\nDONE in the City of Marlila, this 19thday of December in the..year of Our.ord,Tv.fo\nThousand Five.\nBy the Pre~ident:\n\"\"\n."}}],"pack":"ph-p158"};
