  FT["PH-H20567"] = {"id":"PH-H20567","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT. OF THE PHILIPPINES CLASSIFYING NEWLY ORGANIZED MUNICIPAL ITIES IN: THE PHILIPPINES","orig":"MALACAÑAN PALACE BY THE PRESIDENT. OF THE PHILIPPINES CLASSIFYING NEWLY ORGANIZED MUNICIPAL ITIES IN: THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 583","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00583_1953.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00583_1953.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20567-A1","no":1,"noLabel":{},"text":{"en":"dates said municipalities respectively began to exist, the\nsame to continue until said municipalities shall have been\nreclassified pursuant to the provisions of section 5 of Re-\npublic Act No. 554:\nMunicipalities.\nCatanduanes\nMunicipalities\nNegros Occidental\nSan Francisco\n... .\nBuenavista\nZamboanga del Norte\nZamboanga del Sur\nMountain Province\nDone in the City of Manila, this 4th day of April, in the\nyear of Our Lord, nineteen hundred and fifty-three, and\nof the Independence of the Philippines, the seventli.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\n• MARCIANO 'ROQUE\nActing Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H20568"] = {"id":"PH-H20568","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Reconstituting the Board of Directors of the National Cottage Industries Development Authority","orig":"Reconstituting the Board of Directors of the National Cottage Industries Development Authority"},"level":"law","status":"active","docNumber":"Executive Order No. 583","issuingBody":"President of the Philippines","promulgatedDate":"1980-03-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00583_1980_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00583_1980_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20568-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The Board of Directors of the National Cottage Industries Development Authority is hereby\nreconstituted to be composed of the following or their representatives:\n(1) Minister of Industry as Chairman\n(2) Minister of Trade as Vice-Chairman\n(3) Minister of Human Settlements\n(4) Minister of Education and Culture\n(5) Chairman of the National Manpower and Youth Council\n(6) Governor of the Central Bank of the Philippines\n(7) Chairman of the Development Bank of the Philippines\n(8) Administrator of the National Cottage Industries Development Authority\n(9) Three (3) representatives from the private sector\nThe three (3) members from the private sector shall be appointed by the President for a term of six years:\nProvided, That one shall be initially appointed for a term of six years, one for a term of four years and the\nother one for a term of two years."}},{"id":"PH-H20568-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"All laws, decrees, charters, executive orders, administrative orders, proclamations, rules and\nregulations or parts thereof that are in conflict with this Executive Order are hereby repealed or modified\naccordingly."}},{"id":"PH-H20568-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 18th day of March, in the year of Our Lord, Nineteen Hundred and Eighty."}}],"pack":"ph-p158"};
  FT["PH-H20569"] = {"id":"PH-H20569","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ESTABLISHING THE NATIONAL SCIENCE COMPLEX AND TECHNOLOGY INCUBATION PARK IN THE UNIVERSITY OF THE PHILIPPINES,","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ESTABLISHING THE NATIONAL SCIENCE COMPLEX AND TECHNOLOGY INCUBATION PARK IN THE UNIVERSITY OF THE PHILIPPINES,"},"level":"law","status":"active","docNumber":"Executive Order No. 583","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00583_2006.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00583_2006.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20569-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The National Science Complex. - The National Science\nComplex and Technology Incubation Park is hereby established in a 21.9\nhectare area of the southern sector of the University of the Philippines, Diliman,\nwhich shall be composed of the following Member Institutes:\na. National Institute of Geological Sciences (NIGS)\nb. Marine Science Institute (MSI)\nc. National Institute of Physics (NIP)\nd. National Institute of Molecular Biology and Biotechnology (NIMBB)\ne. Institute of Biology (IB)\nf. Institute of Chemistry (IC)\nq. Institute of Environmental Science and Meteorology (IESM)\nh. Department of Mathematics (DM)\ni. Natural Science Research Institute (NSRI)"}},{"id":"PH-H20569-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Management, Operation and Institution of the National\nScience Complex and Technology Incubation Park. - The UP Board of Regents is\nhereby authorized to organize the abovementioned institutes, and such other\nadditional institutes, centers, departments and laboratories in the future which it\nmay deem proper to create, utilizing the staff, physical facilities and programs of\nthe University and its constituent units as appropriate. It shall issue such rules\nregulations and other issuances as may be necessary to ensure the effective\nimplementation of this Executive Order."}},{"id":"PH-H20569-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Appropriations. - The appropriation for the infrastructure\nof the National Science Complex and Technology Incubation Park, as authorized\nunder Republic Act No. 9358, approved on October 16, 2006, to supplement the\nFY 2006 Budget, under Section 1, C, C.1 thereof, in the amount of Five\nHundred Million Pesos (PhP500,000,000.00) shall be released to UP by the\nDepartment of Budget and Management (DBM) in accordance with budgeting\nlaws, rules and regulations.\nPOMA MeSSIAH • 37653\n\n3"}},{"id":"PH-H20569-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Repealing Clause. - All other executive issuances, rules and\nregulations or parts thereof which are inconsistent with the provisions of this\nExecutive Order are hereby repealed, amended or modified accordingly."}},{"id":"PH-H20569-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity.\nimmediately.\n- This Executive Order shall take effect\nDONE, in the City of Manila, on this 8th day of Decarber in the year of\nour Lord, Two Thousand and Six.\nflorists bugs\nBy the President:\nEDUARDO R. ERMITA\nExecutive Secretary\n12"}}],"pack":"ph-p158"};
  FT["PH-H20570"] = {"id":"PH-H20570","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN. PALACE BY THE PRESIDENT OF THE PHILIPPINES TERMINATING THE COLLECTION OF TOLLS AT THE TUMAUINI BRIDGE, ISABELA","orig":"MALACAÑAN. PALACE BY THE PRESIDENT OF THE PHILIPPINES TERMINATING THE COLLECTION OF TOLLS AT THE TUMAUINI BRIDGE, ISABELA"},"level":"law","status":"active","docNumber":"Executive Order No. 584","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00584_1953.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00584_1953.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20570-A1","no":1,"noLabel":{},"text":{"en":"Done in the City of Manila, this 15th day of April,\nin the year of Our Lord, nineteen hundred and fifty-three,\nand of the Independence of the Philippines, the seventh.\nELPIDIO QUiRINO\nPresident of the Philippines\nBy the President:\nMARCIANO ROQUE\nActing Executive Secretary"}}],"pack":"ph-p158"};
  FT["PH-H20571"] = {"id":"PH-H20571","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Amending Section 10 of Executive Order No. 540 Providing for a Foreign Trade Service Corps in the Ministry of Trade","orig":"Amending Section 10 of Executive Order No. 540 Providing for a Foreign Trade Service Corps in the Ministry of Trade"},"level":"law","status":"active","docNumber":"Executive Order No. 584","issuingBody":"President of the Philippines","promulgatedDate":"1980-03-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00584_1980_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00584_1980_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H20571-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Section 10 of Executive Order No. 540 is hereby amended to read as follows:\n\"Sec. 10. Assignment Abroad of Members of the Foreign Trade Service Corps. The assignment abroad of\nmembers of the Foreign Trade Service Corps shall be made by the Ministry of Trade: Provided, however, That\nthe individual members so assigned shall be with the concurrence of the Ministry of Foreign Affairs and shall\nbe based on the qualifications of the officer to be assigned; Provided, further, That the said officer shall serve\nin a post of assignment for a period of not less than two years and more than six years: Provided, finally, That\nthe determination of the specific places abroad which shall for Foreign Trade Service Corps postings shall be\nmade by the Ministry of Trade, based on such criteria as export potential, availability of export financing,\ncenter for technology transfer, transhipment center, trade policy center and center for strategic imports.\"\nWhenever a Foreign Trade Service Officer is given an assignment abroad, he shall be given the appropriate\ndesignation by the Ministry of Foreign Affairs to enable him to perform his duties and functions effectively:\nProvided, That while he is abroad, he shall be under such administrative supervision of the Head of the\nPhilippine Mission as is provided for in existing applicable laws and rules and such memorandum of\nunderstanding which may be entered into between the Ministry of Trade and Ministry of Foreign Affairs and\nrevised from time to time as necessary."}},{"id":"PH-H20571-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"All laws, rules and regulations which are inconsistent herewith hereby repealed, amended and/or\nmodified accordingly."}},{"id":"PH-H20571-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 18th day of March, in the year of Our Lord, Nineteen Hundred and Eighty."}}],"pack":"ph-p158"};
